    // JS puro) ter sido carregado nesse mesmo arquivo. Tudo acontece dentro
    // do proprio navegador, na mesma sessao do Telegram Web - sem servidor
    // local, sem Python, sem conexao externa de IP pra manter aberta.

    const { TelegramClient, StringSession, PromisedWebSockets, Api } = window.TeleprotoBridge;

    // Numero da versao, pra saber na hora (olhando o topo do painel) se o
    // Tampermonkey ja pegou a atualizacao mais nova ou se ainda esta rodando
    // uma versao antiga - sem isso nao tinha como diferenciar "a correcao
    // nao funcionou" de "o script antigo ainda nao foi atualizado de
    // verdade". window.TRP_VERSAO e definido por montar_userscript.mjs (uma
    // unica fonte da verdade, usada tambem no @version do cabecalho
    // ==UserScript==) - "dev" aqui e so um fallback se alguem rodar
    // painel_logic.js fora do userscript montado.
    const VERSAO_PAINEL = window.TRP_VERSAO || "dev";

    const CHAVE_API_ID = "trp_api_id";
    const CHAVE_API_HASH = "trp_api_hash";
    const CHAVE_SESSAO = "trp_session";
    const CHAVE_GRUPOS_EXCLUIDOS = "trp_grupos_excluidos";
    const CHAVE_HISTORICO_BUSCA_LOCAL = "trp_historico_busca_local";
    const CHAVE_HISTORICO_BUSCA_GLOBAL = "trp_historico_busca_global";

    // So guarda a lista de EXCLUIDOS (nao a de incluidos) - assim, por
    // padrao, tudo entra no scan "Todos", e grupo novo que a conta entrar
    // ja aparece incluido sozinho, sem precisar marcar nada.
    function carregarGruposExcluidos() {
        try {
            return new Set(JSON.parse(GM_getValue(CHAVE_GRUPOS_EXCLUIDOS, "[]")));
        } catch (erro) {
            return new Set();
        }
    }

    function salvarGruposExcluidos(excluidos) {
        GM_setValue(CHAVE_GRUPOS_EXCLUIDOS, JSON.stringify([...excluidos]));
    }

    // ---- Historico de termos buscados (preenchimento automatico do navegador) ----

    function carregarHistoricoBusca(chave) {
        try {
            return JSON.parse(GM_getValue(chave, "[]"));
        } catch (erro) {
            return [];
        }
    }

    // Mais recente primeiro, sem repetir o mesmo termo duas vezes, capado
    // em 20 pra nao crescer pra sempre.
    function salvarTermoNoHistorico(chave, termo) {
        if (!termo) return;
        const historico = carregarHistoricoBusca(chave).filter((t) => t !== termo);
        historico.unshift(termo);
        GM_setValue(chave, JSON.stringify(historico.slice(0, 20)));
    }

    // Tira um termo especifico do historico (pedido do usuario: as vezes um
    // termo digitado errado, ou que nao interessa mais, fica poluindo o
    // autocompletar pra sempre - sem isso so dava pra limpar tudo de uma vez,
    // nunca um item so). Ver telaHistoricoBusca().
    function removerTermoDoHistorico(chave, termo) {
        const historico = carregarHistoricoBusca(chave).filter((t) => t !== termo);
        GM_setValue(chave, JSON.stringify(historico));
    }

    // Liga um <input> de busca a um <datalist> com o historico de termos ja
    // buscados antes (persistido entre sessoes via GM_getValue/GM_setValue) -
    // o proprio navegador mostra isso como sugestao/preenchimento automatico
    // nativo ao digitar, sem precisar de nenhum componente customizado.
    // "Capricho" pedido pelo usuario - simples de fazer com HTML puro (sem
    // essa lista, cada busca comeca sempre do zero, sem nenhum lembrete do
    // que ja foi pesquisado antes).
    let contadorDatalistHistorico = 0;
    function ligarHistoricoBusca(input, chave) {
        const idDatalist = "trp-historico-" + contadorDatalistHistorico++;
        const datalist = document.createElement("datalist");
        datalist.id = idDatalist;
        input.insertAdjacentElement("afterend", datalist);
        input.setAttribute("list", idDatalist);

        function repopular() {
            datalist.innerHTML = "";
            for (const termo of carregarHistoricoBusca(chave)) {
                const opcao = document.createElement("option");
                opcao.value = termo;
                datalist.appendChild(opcao);
            }
        }
        repopular();

        return {
            registrar(termo) {
                salvarTermoNoHistorico(chave, termo);
                repopular();
            },
        };
    }

    // Banco MINUSCULO so pra guardar o handle da pasta de armazenamento
    // escolhida (ver bloco "Armazenamento em disco" abaixo) - NAO e mais
    // onde as mensagens moram (isso agora e a pasta real no disco). Um
    // FileSystemDirectoryHandle e "structured-cloneable", entao da pra
    // guardar ele direto numa linha do IndexedDB, exatamente como qualquer
    // outro objeto - e o jeito oficialmente suportado de lembrar uma pasta
    // escolhida entre sessoes (https://developer.chrome.com/articles/file-system-access).
    const NOME_BANCO_CONFIG = "GestorTLGR_Config";
    const VERSAO_BANCO_CONFIG = 1;

    let cliente = null; // instancia conectada, reaproveitada entre aberturas do painel
    let painel = null;
    let botaoFlutuante = null; // o "TLGMaster" fixo na pagina (mostra o numero de novas dos Monitorados)
    let areaRolavel = null; // unico filho de painel que de fato rola - ver montarPainel()
    let bancoPromessa = null;
    let pastaDeArmazenamento = null; // FileSystemDirectoryHandle confirmado NESTA sessao (ver garantirPastaDeArmazenamento)
    let scanEmAndamento = false;
    let cancelarScanSolicitado = false;

    // Qual tela de "Escanear" (ver telaScanner) esta registrada pra RECEBER
    // status/atualizacao de tabela agora - nunca "quem comecou o scan".
    // Sem isso, abrir o painel, iniciar um scan, navegar pra outra tela e
    // voltar pra "Escanear" deixava a tela nova com "Scan ja esta
    // rodando..." congelado pra sempre: os callbacks de status/tabela
    // continuavam presos nos elementos da ABERTURA ANTERIOR (ja fora do
    // DOM, invisivel), e a nova abertura nunca recebia nenhuma atualizacao
    // dali em diante, nem mesmo a mensagem final de "scan completo".
    // escanearTudo() (e o clique de "Iniciar scan") sempre notificam quem
    // estiver registrado AQUI no momento, e toda abertura de telaScanner()
    // se registra de novo, substituindo a anterior.
    //
    // notificarFimScan() cobre a MESMA situacao pro lado dos botoes: antes,
    // o "finally" do clique em "Iniciar scan" resetava diretamente os
    // botoes/select da abertura que CHAMOU escanearTudo() - se enquanto isso
    // o usuario tivesse navegado pra outra tela e voltado (como no caso
    // acima), a abertura visivel na tela (a mais recente) nunca tinha seus
    // botoes resetados: "Iniciar scan de novo" ficava preso desabilitado
    // dizendo "Escaneando..." e o botao "Parar" continuava visivel pra
    // sempre, mesmo com o status ja mostrando "Scan completo...". Por isso
    // o reset de botoes tambem passa a ser dirigido pra quem estiver
    // registrado AQUI no momento em que o scan termina, igual status/tabela.
    let visualizacaoScanAtiva = null;
    function registrarVisualizacaoScanAtiva(visualizacao) {
        visualizacaoScanAtiva = visualizacao;
    }
    function notificarStatusScan(texto) {
        if (visualizacaoScanAtiva) visualizacaoScanAtiva.atualizarStatus(texto);
    }
    async function notificarAtualizacaoChatScan() {
        if (visualizacaoScanAtiva) await visualizacaoScanAtiva.aoAtualizarChat();
    }
    async function notificarFimScan() {
        if (visualizacaoScanAtiva && visualizacaoScanAtiva.aoTerminarScan) {
            await visualizacaoScanAtiva.aoTerminarScan();
        }
    }
    let dadosDaContaEmCache = null; // { cliente, eu } - ver telaLogado

    // ---- Armazenamento em disco (File System Access API) ----
    //
    // Substitui o IndexedDB como motor de armazenamento das mensagens/chats.
    // Motivo: o IndexedDB vive so na cota interna do navegador - um scan
    // grande acumulou ~10GB e travou o navegador a ponto de precisar
    // "limpar dados do navegador" (que apaga tudo, sem aviso previo). Os
    // dados agora moram numa pasta REAL no disco, escolhida uma vez pelo
    // usuario (pode ser dentro do OneDrive/Google Drive sincronizado - a
    // nuvem acontece de graca pelo cliente de sincronizacao do Windows,
    // sem a gente escrever nenhuma integracao de API de nuvem).
    //
    // So funciona em navegador da familia Chromium (Chrome, Edge) - a File
    // System Access API nao existe no Firefox.
    //
    // Formato dentro da pasta escolhida:
    //   chats.json                - array com o registro de cada chat
    //                                (pequeno, reescrito inteiro a cada
    //                                mudanca - nunca passa de um punhado de
    //                                KB mesmo com centenas de grupos)
    //   indice.jsonl               - log so-acrescenta, uma linha por
    //                                "versao" de cada mensagem, SO com os
    //                                campos leves (sem "texto"/"reactions") -
    //                                carregado inteiro em memoria 1x por
    //                                sessao (abrirBanco()) e mantido
    //                                atualizado dali em diante sem reler do
    //                                disco - e o que faz "Top reacoes"
    //                                responder na hora mesmo com milhoes de
    //                                mensagens
    //   mensagens/<chatId>.jsonl    - log so-acrescenta por chat, com o
    //                                registro COMPLETO (inclui "texto" sem
    //                                corte) - so lido quando alguma consulta
    //                                precisa do texto de um chat especifico
    //                                (buscarTexto, buscarMensagem, backup),
    //                                e so uma vez por chat por sessao
    //                                (cache em db.textoCompletoPorChat)
    //
    // "So-acrescenta com ultima linha vencendo por key": NUNCA edita uma
    // linha ja escrita - so acrescenta uma nova com a mesma "key" quando
    // algo muda (reactionTotal atualizado numa rescaneada, "visto"
    // marcado). Quem le sempre fica com a ULTIMA ocorrencia de cada key
    // (repetirJsonlUltimaVence). Isso evita ter que reescrever um arquivo
    // de gigabytes so pra marcar uma caixinha - e tem exatamente a mesma
    // semantica do IndexedDB put() que essa troca substitui.
    //
    // Confirmado em teste real (Chromium via Playwright, ANTES de escrever
    // este codigo): dois createWritable() abertos ao mesmo tempo no MESMO
    // arquivo nao dao nenhum erro - um deles so perde silenciosamente o
    // que escreveu quando o outro fecha por cima. Por isso toda escrita
    // passa pela fila abaixo (enfileirarEscrita) - nunca duas ao mesmo
    // tempo no mesmo caminho.

    const filaDeEscrita = new Map(); // caminho relativo (string) -> promessa da ultima escrita ja enfileirada nesse caminho

    // Quantas escritas ja foram pedidas por caminho (so cresce) - usado pela
    // compactacao pra saber se alguma escrita comecou depois que ela leu o
    // arquivo (ver compactarArquivoSeValerAPena).
    const escritasPedidasPorCaminho = new Map();

    function enfileirarEscrita(caminho, tarefa) {
        escritasPedidasPorCaminho.set(caminho, (escritasPedidasPorCaminho.get(caminho) || 0) + 1);
        const anterior = filaDeEscrita.get(caminho) || Promise.resolve();
        const atual = anterior.then(tarefa, tarefa); // roda mesmo se a anterior falhou - um arquivo com problema nao trava os outros pra sempre
        filaDeEscrita.set(
            caminho,
            atual.then(
                () => {},
                () => {}
            )
        );
        return atual; // quem chamou AINDA recebe o erro de verdade daqui, se houver
    }

    async function obterHandleArquivo(pastaRaiz, caminhoRelativo, criar) {
        const partes = caminhoRelativo.split("/");
        let pasta = pastaRaiz;
        for (let i = 0; i < partes.length - 1; i++) {
            pasta = await pasta.getDirectoryHandle(partes[i], { create: !!criar });
        }
        return pasta.getFileHandle(partes[partes.length - 1], { create: !!criar });
    }

    async function lerArquivoTexto(pastaRaiz, caminhoRelativo) {
        try {
            const handle = await obterHandleArquivo(pastaRaiz, caminhoRelativo, false);
            return await (await handle.getFile()).text();
        } catch (erro) {
            if (erro && erro.name === "NotFoundError") return null; // arquivo/pasta ainda nao existe - primeira vez
            throw erro;
        }
    }

    function anexarArquivoTexto(pastaRaiz, caminhoRelativo, textoNovo) {
        return enfileirarEscrita(caminhoRelativo, async () => {
            const handle = await obterHandleArquivo(pastaRaiz, caminhoRelativo, true);
            const tamanhoAtual = (await handle.getFile()).size;
            const writable = await handle.createWritable({ keepExistingData: true });
            await writable.write({ type: "write", position: tamanhoAtual, data: textoNovo });
            await writable.close();
        });
    }

    function sobrescreverArquivoTexto(pastaRaiz, caminhoRelativo, conteudo) {
        return enfileirarEscrita(caminhoRelativo, async () => {
            const handle = await obterHandleArquivo(pastaRaiz, caminhoRelativo, true);
            const writable = await handle.createWritable(); // sem keepExistingData = trunca certo, inclusive quando o conteudo novo e menor que o antigo (testado)
            await writable.write(conteudo);
            await writable.close();
        });
    }

    // Repete um arquivo .jsonl (uma linha = um JSON) mantendo so a ULTIMA
    // ocorrencia de cada valor de "nomeDaChave" - ver comentario no topo
    // deste bloco. Linha corrompida (ex.: escrita interrompida no meio por
    // fechar o navegador no instante errado) e ignorada em vez de quebrar
    // a leitura do arquivo inteiro.
    function repetirJsonlUltimaVence(texto, nomeDaChave) {
        const porChave = new Map();
        porChave.linhasLidas = 0;
        if (texto) {
            for (const linha of texto.split("\n")) {
                if (!linha.trim()) continue;
                porChave.linhasLidas++;
                try {
                    const registro = JSON.parse(linha);
                    porChave.set(registro[nomeDaChave], registro);
                } catch (erro) {
                    // linha corrompida - ignora so essa linha, nao o arquivo todo
                }
            }
        }
        return porChave;
    }

    // Reescreve um .jsonl so com a ultima versao de cada chave quando ele
    // tem muitas linhas repetidas (cada reescaneamento e cada "visto"
    // acrescenta uma linha nova pra mesma mensagem, e nada nunca apagava as
    // antigas). Arquivo menor = abre mais rapido e cada anexo copia menos
    // (ver "Gravacao em lote"). Seguro contra perder linha: so compacta se
    // nenhuma escrita nesse arquivo foi pedida desde a leitura
    // (escritasPedidasAntes) e se nao ha linha pendente pra ele; a
    // reescrita entra na fila do arquivo, entao qualquer anexo pedido
    // depois vai pro arquivo ja compactado. createWritable so troca o
    // arquivo no close(): se o navegador fechar no meio, o antigo fica.
    const MINIMO_LINHAS_PARA_COMPACTAR = 20000;
    function compactarArquivoSeValerAPena(db, caminho, mapa, escritasPedidasAntes) {
        const linhas = mapa.linhasLidas || 0;
        if (linhas < MINIMO_LINHAS_PARA_COMPACTAR || linhas < mapa.size * 1.5) return null;
        if ((escritasPedidasPorCaminho.get(caminho) || 0) !== escritasPedidasAntes) return null;
        if (db.escritasPendentes && db.escritasPendentes.get(caminho)) return null;
        const partes = [];
        for (const registro of mapa.values()) partes.push(JSON.stringify(registro));
        console.log("[TLGMaster] compactando", caminho, "de", linhas, "pra", mapa.size, "linhas");
        return sobrescreverArquivoTexto(db.pasta, caminho, partes.join("\n") + "\n").catch((erro) =>
            console.warn("[TLGMaster] erro ao compactar " + caminho, erro)
        );
    }

    // ---- Escolha/permissao da pasta (config minuscula, IndexedDB) ----

    function abrirBancoConfig() {
        return new Promise((resolve, reject) => {
            const pedido = indexedDB.open(NOME_BANCO_CONFIG, VERSAO_BANCO_CONFIG);
            pedido.onupgradeneeded = () => {
                const db = pedido.result;
                if (!db.objectStoreNames.contains("config")) {
                    db.createObjectStore("config", { keyPath: "chave" });
                }
            };
            pedido.onsuccess = () => resolve(pedido.result);
            pedido.onerror = () => reject(pedido.error);
        });
    }

    // Handles de pasta guardados no banco de config: "pastaArmazenamento"
    // (pasta de dados) e, desde a rodada 4, "pastaDownloads" (pasta
    // opcional so pros arquivos baixados - Configuracoes > Downloads).
    async function lerHandleSalvo(chave) {
        const dbConfig = await abrirBancoConfig();
        return new Promise((resolve, reject) => {
            const pedido = dbConfig.transaction("config", "readonly").objectStore("config").get(chave);
            pedido.onsuccess = () => resolve(pedido.result ? pedido.result.handle : null);
            pedido.onerror = () => reject(pedido.error);
        });
    }

    async function salvarHandle(chave, handle) {
        const dbConfig = await abrirBancoConfig();
        return new Promise((resolve, reject) => {
            const pedido = dbConfig.transaction("config", "readwrite").objectStore("config").put({ chave, handle });
            pedido.onsuccess = () => resolve();
            pedido.onerror = () => reject(pedido.error);
        });
    }

    function lerPastaSalva() {
        return lerHandleSalvo("pastaArmazenamento");
    }

    function salvarPastaEscolhida(handle) {
        return salvarHandle("pastaArmazenamento", handle);
    }

    // Confere se ja temos uma pasta de verdade, com permissao de
    // leitura/escrita, pronta pra usar - SEM pedir nada ao usuario (so
    // queryPermission, nunca requestPermission aqui, porque esse exige
    // gesto do usuario e lancaria erro se chamado sozinho). Devolve null
    // quando precisa de um clique (primeira vez, ou permissao revogada) -
    // quem chama (telaLogado) decide mostrar a tela de escolha nesse caso.
    async function garantirPastaDeArmazenamento() {
        if (pastaDeArmazenamento) {
            const permissao = await pastaDeArmazenamento.queryPermission({ mode: "readwrite" });
            if (permissao === "granted") return pastaDeArmazenamento;
        }
        const salva = await lerPastaSalva().catch(() => null);
        if (salva) {
            const permissao = await salva.queryPermission({ mode: "readwrite" }).catch(() => "denied");
            if (permissao === "granted") {
                pastaDeArmazenamento = salva;
                return salva;
            }
        }
        return null;
    }

    // So pode ser chamada a partir de um clique de verdade do usuario
    // (showDirectoryPicker e requestPermission exigem gesto - chamar fora
    // de um clique lanca erro "must be handling a user gesture").
    async function escolherPastaDeArmazenamento() {
        const handle = await window.showDirectoryPicker({ mode: "readwrite" });
        return usarPastaDeArmazenamento(handle);
    }

    async function usarPastaDeArmazenamento(handle) {
        await salvarPastaEscolhida(handle);
        pastaDeArmazenamento = handle;
        bancoPromessa = null; // forca abrirBanco() a carregar do zero com a pasta nova
        return handle;
    }

    // Mesma pasta de sempre (handle salvo), so reconfirmando a permissao
    // que o navegador revogou (acontece depois de reiniciar o navegador as
    // vezes - trava de seguranca do proprio navegador, nao da pra evitar,
    // so pra isso que existe esse segundo caminho em vez de sempre abrir o
    // seletor de pasta de novo).
    async function reconfirmarPermissaoPasta(handle) {
        const permissao = await handle.requestPermission({ mode: "readwrite" });
        if (permissao !== "granted") {
            throw new Error("Permissão de acesso à pasta negada.");
        }
        pastaDeArmazenamento = handle;
        bancoPromessa = null;
        return handle;
    }

    // ---- Leitura/escrita de alto nivel - mesmas assinaturas de antes ----
    //
    // abrirBanco() devolve um objeto com tres coisas em memoria: a pasta
    // escolhida, um Map com o metadado de cada chat (de chats.json) e um
    // Map com o indice leve de toda mensagem (de indice.jsonl). As duas
    // listas inteiras cabem tranquilamente em memoria mesmo com uma conta
    // bem usada (sao so numeros/datas/titulos, nunca o texto completo).
    function abrirBanco() {
        if (bancoPromessa) return bancoPromessa;
        bancoPromessa = (async () => {
            if (!pastaDeArmazenamento) {
                throw new Error("Pasta de armazenamento ainda não foi escolhida.");
            }
            const pasta = pastaDeArmazenamento;
            const chats = new Map();
            const textoChats = await lerArquivoTexto(pasta, "chats.json");
            if (textoChats) {
                try {
                    for (const registro of JSON.parse(textoChats)) chats.set(registro.chatId, registro);
                } catch (erro) {
                    // chats.json corrompido/vazio - comeca do zero em vez de travar o painel inteiro
                }
            }
            const escritasNoIndiceAntes = escritasPedidasPorCaminho.get("indice.jsonl") || 0;
            const textoIndice = await lerArquivoTexto(pasta, "indice.jsonl");
            const indice = repetirJsonlUltimaVence(textoIndice, "key");
            const contagemPorChat = new Map(); // chatId -> mensagens no indice (mantido em salvarMensagem)
            for (const registro of indice.values()) {
                contagemPorChat.set(registro.chatId, (contagemPorChat.get(registro.chatId) || 0) + 1);
            }
            const remetentes = new Map();
            const textoRemetentes = await lerArquivoTexto(pasta, "remetentes.json").catch(() => null);
            if (textoRemetentes) {
                try {
                    for (const [id, dados] of Object.entries(JSON.parse(textoRemetentes))) remetentes.set(id, dados);
                } catch (erro) {
                    // corrompido: recomeca (so nomes, o scan preenche de novo)
                }
            }
            const db = {
                pasta,
                chats,
                indice,
                remetentes,
                contagemPorChat,
                textoCompletoPorChat: new Map(),
                escritasPendentes: new Map(),
                linhasPendentes: 0,
            };
            db.compactacaoDoIndice = compactarArquivoSeValerAPena(db, "indice.jsonl", indice, escritasNoIndiceAntes);
            await carregarFavoritos(db); // ehFavorito() e sincrono nas listas
            await carregarMonitorados(db); // estaMonitorado() tambem
            return db;
        })();
        return bancoPromessa;
    }

    // ---- Gravacao em lote (scan e importacao de backup) ----
    //
    // Medido num Chromium real (Playwright + OPFS, mesma API de arquivo que
    // a pasta escolhida usa): createWritable({keepExistingData: true}) faz o
    // navegador COPIAR o arquivo inteiro pra um arquivo temporario (.crswap)
    // antes de cada escrita - anexar 1 linha num arquivo de 20 MB levou
    // ~130 ms, de 100 MB ~600 ms, de 200 MB ~1,2 s. Antes, o scan anexava
    // 2 linhas POR MENSAGEM (indice.jsonl + mensagens/<chat>.jsonl), entao
    // o custo de cada mensagem crescia junto com o tamanho do indice - o
    // scan ficava cada vez mais lento, ate parecer travado. Ver
    // HISTORICO_TECNICO.md (auditoria 2026-10).
    //
    // Agora o scan e a importacao juntam as linhas em memoria
    // (db.escritasPendentes, caminho -> lista de linhas) e gravam tudo de
    // uma vez em descarregarEscritasPendentes(): 1 copia por arquivo a cada
    // checkpoint (INTERVALO_CHECKPOINT_SCAN mensagens), nao 1 por mensagem.
    //
    // Regra que mantem o checkpoint consistente: o checkpoint de um chat
    // (lastScannedMessageId/textoCompletoAte em chats.json) so e gravado
    // DEPOIS de descarregar as mensagens pendentes (ver salvarCheckpoint em
    // escanearTudo). Se o navegador fechar no meio, o que estava pendente
    // se perde, mas o checkpoint tambem nao avancou - o proximo scan pega
    // essas mensagens de novo ("ultima linha vence" torna isso inofensivo).
    const LIMITE_LINHAS_PENDENTES = 10000; // teto de memoria: descarrega sozinho se passar disso entre checkpoints (scan faz checkpoint a cada 2000 mensagens = 4000 linhas)

    function adiarAnexo(db, caminho, linha) {
        let linhas = db.escritasPendentes.get(caminho);
        if (!linhas) {
            linhas = [];
            db.escritasPendentes.set(caminho, linhas);
        }
        linhas.push(linha);
        db.linhasPendentes++;
    }

    // Grava tudo que esta pendente. Troca o Map ANTES de gravar, pra uma
    // mensagem salva durante a gravacao entrar no proximo lote, nunca se
    // perder. A ordem por caminho e preservada pela fila de
    // enfileirarEscrita (o lote entra na fila antes de qualquer escrita
    // pedida depois dele).
    async function descarregarEscritasPendentes(db) {
        if (db.remetentesMudou) {
            db.remetentesMudou = false;
            // Outra aba pode ter gravado nomes que esta nao conhece: junta
            // antes de regravar (o desta aba vence, e o mais recente aqui).
            try {
                const doDisco = JSON.parse((await lerArquivoTexto(db.pasta, "remetentes.json")) || "{}");
                for (const [id, dados] of Object.entries(doDisco)) if (!db.remetentes.has(id)) db.remetentes.set(id, dados);
            } catch (erro) {
                // arquivo corrompido: regrava so o desta aba
            }
            const conteudo = JSON.stringify(Object.fromEntries(db.remetentes));
            await sobrescreverArquivoTexto(db.pasta, "remetentes.json", conteudo).catch((erro) => {
                db.remetentesMudou = true;
                console.warn("[TLGMaster] remetentes.json:", erro);
            });
        }
        if (!db.escritasPendentes || !db.escritasPendentes.size) return;
        const lote = db.escritasPendentes;
        db.escritasPendentes = new Map();
        db.linhasPendentes = 0;
        await Promise.all(
            [...lote].map(([caminho, linhas]) => anexarArquivoTexto(db.pasta, caminho, linhas.join("")))
        );
    }

    async function persistirChats(db) {
        await sobrescreverArquivoTexto(db.pasta, "chats.json", JSON.stringify([...db.chats.values()]));
    }

    async function salvarChat(db, registro) {
        db.chats.set(registro.chatId, registro);
        await persistirChats(db);
    }

    function buscarChat(db, chatId) {
        return db.chats.get(chatId) || null;
    }

    function listarChats(db) {
        return [...db.chats.values()];
    }

    // So os campos leves, sem "texto" nem "reactions" - o que vai pro
    // indice.jsonl (carregado inteiro em memoria, precisa ficar pequeno).
    // Excecao (rodada 4): mensagem COM reacao leva um trecho curto do texto
    // ("trecho", 100 caracteres) - Top reacoes e Minhas reacoes so leem o
    // indice e, desde a troca pro disco, mostravam a mensagem sem texto
    // nenhum. Mensagem com reacao e minoria, entao o indice cresce pouco;
    // as outras tem o texto lido do arquivo do chat so quando aparecem na
    // tela (preencherTrechosQueFaltam).
    const TAMANHO_TRECHO_NO_INDICE = 100;
    function registroLeve(registro) {
        const { texto, reactions, trecho, ...leve } = registro;
        if ((registro.reactionTotal || 0) > 0 && texto) leve.trecho = texto.slice(0, TAMANHO_TRECHO_NO_INDICE);
        return leve;
    }

    // Conjunto de chatId que tem algum dado salvo - usado por
    // buscarTexto/gerarPedacosDoBackup pra decidir quais chats varrer.
    // NAO basta usar so db.chats.keys(): "chats" so e persistido no
    // primeiro checkpoint do scan (salvarCheckpoint, a cada INTERVALO_CHECKPOINT_SCAN mensagens
    // OU no fim de uma fase - ver escanearTudo), enquanto o indice e
    // atualizado a CADA mensagem salva (salvarMensagem). Um chat novo, nos
    // primeiros segundos de um scan em andamento, ja tem mensagens no
    // indice mas ainda nao tem registro em "chats" - sem isso, a busca por
    // texto (e o backup) simplesmente ignorariam esse chat ate o primeiro
    // checkpoint, um bug real encontrado pelo teste automatizado ao migrar
    // do IndexedDB (onde a busca varria a store de mensagens direto, sem
    // depender da store de chats).
    function idsDeChatsComDados(db) {
        const ids = new Set(db.chats.keys());
        for (const chatId of db.contagemPorChat.keys()) ids.add(chatId);
        return ids;
    }

    // Le (do cache em memoria, se ja carregado; senao do disco, 1x) o Map
    // completo de mensagens (com "texto") de UM chat especifico. Usado por
    // buscarTexto/buscarMensagem - nunca por
    // buscarTop/buscarTopPorData, que resolvem tudo so com o indice leve.
    // Cache com teto de memoria: guarda o texto completo dos chats lidos
    // ate somar LIMITE_CACHE_TEXTO_CARACTERES de JSON lido do disco; passou
    // disso, descarta o chat usado ha mais tempo (ordem do Map = ordem de
    // uso, cada acesso move o chat pro fim). Antes ou guardava tudo pra
    // sempre (risco de estourar a memoria em "Todos os grupos") ou, depois
    // da auditoria anterior, nao guardava nada em "Todos" (cada busca relia
    // GBs do disco).
    const LIMITE_CACHE_TEXTO_CARACTERES = 150 * 1000 * 1000;
    async function obterMensagensCompletasDoChat(db, chatId) {
        const emCache = db.textoCompletoPorChat.get(chatId);
        if (emCache) {
            db.textoCompletoPorChat.delete(chatId);
            db.textoCompletoPorChat.set(chatId, emCache);
            return emCache;
        }
        const mapa = await lerMensagensDoChatSemCache(db, chatId);
        db.textoCompletoPorChat.set(chatId, mapa);
        db.caracteresEmCache = (db.caracteresEmCache || 0) + mapa.caracteresLidos;
        for (const [idAntigo, mapaAntigo] of db.textoCompletoPorChat) {
            if (db.caracteresEmCache <= (db.limiteCacheTexto || LIMITE_CACHE_TEXTO_CARACTERES) || idAntigo === chatId) break;
            db.textoCompletoPorChat.delete(idAntigo);
            db.caracteresEmCache -= mapaAntigo.caracteresLidos;
        }
        return mapa;
    }

    // Le o arquivo do chat e aplica por cima as linhas ainda pendentes de
    // gravacao (ver "Gravacao em lote") - sem isso, abrir uma busca durante
    // um scan deixaria de fora as ultimas mensagens ainda nao gravadas.
    async function lerMensagensDoChatSemCache(db, chatId) {
        const caminho = "mensagens/" + chatId + ".jsonl";
        const escritasAntes = escritasPedidasPorCaminho.get(caminho) || 0;
        const texto = await lerArquivoTexto(db.pasta, caminho);
        const pendentes = db.escritasPendentes && db.escritasPendentes.get(caminho);
        const conteudo = pendentes ? (texto || "") + pendentes.join("") : texto;
        const mapa = repetirJsonlUltimaVence(conteudo, "key");
        mapa.caracteresLidos = conteudo ? conteudo.length : 0;
        if (!pendentes) compactarArquivoSeValerAPena(db, caminho, mapa, escritasAntes);
        return mapa;
    }

    // Busca uma mensagem especifica pela chave (chatId:messageId) - usado
    // pela conferencia de link da Busca avancada pra checar se algo que apareceu na
    // busca nativa do Telegram esta (ou nao) no nosso banco local. O
    // chatId nunca tem ":" (ver idBaseDoChatId), entao cortar no ULTIMO
    // ":" da chave sempre isola o chatId certo.
    async function buscarMensagem(db, key) {
        const chatId = key.slice(0, key.lastIndexOf(":"));
        const mapa = await obterMensagensCompletasDoChat(db, chatId);
        return mapa.get(key) || null;
    }

    // Monta o backup em PEDACOS (um por chat) em vez de um objeto unico
    // passado pro JSON.stringify: antes o texto de todas as mensagens
    // virava uma string so na memoria, o que com historico grande passa
    // do limite de tamanho de string do navegador. Com
    // showSaveFilePicker (Chrome/Edge) cada pedaco vai direto pro arquivo
    // escolhido; sem ele, os pedacos viram um Blob (sem juntar numa
    // string). O formato do arquivo e o mesmo de antes.
    async function gerarPedacosDoBackup(db, aoGerarPedaco, aoProgresso) {
        const chats = listarChats(db);
        await aoGerarPedaco(
            '{"formato":"gestor-tlgr-backup","versaoApp":' +
                JSON.stringify(VERSAO_PAINEL) +
                ',"geradoEm":' +
                JSON.stringify(new Date().toISOString()) +
                ',"chats":' +
                JSON.stringify(chats) +
                ',"mensagens":['
        );
        let totalMensagens = 0;
        let primeiro = true;
        const idsDosChats = [...idsDeChatsComDados(db)];
        for (let i = 0; i < idsDosChats.length; i++) {
            if (aoProgresso) aoProgresso(`Exportando grupo ${i + 1} de ${idsDosChats.length}...`);
            const mapa = await lerMensagensDoChatSemCache(db, idsDosChats[i]);
            const linhas = [];
            for (const registro of mapa.values()) linhas.push(JSON.stringify(comVistoDoIndice(db, registro)));
            if (!linhas.length) continue;
            await aoGerarPedaco((primeiro ? "" : ",") + linhas.join(","));
            primeiro = false;
            totalMensagens += linhas.length;
        }
        await aoGerarPedaco("]}");
        return { totalChats: chats.length, totalMensagens };
    }

    // opcoes.adiarGravacao = true: so guarda a linha em memoria (ver
    // "Gravacao em lote" acima) - quem passa isso (scan, importacao) tem
    // que chamar descarregarEscritasPendentes() depois. Sem a opcao, grava
    // na hora (marcar visto, busca ao vivo), descarregando junto qualquer
    // lote pendente pra manter a ordem das linhas no arquivo.
    // Quem quer saber de mensagem que acabou de entrar no banco (scan,
    // busca ao vivo, Monitorados) se registra aqui: (db, registro) -> nada.
    // So mensagem NOVA (que nao estava no indice) - rescanear nao repete.
    const aoSalvarMensagemNova = [];

    async function salvarMensagem(db, registro, opcoes) {
        const leve = registroLeve(registro);
        const eraNova = !db.indice.has(registro.key);
        if (eraNova) {
            db.contagemPorChat.set(registro.chatId, (db.contagemPorChat.get(registro.chatId) || 0) + 1);
        }
        db.indice.set(registro.key, leve);
        if (eraNova) {
            for (const avisar of aoSalvarMensagemNova) {
                try {
                    avisar(db, registro);
                } catch (erro) {
                    console.warn("[TLGMaster] aviso de mensagem nova:", erro);
                }
            }
        }
        const cacheDoChat = db.textoCompletoPorChat.get(registro.chatId);
        if (cacheDoChat) cacheDoChat.set(registro.key, registro); // mantem o cache (se ja carregado) atualizado, nunca deixa ele ficar velho
        adiarAnexo(db, "mensagens/" + registro.chatId + ".jsonl", JSON.stringify(registro) + "\n");
        adiarAnexo(db, "indice.jsonl", JSON.stringify(leve) + "\n");
        if (!(opcoes && opcoes.adiarGravacao) || db.linhasPendentes >= LIMITE_LINHAS_PENDENTES) {
            await descarregarEscritasPendentes(db);
        }
    }

    // Monta o registro de uma mensagem vinda do scan. "visto" e um campo so
    // nosso (marcado a mao pelo usuario) que o Telegram nao manda - sem
    // copiar ele do registro anterior, reescanear (forcar reescaneamento,
    // backfill) apagava todas as marcacoes de "ja visto" daquele chat.
    function montarRegistroDoScan(db, chatId, chatTitle, mensagem) {
        const key = chatId + ":" + mensagem.id;
        const registro = {
            key,
            chatId,
            messageId: mensagem.id,
            dateUtc: dataIso(mensagem),
            texto: textoCompleto(mensagem),
            chatTitle,
        };
        aplicarDadosDaMensagem(registro, mensagem);
        registrarRemetente(db, mensagem);
        const anterior = db.indice.get(key);
        if (anterior && anterior.visto) registro.visto = true;
        return registro;
    }

    // Campos que vem da mensagem do Telegram e vao pro indice leve (rodada
    // 4): autor ("de", id no formato da Bot API: pessoa = numero positivo,
    // canal/grupo = -100...), resumo das reacoes por emoji (pra mostrar e
    // filtrar sem ler o arquivo do chat), tipo de midia, se o texto cita
    // link e a assinatura do post (canal, admin anonimo). Mensagem salva
    // antes desta versao nao tem esses campos ate ser escaneada de novo (ou
    // atualizada pelo servidor - "Atualizar reacoes" / Monitorados).
    // Usado pelo scan e por todo lugar que salva mensagem vinda do servidor.
    function aplicarDadosDaMensagem(registro, mensagem) {
        const { reactions, total, minhasReacoes } = extrairReacoes(mensagem);
        registro.reactionTotal = total;
        registro.reactions = reactions;
        registro.minhasReacoes = minhasReacoes;
        if (reactions.length) registro.emojis = reactions.map((r) => [r.emoji, r.count]);
        else delete registro.emojis;
        const de = idDoAutor(mensagem);
        if (de) registro.de = de;
        const tipo = typeof tipoDaMidia === "function" ? tipoDaMidia(mensagem) : null;
        if (tipo) registro.midia = tipo;
        else delete registro.midia;
        if (REGEX_TEM_LINK.test(mensagem.message || "")) registro.link = true;
        else delete registro.link;
        if (mensagem.postAuthor) registro.assinatura = String(mensagem.postAuthor).slice(0, 64);
        return registro;
    }

    // Id do autor no formato da Bot API (o mesmo do chatId): pessoa =
    // "123", canal/supergrupo = "-100123", grupo basico = "-123". O
    // teleproto ja calcula isso em mensagem.senderId (from_id; em post de
    // canal, o proprio canal). Sem teleproto (objeto cru da API), olha o
    // fromId.
    function idDoAutor(mensagem) {
        if (mensagem.senderId != null) return String(mensagem.senderId);
        const de = mensagem.fromId;
        if (!de) return null;
        if (de.userId != null) return String(de.userId);
        if (de.channelId != null) return "-100" + String(de.channelId);
        if (de.chatId != null) return "-" + String(de.chatId);
        return null;
    }

    // Nome atual de quem mandou (pessoa ou canal), guardado em
    // remetentes.json na pasta (id -> { n: nome, u: @usuario, c: canal?,
    // h: access hash quando o Telegram manda um completo, a: nomes
    // anteriores }). Serve pra achar a pessoa pelo nome (Monitorados) e
    // mostrar o nome atual sem pedir nada ao Telegram. Gravado junto com o
    // lote de mensagens (descarregarEscritasPendentes), so quando mudou.
    function registrarRemetente(db, mensagem) {
        const entidade = mensagem.sender || mensagem._sender;
        const de = idDoAutor(mensagem);
        if (!de || !entidade || !db.remetentes) return;
        atualizarRemetente(db, de, entidade);
    }

    function nomeDaEntidade(entidade) {
        if (!entidade) return "";
        if (entidade.title) return String(entidade.title);
        return [entidade.firstName, entidade.lastName].filter(Boolean).join(" ").trim() || (entidade.deleted ? "(conta apagada)" : "(sem nome)");
    }

    function atualizarRemetente(db, id, entidade) {
        const anterior = db.remetentes.get(id);
        const nome = nomeDaEntidade(entidade);
        const usuario = entidade.username || (entidade.usernames && entidade.usernames[0] && entidade.usernames[0].username) || "";
        const ehCanal = entidade.className === "Channel" || entidade.className === "Chat" || !!entidade.title;
        const hash = !entidade.min && entidade.accessHash != null ? String(entidade.accessHash) : null;
        if (anterior && anterior.n === nome && (anterior.u || "") === usuario && (!hash || anterior.h === hash)) return;
        const novo = { n: nome };
        if (usuario) novo.u = usuario;
        if (ehCanal) novo.c = true;
        if (hash) novo.h = hash;
        else if (anterior && anterior.h) novo.h = anterior.h;
        const anteriores = (anterior && anterior.a) || [];
        if (anterior && anterior.n && anterior.n !== nome) novo.a = [anterior.n, ...anteriores.filter((n) => n !== anterior.n && n !== nome)].slice(0, 5);
        else if (anteriores.length) novo.a = anteriores;
        db.remetentes.set(id, novo);
        db.remetentesMudou = true;
    }

    // Marca (ou desmarca) uma mensagem como "ja vista" - controle 100%
    // manual do usuario. Grava SO no indice leve (uma linha pequena em
    // indice.jsonl): antes lia o arquivo inteiro do chat (pode ter centenas
    // de MB) so pra regravar a mensagem completa com um campo a mais. O
    // indice passa a ser a fonte da verdade do "visto" - quem le mensagem
    // completa do arquivo do chat (buscarTexto, backup) aplica o "visto" do
    // indice por cima (comVistoDoIndice).
    async function marcarVisto(db, key, visto) {
        const leve = db.indice.get(key);
        if (!leve) return;
        const novo = { ...leve, visto };
        db.indice.set(key, novo);
        const cacheDoChat = db.textoCompletoPorChat.get(leve.chatId);
        const completo = cacheDoChat && cacheDoChat.get(key);
        if (completo) cacheDoChat.set(key, { ...completo, visto });
        adiarAnexo(db, "indice.jsonl", JSON.stringify(novo) + "\n");
        await descarregarEscritasPendentes(db);
    }

    // O indice e a fonte da verdade dos campos que mudam depois do scan:
    // "visto" (marcado a mao) e as reacoes atualizadas pelo servidor
    // ("Atualizar reacoes", Monitorados) - quem le a mensagem completa do
    // arquivo do chat (busca, backup) aplica esses campos por cima.
    const CAMPOS_DO_INDICE_QUE_VENCEM = ["reactionTotal", "minhasReacoes", "emojis", "de", "midia", "link", "assinatura"];
    function comVistoDoIndice(db, registro) {
        const leve = db.indice.get(registro.key);
        if (!leve) return registro;
        const visto = !!leve.visto;
        let mudou = visto !== !!registro.visto;
        for (const campo of CAMPOS_DO_INDICE_QUE_VENCEM) {
            if (leve[campo] !== undefined && leve[campo] !== registro[campo]) mudou = true;
        }
        if (!mudou) return registro;
        const novo = { ...registro, visto };
        for (const campo of CAMPOS_DO_INDICE_QUE_VENCEM) if (leve[campo] !== undefined) novo[campo] = leve[campo];
        return novo;
    }

    // Filtros novos da rodada 4, iguais em todas as listas: so com uma
    // reacao (emoji), tipo de midia, so com link, autor. Mensagem salva
    // antes da rodada 4 nao tem esses campos e nao passa nos filtros ate
    // ser escaneada de novo.
    const REGEX_TEM_LINK = /(?:https?:\/\/|t\.me\/|tg:\/\/)/i;
    function passaNosFiltrosExtras(valor, { emoji, midia, soLink, de }) {
        if (emoji && !(valor.emojis || []).some((par) => par[0] === emoji)) return false;
        if (midia && (midia === "sem" ? !!valor.midia : valor.midia !== midia)) return false;
        if (soLink && !valor.link && !(valor.texto && REGEX_TEM_LINK.test(valor.texto))) return false;
        if (de && valor.de !== de) return false;
        return true;
    }

    // Quantas mensagens de um chat ja estao salvas - usado pela tabela "o
    // que ja foi salvo". Antes percorria o indice INTEIRO uma vez por chat,
    // e a tabela e redesenhada a cada checkpoint do scan: com centenas de
    // chats e milhoes de mensagens, bilhoes de comparacoes por checkpoint.
    // Agora e uma contagem mantida em memoria (abrirBanco/salvarMensagem).
    function contarMensagensDoChat(db, chatId) {
        return db.contagemPorChat.get(chatId) || 0;
    }

    // Filtra o indice inteiro (ja em memoria - nenhuma leitura de disco
    // aqui) por chat/minimo/periodo/excluidos e ordena pelo criterio
    // pedido. "excluidos" (Set de chatId, opcional): grupo desmarcado em
    // "Configurar grupos" nao pode continuar poluindo o ranking "Todos os
    // grupos" (bug real reportado pelo usuario e corrigido antes desta
    // troca de armazenamento - ver HISTORICO_TECNICO.md v2026.10.10.2).
    // Os "limite" primeiros itens pela ordem de "comparar", sem guardar nem
    // ordenar a lista inteira de candidatos: mantem so um vetor ordenado de
    // tamanho "limite" (insercao por busca binaria). Antes cada troca de
    // filtro ordenava TODAS as mensagens que passavam no filtro (milhoes,
    // com "minimo 0") pra mostrar 50. Sem limite, junta tudo e ordena no fim.
    function criarSelecaoDosPrimeiros(limite, comparar) {
        const itens = [];
        return {
            adicionar(item) {
                if (!limite) {
                    itens.push(item);
                    return;
                }
                if (itens.length === limite && comparar(item, itens[limite - 1]) >= 0) return;
                let baixo = 0;
                let alto = itens.length;
                while (baixo < alto) {
                    const meio = (baixo + alto) >> 1;
                    if (comparar(item, itens[meio]) < 0) alto = meio;
                    else baixo = meio + 1;
                }
                itens.splice(baixo, 0, item);
                if (itens.length > limite) itens.pop();
            },
            resultado() {
                return limite ? itens : itens.sort(comparar);
            },
        };
    }

    const compararPorReacoes = (a, b) => (b.reactionTotal || 0) - (a.reactionTotal || 0);
    const compararPorData = (a, b) => (a.dateUtc < b.dateUtc ? 1 : a.dateUtc > b.dateUtc ? -1 : 0);

    // "ocultarVistos": tira as ja marcadas como vistas ANTES de cortar no
    // limite - antes era filtrado so na tela, depois do corte em 50, entao
    // com muita coisa vista a lista vinha quase vazia e "Mostrar mais"
    // tinha que ser clicado varias vezes.
    function buscarTop(db, { chatId, minimo, limite, dataDe, dataAte, ordenarPor, excluidos, ocultarVistos, emoji, midia, soLink, de }) {
        const extras = { emoji, midia, soLink, de };
        const minimoReacoes = minimo || 0;
        const selecao = criarSelecaoDosPrimeiros(limite, ordenarPor === "data" ? compararPorData : compararPorReacoes);
        for (const valor of db.indice.values()) {
            if ((valor.reactionTotal || 0) < minimoReacoes) continue;
            if (chatId && valor.chatId !== chatId) continue;
            if (excluidos && excluidos.has(valor.chatId)) continue;
            if (ocultarVistos && valor.visto) continue;
            const dataDaMensagem = (valor.dateUtc || "").slice(0, 10);
            if (dataDe && dataDaMensagem < dataDe) continue;
            if (dataAte && dataDaMensagem > dataAte) continue;
            if (!passaNosFiltrosExtras(valor, extras)) continue;
            selecao.adicionar(valor);
        }
        return selecao.resultado();
    }

    // Existia como caminho separado (mais caro) quando o armazenamento era
    // IndexedDB com indice ordenado so por reacoes - agora que tudo vive
    // num Map em memoria, ordenar por data custa o mesmo que ordenar por
    // reacoes. Mantida como funcao a parte so pela assinatura (compatibilidade
    // com quem ainda chama ela direto), delega pra buscarTop().
    function buscarTopPorData(db, { chatId, minimo, limite, dataDe, dataAte, excluidos }) {
        return buscarTop(db, { chatId, minimo, limite, dataDe, dataAte, ordenarPor: "data", excluidos });
    }

    // "Minhas reacoes": mensagem que a PROPRIA conta logada reagiu (ver
    // comentario em extrairReacoes sobre chosenOrder), independente de
    // quantas reacoes no total ela tem. Existe porque reagir numa mensagem
    // e, na pratica, usado tambem como "marcar/guardar" - e esse uso se
    // perde dentro do ranking de "Top reacoes" quando mais ninguem reagiu
    // (reactionTotal fica baixo e a mensagem nunca aparece la). So enxerga
    // o indice leve (minhasReacoes faz parte dele - ver registroLeve), 0
    // leitura de disco, igual buscarTop(). Ordena por data (mais recente
    // primeiro) por padrao, nao por reacoes - o caso de uso tipico e "o que
    // eu marquei ultimamente", nao "o que teve mais engajamento".
    //
    // LIMITACAO CONHECIDA: so pega mensagem escaneada (ou rescaneada) DEPOIS
    // dessa funcionalidade existir (v2026.10.11.2) - mensagem ja salva antes
    // disso nao tem minhasReacoes no indice ate o chat ser escaneado de novo.
    function buscarMinhasReacoes(db, { chatId, limite, dataDe, dataAte, excluidos, ocultarVistos, emoji, midia, soLink }) {
        const extras = { emoji, midia, soLink };
        const selecao = criarSelecaoDosPrimeiros(limite, compararPorData);
        for (const valor of db.indice.values()) {
            if (!valor.minhasReacoes || !valor.minhasReacoes.length) continue;
            if (chatId && valor.chatId !== chatId) continue;
            if (excluidos && excluidos.has(valor.chatId)) continue;
            if (ocultarVistos && valor.visto) continue;
            const dataDaMensagem = (valor.dateUtc || "").slice(0, 10);
            if (dataDe && dataDaMensagem < dataDe) continue;
            if (dataAte && dataDaMensagem > dataAte) continue;
            if (!passaNosFiltrosExtras(valor, extras)) continue;
            selecao.adicionar(valor);
        }
        return selecao.resultado();
    }

    // Busca por substring (acentuacao/caixa ignoradas) no texto completo das
    // mensagens ja escaneadas - existe porque a busca nativa do Telegram e
    // por palavra inteira, as vezes nao acha mensagem que claramente existe
    // (ver HISTORICO_TECNICO.md). So enxerga o que ja foi salvo localmente.
    //
    // Termo com mais de uma palavra ("ana costa") NAO exige frase exata
    // nem que todas as palavras apareçam - cada palavra e checada separado,
    // e a mensagem entra se QUALQUER UMA delas aparecer em algum lugar do
    // texto (OU logico). Essa ferramenta existe pra achar o maximo possivel
    // (o problema real e mensagem que deveria aparecer e nao aparece, nao o
    // contrario) - entao, de proposito, prioriza nao perder nada a filtrar
    // demais: "ana costa" tambem traz "Mariana" e "Luciana" (so tem
    // "ana"), e eventualmente mensagem que so tem "costa" sem nenhuma
    // relacao com "ana". Isso e intencional, pedido pelo usuario -
    // ele prefere resultado a mais (filtra visualmente depois) a resultado
    // a menos. Buscar uma palavra so (sem espaco) se comporta exatamente
    // como sempre: substring simples.
    //
    // Precisa do TEXTO completo (nao esta no indice leve), entao le do
    // disco o(s) chat(s) relevante(s) - so o(s) necessario(s): um chat
    // especifico escolhido, ou todos MENOS os excluidos quando e "Todos os
    // grupos" (nem le do disco o que ja sabemos que vai ser descartado).
    // Cada chat so e lido do disco 1x por sessao (obterMensagensCompletasDoChat
    // cacheia) - buscas seguintes (trocar o termo, "Mostrar mais") reusam o
    // que ja esta em memoria.
    //
    // "excluidos" (Set de chatId, opcional): mesmo raciocinio de buscarTop()
    // - chat desmarcado em "Configurar grupos" tinha suas mensagens ja
    // salvas continuando a aparecer aqui com "Todos os grupos" selecionado.
    const textoNormalizadoPorRegistro = new WeakMap(); // registro -> texto normalizado; some junto com o registro

    async function buscarTexto(db, { termo, chatId, minimo, limite, ordenarPor, dataDe, dataAte, excluidos, ocultarVistos, emoji, midia, soLink, de }) {
        const extras = { emoji, midia, soLink, de };
        const palavras = normalizarTexto(termo)
            .split(/\s+/)
            .filter(Boolean);
        const minimoReacoes = minimo || 0;
        const selecao = criarSelecaoDosPrimeiros(limite, ordenarPor === "reacoes" ? compararPorReacoes : compararPorData);

        const chatsParaVarrer = chatId
            ? [chatId]
            : [...idsDeChatsComDados(db)].filter((id) => !excluidos || !excluidos.has(id));

        // Memoria: antes, "Todos os grupos" carregava o texto completo de
        // TODOS os chats de uma vez e deixava tudo em cache pela sessao
        // inteira - com o historico grande (GBs em disco) isso pode estourar
        // a memoria da aba. Agora le um chat por vez, o cache tem teto
        // (obterMensagensCompletasDoChat), e so os "limite" melhores
        // resultados ficam guardados (criarSelecaoDosPrimeiros). O texto sem
        // acento de cada mensagem fica guardado (textoNormalizadoPorRegistro)
        // enquanto o registro estiver em cache: a segunda busca nao refaz o
        // normalize() de cada mensagem.
        for (const idChat of chatsParaVarrer) {
            const mapa = await obterMensagensCompletasDoChat(db, idChat);
            for (const valor of mapa.values()) {
                let textoNormalizado = textoNormalizadoPorRegistro.get(valor);
                if (textoNormalizado === undefined) {
                    textoNormalizado = normalizarTexto(valor.texto || valor.textPreview || "");
                    textoNormalizadoPorRegistro.set(valor, textoNormalizado);
                }
                // palavras.length === 0 (termo em branco/so espaco) conta
                // como "bate com tudo", de proposito - pedido do usuario
                // pra poder deixar o campo vazio e usar esta busca como um
                // "mostra tudo".
                const bateAlgumaPalavra = palavras.length === 0 || palavras.some((p) => textoNormalizado.includes(p));
                const dataDaMensagem = (valor.dateUtc || "").slice(0, 10);
                const bateData = (!dataDe || dataDaMensagem >= dataDe) && (!dataAte || dataDaMensagem <= dataAte);
                if (bateAlgumaPalavra && bateData) {
                    const comVisto = comVistoDoIndice(db, valor);
                    if ((comVisto.reactionTotal || 0) < minimoReacoes) continue;
                    if (ocultarVistos && comVisto.visto) continue;
                    if (!passaNosFiltrosExtras(comVisto, extras)) continue;
                    selecao.adicionar(comVisto);
                }
            }
        }

        return selecao.resultado();
    }

    // Agrupa uma lista de mensagens por chat, preservando a ordem de
    // primeira aparicao de cada chat (ou seja, se a lista ja vier ordenada
    // por reacoes ou data, o grupo com o resultado mais relevante aparece
    // primeiro). Usado pra renderizar resultados de busca agrupados por
    // grupo/canal quando a busca e feita em "Todos".
    function agruparPorChat(mensagens) {
        const ordemChats = [];
        const porChat = new Map();
        for (const m of mensagens) {
            if (!porChat.has(m.chatId)) {
                porChat.set(m.chatId, { chatId: m.chatId, chatTitle: m.chatTitle, itens: [] });
                ordemChats.push(m.chatId);
            }
            porChat.get(m.chatId).itens.push(m);
        }
        return ordemChats.map((chatId) => porChat.get(chatId));
    }

    // ---- Extracao de dados da mensagem/dialogo, espelhando o scan.py ----

    // "chosenOrder" (campo opcional da TL "ReactionCount", chosen_order no
    // schema MTProto) e o proprio Telegram dizendo "a CONTA LOGADA reagiu
    // com essa aqui" - vem de graca no mesmo "results" que ja liamos pro
    // total, sem chamada de API extra nenhuma. So pode faltar (undefined)
    // ou ser um numero (a ORDEM da reacao, podendo ser 0 - por isso o teste
    // tem que ser "!== undefined", nunca truthiness direta, senao a
    // primeira reacao do usuario, ordem 0, seria descartada por engano).
    // Usado pra "Minhas reacoes": mensagem que o PROPRIO usuario reagiu,
    // muitas vezes so pra marcar/guardar, que fica perdida no ranking de
    // "Top reacoes" quando mais ninguem reagiu (reactionTotal baixo).
    function extrairReacoes(mensagem) {
        const reactions = [];
        const minhasReacoes = [];
        let total = 0;
        if (mensagem.reactions && mensagem.reactions.results) {
            for (const r of mensagem.reactions.results) {
                const emoji =
                    (r.reaction && r.reaction.emoticon) || (r.reaction && r.reaction.className === "ReactionPaid" ? "estrela" : "custom");
                reactions.push({ emoji, count: r.count });
                total += r.count;
                if (r.chosenOrder !== undefined && r.chosenOrder !== null) {
                    minhasReacoes.push(emoji);
                }
            }
        }
        return { reactions, total, minhasReacoes };
    }

    // Texto completo da mensagem, sem truncar - e o que a busca por palavra-
    // chave usa. truncar() abaixo e so pra exibicao nas listas.
    function textoCompleto(mensagem) {
        const texto = (mensagem.message || "").trim().replace(/\s+/g, " ");
        return texto || "[mídia ou mensagem sem texto]";
    }

    // Acha links do Telegram num texto - t.me de @usuario (t.me/nome), t.me
    // de convite por hash (t.me/joinchat/XXX ou t.me/+XXX), e tambem o
    // esquema nativo tg://join?invite=XXX (formato que a maioria dos sites
    // externos que agregam link de grupo publico usa, ex. diretorios de
    // grupo por categoria). Usado pelo filtro "links de grupo" da Busca
    // avancada (telaBuscaAvancada) e pela caixa de "conferir link colado" -
    // pra oferecer verificar se o link ainda e valido em vez do usuario
    // precisar abrir cada um so pra descobrir. new RegExp() a cada chamada
    // (em vez de um regex /g compartilhado no modulo) de proposito - regex
    // com /g guarda posicao entre chamadas (lastIndex), e reusar o mesmo
    // objeto entre textos diferentes e um jeito classico de perder ou
    // duplicar match por engano.
    function extrairLinksTelegram(texto) {
        const links = [];
        if (!texto) return links;
        const vistos = new Set();
        const adicionar = (ehConvite, valor) => {
            const chave = (ehConvite ? "c:" : "u:") + valor.toLowerCase();
            if (vistos.has(chave)) return;
            vistos.add(chave);
            links.push({ ehConvite, valor });
        };

        // O link pode vir url-encoded (ex.: colado de dentro de uma URL do
        // tipo web.telegram.org/k/#?tgaddr=tg%3A%2F%2Fjoin%3Finvite%3DXXX,
        // que e como o proprio Telegram Web representa um tg://join colado
        // na barra de enderecos) - decodifica uma vez antes de rodar os
        // regex, assim o formato puro e o encoded caem no mesmo caminho. Se
        // o texto tiver um "%" que nao e um escape valido, decodeURIComponent
        // lanca erro - nesse caso segue com o texto original, sem decodificar.
        let textoDecodificado = texto;
        try {
            textoDecodificado = decodeURIComponent(texto);
        } catch (erro) {
            // nao e url-encoded (ou esta mal formado) - usa o texto como veio
        }

        const regexTMe = /(?:https?:\/\/)?t\.me\/(\+|joinchat\/)?([a-zA-Z0-9_]{3,})/g;
        let m;
        while ((m = regexTMe.exec(textoDecodificado))) {
            adicionar(!!m[1], m[2]);
        }

        const regexTgJoin = /tg:\/\/join\?invite=([a-zA-Z0-9_-]+)/g;
        while ((m = regexTgJoin.exec(textoDecodificado))) {
            adicionar(true, m[1]);
        }

        return links;
    }

    // Confere se um link de grupo/canal ainda e valido SEM abrir nada no
    // navegador - link de @usuario usa contacts.ResolveUsername (o usuario
    // ainda existe?), link de convite por hash usa messages.CheckChatInvite
    // (o hash ainda e valido? convite pode ser revogado ou expirar). Os dois
    // dao erro RPC (USERNAME_NOT_OCCUPIED/USERNAME_INVALID,
    // INVITE_HASH_EXPIRED/INVITE_HASH_INVALID) quando o link nao presta mais -
    // e isso que vira "invalido" aqui, nao um campo separado na resposta.
    async function verificarLinkTelegram(link) {
        try {
            if (link.ehConvite) {
                const resultado = await cliente.invoke(new Api.messages.CheckChatInvite({ hash: link.valor }));
                const titulo = resultado.title || (resultado.chat && resultado.chat.title) || null;
                const participantes =
                    typeof resultado.participantsCount === "number" ? resultado.participantsCount : null;
                return { valido: true, titulo, participantes };
            }
            const resultado = await cliente.invoke(new Api.contacts.ResolveUsername({ username: link.valor }));
            const chat = (resultado.chats && resultado.chats[0]) || null;
            return {
                valido: true,
                titulo: chat ? chat.title : null,
                participantes: chat && typeof chat.participantsCount === "number" ? chat.participantsCount : null,
            };
        } catch (erro) {
            return { valido: false, erro: erro && erro.message ? erro.message : String(erro) };
        }
    }

    // Cria a linha "verificando..." pra um link achado (por
    // extrairLinksTelegram), dispara verificarLinkTelegram nele e atualiza a
    // propria linha quando o resultado volta - valido (com titulo/qtd de
    // participantes, se vierem) ou invalido/expirado. Compartilhado entre o
    // "links encontrados nos resultados da busca" (telaBuscaAvancada) e a
    // caixa de "conferir link colado" (mesma tela) - os dois so diferem em
    // ONDE o link veio de, a verificacao e a apresentacao sao identicas.
    // "mapaVistos" (valor normalizado -> elemento) evita duplicar o mesmo
    // link na mesma lista.
    function criarItemDeLink(link, container, mapaVistos) {
        const chave = (link.ehConvite ? "convite:" : "usuario:") + link.valor.toLowerCase();
        if (mapaVistos.has(chave)) return;

        const item = document.createElement("div");
        item.style.cssText = "padding:6px 0;border-bottom:1px solid #2a2f3a;font-size:13px;";
        item.textContent = "t.me/" + (link.ehConvite ? "+" : "") + link.valor + " - verificando...";
        container.appendChild(item);
        mapaVistos.set(chave, item);

        verificarLinkTelegram(link).then((resultado) => {
            const enderecoLink = "t.me/" + (link.ehConvite ? "+" : "") + link.valor;
            if (resultado.valido) {
                const detalhes = [];
                if (resultado.titulo) detalhes.push(escapeHtml(resultado.titulo));
                if (resultado.participantes != null) detalhes.push(resultado.participantes + " participantes");
                item.innerHTML =
                    '<span style="color:#5ec26a;">válido</span> - ' +
                    escapeHtml(enderecoLink) +
                    (detalhes.length ? " (" + detalhes.join(", ") + ")" : "") +
                    " ";
                item.appendChild(criarLinkExterno("abrir", "https://" + enderecoLink, "color:#4da3ff;"));
            } else {
                item.innerHTML =
                    '<span style="color:#ff6b6b;">inválido ou expirado</span> - ' +
                    escapeHtml(enderecoLink) +
                    ' <span style="color:#a3aab8;font-size:13px;">(' + escapeHtml(resultado.erro || "") + ")</span>";
            }
        });
    }

    function truncar(texto, tamanho) {
        if (!texto) return "";
        return texto.length > tamanho ? texto.slice(0, tamanho) + "..." : texto;
    }

    // Tira acentuacao e caixa, pra "informacao" encontrar "informação" (ou
    // "INFORMAÇÃO"). A busca nativa do Telegram e por palavra inteira, nao
    // por pedaco de palavra - essa normalizacao + o .includes() em
    // buscarTexto() cobrem exatamente esse buraco.
    function normalizarTexto(texto) {
        return (texto || "")
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "") // escape em vez do caractere cru: arquivo lido com codificacao errada nao quebra o script inteiro
            .toLowerCase();
    }

    function dataIso(mensagem) {
        const d = mensagem.date instanceof Date ? mensagem.date : new Date(mensagem.date * 1000);
        return d.toISOString();
    }

    // O chatId que guardamos (dialog.id) segue a convencao da Bot API: grupos
    // basicos viram "-<id>", canais/supergrupos viram "-100<id>". Olhando o
    // codigo-fonte do proprio Telegram Web (github.com/morethanwords/tweb,
    // src/lib/appImManager.ts, funcao onHashChangeUnsafe), o link que abre a
    // MENSAGEM EXATA (nao so o grupo) e "#<id puro, sem sinal e sem o
    // 100>?post=<id da mensagem>" - e'xatamente o mesmo id puro que aparece
    // nos links nativos de "copiar link da mensagem" (t.me/c/<id>/<msg>).
    // Essa funcao tira o sinal e o "100" do chatId que a gente guarda, pra
    // chegar nesse id puro.
    function idBaseDoChatId(chatId) {
        const texto = String(chatId);
        if (texto.startsWith("-100")) {
            return texto.slice(4);
        }
        if (texto.startsWith("-")) {
            return texto.slice(1);
        }
        return texto;
    }

    // Link HTML comum (<a target="_blank">), sem nenhum JS por tras - mesma
    // decisao da v2026.10.12.5 pros links de mensagem: window.open chamado
    // de dentro do sandbox do Tampermonkey no Edge deixava a aba original
    // inutilizavel (ver HISTORICO_TECNICO.md v2026.10.12.3 a .5). Os links
    // "abrir" da Busca avancada ainda usavam window.open.
    function criarLinkExterno(texto, url, estilo) {
        const link = document.createElement("a");
        link.href = url;
        link.target = "_blank";
        link.rel = "noopener noreferrer";
        link.textContent = texto;
        link.style.cssText = "text-decoration:none;" + (estilo || "");
        return link;
    }

    // href do link que abre a mensagem exata no Telegram Web (ver
    // idBaseDoChatId). Passa por encodeURIComponent porque chatId/messageId
    // podem vir de um backup importado (arquivo de fora), nao so do scan.
    function urlDaMensagem(m) {
        return (
            "https://web.telegram.org/k/#" +
            encodeURIComponent(idBaseDoChatId(m.chatId)) +
            "?post=" +
            encodeURIComponent(m.messageId)
        );
    }

    function criarBotao() {
        const botao = document.createElement("button");
        botao.textContent = "TLGMaster";
        Object.assign(botao.style, {
            position: "fixed",
            bottom: "24px",
            right: "24px",
            zIndex: 999999,
            padding: "10px 16px",
            borderRadius: "999px",
            border: "none",
            background: CORES.destaque,
            color: CORES.fundo,
            fontFamily: "sans-serif",
            fontWeight: "600",
            fontSize: "14px",
            cursor: "pointer",
            boxShadow: "0 2px 10px rgba(0,0,0,0.35)",
        });
        botao.addEventListener("click", alternarPainel);
        document.body.appendChild(botao);
        botaoFlutuante = botao;
        if (typeof atualizarContadoresDeNovos === "function") atualizarContadoresDeNovos(null);
    }

    function alternarPainel() {
        fecharBalaoDeInfo();
        if (painel) {
            painel.remove(); // leva areaRolavel e os botoes de navegacao junto, todos filhos dele
            painel = null;
            areaRolavel = null;
        } else montarPainel();
        // Dica do Alt+clique na tela: sai de baixo do painel que abriu.
        if (typeof reposicionarDicaDoAlt === "function") reposicionarDicaDoAlt();
    }

    // O painel agora e so a caixa fixa (header + area com scroll proprio
    // dentro dela) - ver comentario de adicionarBotoesNavegacao() sobre o
    // motivo dessa separacao existir.
    function montarPainel() {
        painel = document.createElement("div");
        Object.assign(painel.style, {
            position: "fixed",
            top: "40px",
            right: "24px",
            width: "620px",
            maxWidth: "calc(100vw - 48px)",
            maxHeight: "80vh",
            overflow: "hidden",
            display: "flex",
            flexDirection: "column",
            background: "#171a21",
            color: "#e6e8ec",
            border: "1px solid #2a2f3a",
            borderRadius: "10px",
            zIndex: 999999,
            padding: "16px",
            fontFamily: "sans-serif",
            fontSize: "14px",
            lineHeight: "1.45",
            boxShadow: "0 8px 30px rgba(0,0,0,0.5)",
        });
        document.body.appendChild(painel);
        renderizarCabecalho();

        // Unico filho de painel que de fato rola - "flex:1;min-height:0" e
        // o jeito padrao de fazer um filho de flex-column encolher e ganhar
        // scroll proprio em vez de estourar o pai. Com isso, o cabecalho
        // fica sempre visivel (fora da area rolavel) e os botoes de
        // navegacao (filhos de painel, nao de areaRolavel) nunca ficam
        // tampados pelo conteudo nem precisam fugir do painel pra escapar
        // de corte nenhum.
        areaRolavel = document.createElement("div");
        areaRolavel.id = "trp-area-rolavel";
        // overflow-x:hidden e cinto-de-seguranca contra mensagem com palavra
        // comprida sem espaco (link, texto colado) que force a largura da
        // caixa alem do previsto - sem isso aparecia uma barra de rolagem
        // horizontal, empurrando o usuario pra uma area vazia a direita. A
        // quebra de linha forcada nos textos (overflow-wrap:anywhere, ver
        // criarItemResultado() e as listas de resultado) ja deveria evitar
        // que isso aconteça, mas o corte aqui garante mesmo se algum texto
        // escapar.
        areaRolavel.style.cssText = "overflow-y:auto;overflow-x:hidden;flex:1;min-height:0;";
        painel.appendChild(areaRolavel);

        adicionarBotoesNavegacao();
        decidirTela();
    }

    // Botoes flutuantes (voltar ao topo / ir pro fim) da area de
    // resultado, sem precisar arrastar o mouse rolando. Sao filhos do
    // PAINEL (posicionados com position:absolute, ancorados no canto
    // inferior direito dele - painel tem position:fixed, entao serve de
    // referencia pra esse absolute), nao filhos de areaRolavel nem do
    // document.body:
    // - filho de areaRolavel rolaria junto com o conteudo (sumiria de
    //   vista ao rolar pra baixo).
    // - filho do document.body com position:fixed foi tentado antes e
    //   saiu errado: o Telegram Web pode ter algum ancestral com
    //   transform/filter la em cima que muda a base de calculo de um
    //   "fixed", fazendo o botao aparecer em qualquer canto da pagina real
    //   em vez do canto do NOSSO painel.
    // Como filho do painel, painel.remove() leva os dois junto - nao
    // precisa remover na mao ao fechar.
    function adicionarBotoesNavegacao() {
        const estiloBase = {
            position: "absolute",
            right: "16px",
            zIndex: 1,
            width: "32px",
            height: "32px",
            borderRadius: "50%",
            border: "none",
            background: CORES.destaque,
            color: CORES.fundo,
            fontSize: "16px",
            fontWeight: "700",
            cursor: "pointer",
            boxShadow: "0 2px 10px rgba(0,0,0,0.35)",
            // Comecam escondidos - so fazem sentido quando a area rolavel tem
            // mais conteudo do que cabe na tela. atualizarVisibilidadeBotoesNavegacao()
            // (chamada pelo ResizeObserver em corpoDoPainel()) mostra os dois
            // assim que detecta rolagem de verdade disponivel, e esconde de
            // volta se o conteudo encolher a ponto de nao precisar mais.
            display: "none",
        };

        const botaoTopo = document.createElement("button");
        botaoTopo.id = "trp-botao-nav-topo";
        botaoTopo.textContent = "↑";
        botaoTopo.title = "Voltar ao topo";
        Object.assign(botaoTopo.style, estiloBase, { bottom: "56px" });
        botaoTopo.addEventListener("click", () => {
            areaRolavel.scrollTop = 0;
        });
        painel.appendChild(botaoTopo);

        const botaoFim = document.createElement("button");
        botaoFim.id = "trp-botao-nav-fim";
        botaoFim.textContent = "↓";
        botaoFim.title = "Ir pro fim";
        Object.assign(botaoFim.style, estiloBase, { bottom: "16px" });
        botaoFim.addEventListener("click", () => {
            areaRolavel.scrollTop = areaRolavel.scrollHeight;
        });
        painel.appendChild(botaoFim);
    }

    // Mostra as setinhas de navegacao so quando a area rolavel realmente tem
    // mais conteudo do que cabe na tela (ou seja, so quando rolar faz
    // sentido) - escondidas na tela inicial e em qualquer lista curta. +1 e
    // margem pra arredondamento de subpixel nao contar como "tem rolagem" por
    // 1px de diferenca.
    function atualizarVisibilidadeBotoesNavegacao() {
        if (!painel || !areaRolavel) return;
        const temRolagem = areaRolavel.scrollHeight > areaRolavel.clientHeight + 1;
        const exibir = temRolagem ? "" : "none";
        const botaoTopo = painel.querySelector("#trp-botao-nav-topo");
        const botaoFim = painel.querySelector("#trp-botao-nav-fim");
        if (botaoTopo) botaoTopo.style.display = exibir;
        if (botaoFim) botaoFim.style.display = exibir;
        // Rodada 6: com as setinhas na tela, reserva a faixa da direita pra
        // elas nao ficarem por cima de lapis/lixeira/botoes no fim da linha.
        areaRolavel.style.paddingRight = temRolagem ? "44px" : "";
    }

    function renderizarCabecalho() {
        const cabecalho = document.createElement("div");
        cabecalho.style.cssText =
            "display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:12px;";
        cabecalho.innerHTML =
            '<div style="display:flex;align-items:baseline;gap:8px;min-width:0;">' +
            '<span id="trp-titulo-tela" style="font-size:16px;font-weight:700;color:#e6e8ec;">TLGMaster</span>' +
            '<span style="color:#a3aab8;font-size:13px;">v' +
            escapeHtml(VERSAO_PAINEL) +
            "</span></div>" +
            '<button id="trp-fechar" title="Fechar o painel" aria-label="Fechar o painel" style="background:none;border:none;color:#a3aab8;cursor:pointer;font-size:18px;line-height:1;padding:2px 6px;">x</button>';
        painel.appendChild(cabecalho);
        cabecalho.querySelector("#trp-fechar").addEventListener("click", alternarPainel);
    }

    // Titulo = nome do botao que levou ate a tela (rodada 6), ex.:
    // "TLGMaster  Escanear". O menu (telaLogado) chama com null.
    function definirTituloTela(nomeTela) {
        const titulo = painel && painel.querySelector("#trp-titulo-tela");
        if (!titulo) return;
        titulo.innerHTML = nomeTela
            ? '<span style="color:#a3aab8;font-weight:600;">TLGMaster</span> <span style="color:#a3aab8;">/</span> ' + escapeHtml(nomeTela)
            : "TLGMaster";
    }

    // "Sair" mudou do cabecalho pra Ajustes > Conta (rodada 6). Mantida
    // por compatibilidade com quem ainda chama (nao faz nada).
    function atualizarVisibilidadeSair() {}

    // Botao "Sair da conta": primeiro clique so avisa (3 s, vermelho);
    // segundo clique sai. Evita sair sem querer.
    function botaoSairDaConta(container) {
        const botao = botaoPequeno(container, "Sair da conta", null, "color:#ff6b6b;");
        let pendente = null;
        botao.addEventListener("click", () => {
            if (!pendente) {
                botao.textContent = "Confirmar: sair da conta?";
                botao.style.background = "#ff6b6b";
                botao.style.color = "#171a21";
                pendente = setTimeout(() => {
                    pendente = null;
                    botao.textContent = "Sair da conta";
                    botao.style.background = "#2a2f3a";
                    botao.style.color = "#ff6b6b";
                }, 3000);
                return;
            }
            clearTimeout(pendente);
            executarSaida(botao);
        });
        return botao;
    }

    async function executarSaida(botao) {
        if (botao) {
            botao.disabled = true;
            botao.textContent = "saindo...";
        }
        try {
            await cliente.logOut();
        } catch (erro) {
            // se der erro no logOut remoto, ainda assim limpa localmente
        }
        cliente = null;
        limparCacheDaConta();
        limparSessao();
        decidirTela();
    }

    function corpoDoPainel() {
        fecharBalaoDeInfo(); // trocou de tela: o "i" do balao aberto sumiu
        let corpo = areaRolavel.querySelector("#trp-corpo");
        if (!corpo) {
            corpo = document.createElement("div");
            corpo.id = "trp-corpo";
            // overflow-wrap:anywhere quebra ate uma palavra sem espaco (link,
            // texto colado) que de outra forma estouraria a largura da caixa -
            // ver comentario em areaRolavel sobre a barra de rolagem
            // horizontal que isso evita.
            corpo.style.cssText = "overflow-wrap:anywhere;word-break:break-word;";
            areaRolavel.appendChild(corpo);
            // O tamanho de #trp-corpo muda toda vez que uma tela troca de
            // conteudo ou uma lista e recarregada - observar ele (em vez de
            // cada call site que muda a lista) e o jeito mais simples de
            // saber, de forma centralizada, se a area rolavel ficou mais alta
            // que a parte visivel dela (ver atualizarVisibilidadeBotoesNavegacao).
            if (window.ResizeObserver) {
                new ResizeObserver(atualizarVisibilidadeBotoesNavegacao).observe(corpo);
            }
        }
        corpo.innerHTML = "";
        return corpo;
    }

    function campoTexto(corpo, rotulo, tipo, valorInicial) {
        const bloco = document.createElement("div");
        bloco.style.marginBottom = "10px";
        const label = document.createElement("label");
        label.textContent = rotulo;
        label.style.cssText = "display:block;color:#a3aab8;margin-bottom:4px;";
        const input = document.createElement("input");
        input.type = tipo || "text";
        input.value = valorInicial || "";
        input.style.cssText =
            "width:100%;background:#0c0e12;color:#e6e8ec;border:1px solid #2a2f3a;border-radius:6px;padding:8px;box-sizing:border-box;";
        bloco.appendChild(label);
        bloco.appendChild(input);
        corpo.appendChild(bloco);
        return input;
    }

    function botaoAcao(corpo, texto) {
        const botao = document.createElement("button");
        botao.textContent = texto;
        botao.style.cssText =
            "width:100%;padding:10px;border:none;border-radius:6px;background:#4da3ff;color:#171a21;font-weight:600;cursor:pointer;margin-top:4px;";
        corpo.appendChild(botao);
        return botao;
    }

    // Quadrado marcavel feito na mao (nao usa <input type="checkbox">
    // nativo). O CSS global do Telegram Web reseta a aparencia de checkbox
    // nativo sem recolocar nada visivel no lugar - o elemento continua
    // funcional (por isso o cursor vira de "clicavel"), mas invisivel. Um
    // quadrado de verdade desenhado por nos nao depende do CSS do site.
    // Qualquer novo controle de formulario (checkbox, radio, etc.) deve
    // seguir esse mesmo padrao. Sem label proprio - o chamador decide o
    // layout em volta (usado como "marcar como visto" em cada item das
    // listas de resultado).
    function criarQuadradoMarcavel(valorInicial, aoAlternar) {
        const quadrado = document.createElement("div");
        quadrado.style.cssText =
            "width:18px;height:18px;flex-shrink:0;margin-top:2px;border:2px solid #a3aab8;border-radius:4px;" +
            "display:flex;align-items:center;justify-content:center;font-size:13px;line-height:1;color:#171a21;" +
            "background:#0c0e12;cursor:pointer;user-select:none;";

        let marcado = !!valorInicial;
        const atualizarVisual = () => {
            quadrado.textContent = marcado ? "✓" : "";
            quadrado.style.background = marcado ? "#4da3ff" : "#0c0e12";
            quadrado.style.borderColor = marcado ? "#4da3ff" : "#a3aab8";
        };
        quadrado.addEventListener("click", (ev) => {
            ev.stopPropagation(); // nao deixa o clique vazar pro "abrir mensagem" do item
            marcado = !marcado;
            atualizarVisual();
            if (aoAlternar) aoAlternar(marcado);
        });
        atualizarVisual();

        return {
            elemento: quadrado,
            get checked() {
                return marcado;
            },
            set checked(valor) {
                marcado = !!valor;
                atualizarVisual();
            },
        };
    }

    // "i" pequeno com tooltip nativo (atributo title, o navegador mostra
    // sozinho ao passar o mouse por cima) - usado pra tirar explicacao
    // longa de cima da tela (fica tudo poluido com paragrafo grande
    // sempre visivel) sem perder a informacao, so escondendo ela atras de
    // um hover. Devolve uma STRING de HTML (nao um elemento), pra poder
    // ser concatenada direto num innerHTML ou injetada com
    // insertAdjacentHTML.
    // Rodada 8: o texto vai em data-info e abre num balao proprio (clique,
    // Enter ou mouse parado em cima - ver ligarBaloesDeInfo em
    // interface.js). Antes era so o "title" do navegador: clicar nao fazia
    // nada e, no Telegram real, passar o mouse tambem nao mostrou nada.
    function criarIconeInfoHtml(textoCompleto) {
        return (
            ' <span class="trp-icone-info" role="button" tabindex="0" aria-label="Mais informações" aria-expanded="false" ' +
            'style="display:inline-block;width:18px;height:18px;line-height:17px;text-align:center;' +
            "border-radius:50%;border:1px solid #a3aab8;color:#a3aab8;font-size:13px;font-style:normal;" +
            'cursor:pointer;vertical-align:middle;user-select:none;" data-info="' +
            // aspas tambem: antes o texto do title era cortado na primeira
            // aspa (escapeHtml nao troca aspas)
            escapeHtml(textoCompleto).replace(/"/g, "&quot;") +
            '">i</span>'
        );
    }

    function textoAviso(corpo, mensagem, cor) {
        let aviso = corpo.querySelector(".trp-aviso");
        if (!aviso) {
            aviso = document.createElement("div");
            aviso.className = "trp-aviso";
            aviso.style.cssText = "margin-top:10px;font-size:13px;";
            corpo.appendChild(aviso);
        }
        aviso.style.color = cor || "#a3aab8";
        aviso.textContent = mensagem || "";
        return aviso;
    }

    // Pede um valor ao usuario dentro do proprio painel (ex.: codigo de
    // login, senha de duas etapas) e devolve uma Promise que resolve quando
    // ele confirma. Usado pelos callbacks do client.start().
    // Erro da tentativa anterior de login (ex.: PHONE_CODE_INVALID). O
    // client.start() chama onError e logo depois pede o codigo de novo -
    // como pedirValor() limpa a tela, o aviso do onError sumia antes de
    // aparecer e o usuario so via o campo vazio de novo, sem saber que o
    // codigo estava errado. Agora pedirValor() mostra esse erro em cima.
    let erroLoginAnterior = "";
    function pedirValor(rotulo, tipo) {
        return new Promise((resolve) => {
            const corpo = corpoDoPainel();
            if (erroLoginAnterior) {
                textoAviso(corpo, erroLoginAnterior, "#ff6b6b").style.margin = "0 0 10px";
                erroLoginAnterior = "";
            }
            const input = campoTexto(corpo, rotulo, tipo || "text");
            const botao = botaoAcao(corpo, "Confirmar");
            const confirmar = () => {
                const valor = input.value.trim();
                if (!valor) return;
                resolve(valor);
            };
            botao.addEventListener("click", confirmar);
            input.addEventListener("keydown", (ev) => {
                if (ev.key === "Enter") confirmar();
            });
            input.focus();
        });
    }

    function decidirTela() {
        atualizarVisibilidadeSair(false);
        // Produto: primeira abertura mostra as boas-vindas (boas_vindas.js).
        if (boasVindasNoInicio()) return telaBoasVindas();
        const apiId = GM_getValue(CHAVE_API_ID, "");
        const apiHash = GM_getValue(CHAVE_API_HASH, "");
        if (!apiId || !apiHash) {
            return telaCredenciais();
        }
        const temSessao = temSessaoGuardada();
        if (temSessao && cliente) {
            return telaLogado();
        }
        if (temSessao) {
            return reconectarComSessaoSalva(apiId, apiHash);
        }
        return telaLogin(apiId, apiHash);
    }

    function telaCredenciais() {
        definirTituloTela(null);
        const corpo = corpoDoPainel();
        corpo.innerHTML =
            '<div style="color:#a3aab8;margin-bottom:10px;">' +
            "Antes do primeiro login, pegue suas credenciais de API em " +
            '<a href="https://my.telegram.org/apps" target="_blank" style="color:#4da3ff;">my.telegram.org/apps</a>' +
            " (login com seu número, cria um app qualquer, anota api_id e api_hash). Só precisa fazer isso uma vez." +
            "</div>";
        // Produto: botao que cria a chave sozinho (chave_api.js) + faixa do
        // primeiro uso. Pessoal: nada muda (CONFIG desliga os dois).
        if (CONFIG.assistenteChaveApi) montarChaveAutomaticaNoPainel(corpo, () => decidirTela());
        faixaDoPrimeiroUso(corpo, 2);
        const apiId = campoTexto(corpo, "api_id", "text");
        const apiHash = campoTexto(corpo, "api_hash", "text");
        const botao = botaoAcao(corpo, "Salvar");
        botao.addEventListener("click", () => {
            const idValor = apiId.value.trim();
            const hashValor = apiHash.value.trim();
            if (!idValor || !hashValor) {
                textoAviso(corpo, "Preenche os dois campos.", "#ff6b6b");
                return;
            }
            GM_setValue(CHAVE_API_ID, idValor);
            GM_setValue(CHAVE_API_HASH, hashValor);
            decidirTela();
        });
    }

    function novoCliente(apiId, apiHash, sessaoSalva) {
        const novo = new TelegramClient(new StringSession(sessaoSalva || ""), parseInt(apiId, 10), apiHash, {
            connectionRetries: 3,
            networkSocket: PromisedWebSockets,
            deviceModel: CONFIG.nomeDoAparelho,
            systemVersion: "Tampermonkey",
            useWSS: true,
        });
        // Etapa P2: reacao nova vai pro indice na hora (reacoes_na_hora.js).
        ouvirReacoesNoCliente(novo);
        return novo;
    }

    // Conexao UNICA com a sessao salva, compartilhada entre o painel e as
    // ferramentas de fundo (ferramentas_fundo.js). Antes cada um criava a
    // sua: abrir o painel e dar Alt+clique ao mesmo tempo abria duas
    // conexoes MTProto com a mesma sessao, e uma ficava aberta a toa. Quem
    // chamar enquanto ja esta conectando recebe a mesma promessa. "cliente"
    // so e preenchido DEPOIS de autorizado - antes, fechar e reabrir o
    // painel no meio da reconexao caia em telaLogado() com um cliente que
    // ainda nao estava pronto.
    // Devolve o cliente, ou null se a sessao salva nao vale mais (nesse
    // caso ja apaga a sessao salva).
    let conectandoComSessaoSalva = null;
    function conectarComSessaoSalva() {
        if (cliente) return Promise.resolve(cliente);
        if (conectandoComSessaoSalva) return conectandoComSessaoSalva;
        conectandoComSessaoSalva = (async () => {
            const apiId = GM_getValue(CHAVE_API_ID, "");
            const apiHash = GM_getValue(CHAVE_API_HASH, "");
            const sessaoSalva = await carregarSessao();
            if (!apiId || !apiHash || !sessaoSalva) return null;
            const novo = novoCliente(apiId, apiHash, sessaoSalva);
            try {
                await novo.connect();
                if (!(await novo.checkAuthorization())) {
                    limparSessao();
                    await novo.disconnect().catch(() => {});
                    return null;
                }
            } catch (erro) {
                await novo.disconnect().catch(() => {});
                throw erro;
            }
            if (!cliente) cliente = novo;
            return cliente;
        })();
        conectandoComSessaoSalva.then(
            () => (conectandoComSessaoSalva = null),
            () => (conectandoComSessaoSalva = null)
        );
        return conectandoComSessaoSalva;
    }

    async function reconectarComSessaoSalva(apiId, apiHash) {
        definirTituloTela(null);
        const corpo = corpoDoPainel();
        textoAviso(corpo, "Reconectando com a sessão salva...");
        try {
            const conectado = await conectarComSessaoSalva();
            if (!conectado) {
                textoAviso(corpo, "Sessão salva não é mais válida, faça login de novo.", "#ff6b6b");
                telaLogin(apiId, apiHash);
                return;
            }
            telaLogado();
        } catch (erro) {
            textoAviso(corpo, "Erro ao reconectar: " + (erro && erro.message ? erro.message : erro), "#ff6b6b");
        }
    }

    function telaLogin(apiId, apiHash) {
        definirTituloTela(null);
        const corpo = corpoDoPainel();
        faixaDoPrimeiroUso(corpo, 3);
        const telefone = campoTexto(corpo, "Número de telefone (com DDI, ex: +5511999999999)", "text");
        const botao = botaoAcao(corpo, "Entrar");
        botao.addEventListener("click", async () => {
            botao.disabled = true;
            textoAviso(corpo, "Conectando...");
            const numero = telefone.value.trim();
            if (!numero) {
                textoAviso(corpo, "Digita o número de telefone.", "#ff6b6b");
                botao.disabled = false;
                return;
            }
            erroLoginAnterior = "";
            const novoClienteLogin = novoCliente(apiId, apiHash, "");
            try {
                await novoClienteLogin.start({
                    phoneNumber: async () => numero,
                    phoneCode: async (ehPeloApp, info) =>
                        pedirValor(
                            "Código de login recebido " + (ehPeloApp ? "no próprio Telegram" : "por SMS"),
                            "text"
                        ),
                    password: async (dica) =>
                        pedirValor(
                            "Senha de verificação em duas etapas" + (dica ? " (dica: " + dica + ")" : ""),
                            "password"
                        ),
                    onError: async (erro) => {
                        erroLoginAnterior = "Erro: " + (erro && erro.message ? erro.message : erro);
                        textoAviso(corpo, erroLoginAnterior, "#ff6b6b");
                        return false; // false = tenta de novo em vez de cancelar
                    },
                });
                cliente = novoClienteLogin;
                await guardarSessao(cliente.session.save()).catch((e) => console.warn("[TLGMaster] sessão:", e));
                telaLogado();
            } catch (erro) {
                novoClienteLogin.disconnect().catch(() => {}); // senao a conexao da tentativa que falhou fica aberta
                textoAviso(corpo, "Erro ao entrar: " + (erro && erro.message ? erro.message : erro), "#ff6b6b");
                botao.disabled = false;
            }
        });
    }

    async function telaLogado() {
        definirTituloTela(null);
        const corpo = corpoDoPainel();
        textoAviso(corpo, "Carregando dados da conta...");
        try {
            // getMe() so na primeira vez por conexao - antes rodava a cada
            // "Voltar" pro menu (uma chamada de rede por clique).
            if (!dadosDaContaEmCache || dadosDaContaEmCache.cliente !== cliente) {
                dadosDaContaEmCache = { cliente, eu: await cliente.getMe() };
            }
            const eu = dadosDaContaEmCache.eu;
            // Etapa P5: confere a licenca no servidor (no maximo 1x/12h);
            // nao trava a tela se falhar (offline usa o token atual).
            if (eu && eu.id != null) conferirLicencaSePreciso(eu.id).catch(() => {});
            const nome = [eu.firstName, eu.lastName].filter(Boolean).join(" ") || "(sem nome)";
            const usuario = eu.username ? "@" + eu.username : "sem username público";
            corpo.innerHTML =
                '<div style="margin-bottom:10px;">' +
                '<div style="color:#4da3ff;font-weight:600;">Logado como ' +
                escapeHtml(nome) +
                "</div>" +
                '<div style="color:#a3aab8;">' +
                escapeHtml(usuario) +
                "</div>" +
                "</div>";
            dadosDaContaEmCache.nome = nome;
            dadosDaContaEmCache.usuario = usuario;

            // Precisa de uma pasta de verdade no disco escolhida/confirmada
            // ANTES de mostrar o resto do menu - toda tela daqui pra frente
            // chama abrirBanco(), que exige isso. So pede de novo quando
            // realmente precisa (primeira vez, ou permissao revogada pelo
            // navegador) - nao em toda abertura do painel.
            const pastaPronta = await garantirPastaDeArmazenamento();
            if (!pastaPronta) {
                await renderizarEscolhaDePasta(corpo);
                atualizarVisibilidadeSair(true);
                return;
            }

            // Produto, primeiro uso: passo 5 (primeiro scan) antes do menu.
            if (boasVindasEmAndamento()) return telaPrimeiroScan();
            corpo.innerHTML = "";
            await montarMenuEmGrade(corpo, nome, usuario);
        } catch (erro) {
            textoAviso(corpo, "Erro ao carregar a conta: " + (erro && erro.message ? erro.message : erro), "#ff6b6b");
        }
    }

    // ---- Menu inicial em grade (rodada 6) ----
    //
    // 6 botoes quadrados (3 por linha; 2 quando o painel fica estreito),
    // cada um com icone, nome curto e uma linha de informacao. As telas que
    // eram separadas viraram abas: Mais reagidas (Top reacoes / Minhas
    // reacoes), Buscar (No que escaneei / No Telegram), Downloads (Arquivos /
    // Em lote). Rodape: Ajustes (conta, pasta, backup, ferramentas, sair).

    function telaMaisReagidas() {
        return lerPreferencia("aba_reagidas") === "minhas" ? telaMinhasReacoes() : telaResultados();
    }
    function telaBuscar() {
        return lerPreferencia("aba_buscar") === "telegram" ? telaBuscaAvancada() : telaBusca();
    }
    function telaDownloadsEmAbas() {
        return lerPreferencia("aba_downloads") === "lote" ? telaLote() : telaDownloads();
    }

    function tempoRelativo(iso) {
        const ms = Date.now() - Date.parse(iso);
        if (!isFinite(ms) || ms < 0) return "agora";
        const minutos = Math.floor(ms / 60000);
        if (minutos < 1) return "agora";
        if (minutos < 60) return "há " + minutos + " min";
        const horas = Math.floor(minutos / 60);
        if (horas < 48) return "há " + horas + " h";
        return "há " + Math.floor(horas / 24) + " dias";
    }

    // Linha de informacao de cada botao do menu (so leitura, em memoria).
    function informacoesDoMenu(db) {
        let ultimoScan = null;
        for (const chat of db.chats.values()) if (chat.lastScannedAt && (!ultimoScan || chat.lastScannedAt > ultimoScan)) ultimoScan = chat.lastScannedAt;
        let comReacao = 0;
        for (const valor of db.indice.values()) if ((valor.reactionTotal || 0) > 0) comReacao++;
        const estado = db.monitorados || { pessoas: [], rastreadores: [] };
        const novas = totalDeNovos(estado);
        const favoritos = db.favoritos ? db.favoritos.mensagens.length + db.favoritos.buscas.length : 0;
        const fila = resumoDaFila();
        return {
            escanear: scanEmAndamento ? "escaneando agora" : ultimoScan ? "último scan " + tempoRelativo(ultimoScan) : "nenhum scan ainda",
            reagidas: comReacao + " mensagens com reação",
            buscar: db.indice.size + " mensagens salvas",
            monitorados: novas
                ? novas + (novas > 1 ? " novas" : " nova")
                : estado.pessoas.length || estado.rastreadores.length
                ? [estado.pessoas.length ? estado.pessoas.length + " pessoa(s)" : "", estado.rastreadores.length ? estado.rastreadores.length + " rastreador(es)" : ""].filter(Boolean).join(", ") + ", sem novas"
                : "ninguém ainda",
            favoritos: favoritos + " salvo(s)",
            downloads: fila.baixando || fila.naFila
                ? fila.baixando + " baixando" + (fila.naFila ? ", " + fila.naFila + " na fila" : "")
                : typeof loteEmExecucao !== "undefined" && loteEmExecucao
                ? "lote rodando"
                : "nada baixando",
        };
    }

    function botaoDoMenu(grade, { id, icone, rotulo, info, abrir }) {
        const botao = document.createElement("button");
        botao.type = "button";
        botao.id = id;
        botao.className = "trp-botao-menu";
        botao.style.cssText =
            "position:relative;display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;gap:10px;min-height:112px;" +
            "padding:14px;text-align:left;background:" + CORES.superficie + ";border:1px solid " + CORES.borda + ";border-radius:10px;" +
            "color:" + CORES.texto + ";cursor:pointer;font-family:inherit;";
        botao.innerHTML =
            '<span style="color:' + CORES.destaque + ';">' + iconeSvg(icone, 28) + "</span>" +
            '<span style="display:block;">' +
            '<span class="trp-rotulo" style="display:block;font-size:15px;font-weight:700;">' + escapeHtml(rotulo) + "</span>" +
            '<span class="trp-info" style="display:block;font-size:13px;color:' + CORES.textoSecundario + ';margin-top:2px;">' + escapeHtml(info || "") + "</span>" +
            "</span>";
        botao.addEventListener("mouseenter", () => (botao.style.borderColor = CORES.destaque));
        botao.addEventListener("mouseleave", () => (botao.style.borderColor = botao.dataset.borda || CORES.borda));
        botao.addEventListener("click", abrir);
        grade.appendChild(botao);
        return botao;
    }

    async function montarMenuEmGrade(corpo, nome, usuario) {
        const db = await abrirBanco();
        const info = informacoesDoMenu(db);
        if (typeof avisoDeQuebraNoMenu === "function") avisoDeQuebraNoMenu(corpo); // etapa P5: aviso se o Telegram mudou
        const grade = document.createElement("div");
        grade.className = "trp-menu-grade";
        grade.style.cssText = "display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:10px;margin-bottom:14px;";
        corpo.appendChild(grade);
        botaoDoMenu(grade, { id: "trp-botao-escanear", icone: "escanear", rotulo: "Escanear", info: info.escanear, abrir: () => telaScanner() });
        botaoDoMenu(grade, { id: "trp-botao-reagidas", icone: "reagidas", rotulo: "Mais reagidas", info: info.reagidas, abrir: () => telaMaisReagidas() });
        botaoDoMenu(grade, { id: "trp-botao-buscar", icone: "buscar", rotulo: "Buscar", info: info.buscar, abrir: () => telaBuscar() });
        botaoDoMenu(grade, { id: "trp-botao-monitorados", icone: "monitorados", rotulo: "Monitorados", info: info.monitorados, abrir: () => telaMonitorados() });
        botaoDoMenu(grade, { id: "trp-botao-favoritos", icone: "favoritos", rotulo: "Favoritos", info: info.favoritos, abrir: () => telaFavoritos() });
        botaoDoMenu(grade, { id: "trp-botao-downloads", icone: "downloads", rotulo: "Downloads", info: info.downloads, abrir: () => telaDownloadsEmAbas() });
        atualizarContadoresDeNovos(db);

        const rodape = document.createElement("div");
        rodape.style.cssText = "display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px;border-top:1px solid " + CORES.borda + ";padding-top:10px;";
        const conta = document.createElement("span");
        conta.style.cssText = "color:" + CORES.textoSecundario + ";font-size:13px;min-width:0;";
        conta.textContent = "Conta: " + nome + " (" + usuario + ")";
        rodape.appendChild(conta);
        const botoesDoRodape = document.createElement("div");
        botoesDoRodape.style.cssText = "display:flex;gap:8px;flex-shrink:0;";
        rodape.appendChild(botoesDoRodape);
        const botaoDoRodape = (id, icone, rotulo, abrir) => {
            const botao = document.createElement("button");
            botao.type = "button";
            botao.id = id;
            botao.innerHTML = '<span style="color:' + CORES.destaque + ';">' + iconeSvg(icone, 18) + '</span><span style="font-size:14px;font-weight:600;">' + rotulo + "</span>";
            botao.style.cssText =
                "display:inline-flex;align-items:center;gap:6px;padding:7px 12px;background:" + CORES.superficie + ";border:1px solid " + CORES.borda + ";border-radius:8px;color:" + CORES.texto + ";cursor:pointer;flex-shrink:0;";
            botao.addEventListener("click", abrir);
            botoesDoRodape.appendChild(botao);
            return botao;
        };
        botaoDoRodape("trp-botao-ajuda", "ajuda", "Ajuda", () => telaAjuda());
        botaoDoRodape("trp-botao-ajustes", "ajustes", "Ajustes", () => telaConfiguracoes());
        corpo.appendChild(rodape);
    }

    // Mostra o passo de escolher/reconfirmar a pasta de armazenamento no
    // disco - so aparece quando garantirPastaDeArmazenamento() nao
    // conseguiu resolver sozinho (primeira vez neste navegador/perfil, ou
    // permissao revogada). showDirectoryPicker/requestPermission exigem um
    // clique de verdade do usuario, por isso isso nao pode acontecer
    // sozinho, precisa de um botao.
    async function renderizarEscolhaDePasta(corpo) {
        if (!window.showDirectoryPicker) {
            textoAviso(
                corpo,
                'Este navegador não suporta a escolha de pasta (File System Access). Funciona em Chrome ou Edge - abra o painel num desses pra continuar.',
                "#ff6b6b"
            );
            return;
        }

        const salva = await lerPastaSalva().catch(() => null);
        faixaDoPrimeiroUso(corpo, 4);
        // Produto (etapa P3): pasta recomendada em Documentos e aviso de
        // pasta com dados de outra instalacao (boas_vindas.js).
        if (!salva && CONFIG.pastaSugerida) {
            passoDaPastaRecomendada(corpo);
            return;
        }
        const bloco = document.createElement("div");
        bloco.style.cssText = "margin-bottom:10px;";
        bloco.innerHTML = salva
            ? '<div style="color:#ff6b6b;font-weight:600;margin-bottom:6px;">Precisa reconfirmar o acesso à pasta</div>' +
              '<div style="color:#a3aab8;margin-bottom:10px;">O navegador revogou a permissão (acontece às vezes depois de reiniciar) - clique abaixo pra reconfirmar o acesso à mesma pasta de sempre. Nenhum dado é perdido com isso.</div>'
            : '<div style="color:#4da3ff;font-weight:600;margin-bottom:6px;">Escolher pasta de armazenamento</div>' +
              '<div style="color:#a3aab8;margin-bottom:10px;">As mensagens escaneadas agora ficam guardadas numa pasta de verdade no seu disco, escolhida por você - pode ser dentro do OneDrive ou do Google Drive sincronizado, assim a nuvem acontece sozinha. Isso substitui o armazenamento interno do navegador (que tem teto baixo e some se você "limpar dados do navegador").</div>';
        corpo.appendChild(bloco);

        const botao = botaoAcao(corpo, salva ? "Reconfirmar acesso à pasta" : "Escolher pasta de armazenamento");
        botao.addEventListener("click", async () => {
            botao.disabled = true;
            try {
                if (salva) {
                    await reconfirmarPermissaoPasta(salva);
                } else {
                    await escolherPastaDeArmazenamento();
                }
                await telaLogado();
            } catch (erro) {
                botao.disabled = false;
                if (erro && erro.name === "AbortError") return; // usuario fechou o seletor sem escolher nada - nao e erro de verdade
                textoAviso(corpo, "Não foi possível confirmar a pasta: " + (erro && erro.message ? erro.message : erro), "#ff6b6b");
            }
        });
    }

    // destino: tela pra onde volta (padrao: o menu). As telas que agora
    // ficam dentro de Configuracoes voltam pra ela.
    function botaoVoltar(corpo, destino) {
        const botao = document.createElement("button");
        botao.textContent = "← Voltar";
        // Antes era texto puro sem fundo nem borda (font-size:13px) - dificil
        // de identificar rapido entre o resto da tela. Agora tem contorno e
        // area de clique maior, continua discreto (sem cor de destaque igual
        // os botoes de acao) mas facil de achar.
        botao.style.cssText =
            "background:#0c0e12;border:1px solid #2a2f3a;border-radius:6px;color:#c7cbd4;cursor:pointer;" +
            "font-size:13px;font-weight:600;margin-bottom:12px;padding:6px 12px;";
        botao.addEventListener("click", () => (destino ? destino() : telaLogado()));
        corpo.appendChild(botao);
        return botao;
    }

    // ---- Tela de scan ----

    // Itera TODOS os grupos/canais da conta, incluindo os que estao na
    // pasta "Arquivados" do Telegram - cliente.iterDialogs({}) sozinho so
    // devolve a pasta principal. Sem isso, um grupo que foi arquivado DEPOIS
    // de ja ter sido escaneado nunca mais aparece em "Configurar grupos" pra
    // poder ser excluido - ele fica preso pra sempre nas listas de
    // status/busca (que leem direto do que ja foi salvo no disco, sem
    // ligar se o grupo ainda esta na pasta principal) sem nenhum jeito de
    // tirar ele de la pela tela de configuracao. Toda funcao que precisa
    // enumerar "todos os grupos/canais da conta" usa essa, nunca
    // cliente.iterDialogs({}) direto.
    //
    // Sem repetir: pela documentacao do Telethon (que o teleproto espelha),
    // iterDialogs sem "archived" devolve TODOS os dialogs, arquivados
    // inclusive - nesse caso a segunda passada repetiria cada grupo
    // arquivado (scan dele 2x por rodada, "grupo X de Y" inflado, item
    // duplicado nas listas). Nao deu pra confirmar contra a conta real qual
    // dos dois comportamentos o servidor tem; o filtro por id e inofensivo
    // nos dois casos.
    async function* iterTodosOsDialogs() {
        const vistos = new Set();
        for (const opcoes of [{}, { archived: true }]) {
            for await (const dialog of cliente.iterDialogs(opcoes)) {
                const id = String(dialog.id);
                if (vistos.has(id)) continue;
                vistos.add(id);
                yield dialog;
            }
        }
    }

    // Lista de dialogs em cache por 2 minutos. Antes, abrir a tela de scan
    // percorria TODOS os dialogs da conta duas vezes (lista do seletor e
    // aviso de "tem mensagem nova"), e "Buscar ao vivo", "Verificar
    // mensagem" e o Alt+clique percorriam de novo a cada uso so pra achar
    // um chat - com centenas de grupos, segundos de espera e chamadas de API
    // repetidas. forcar=true ignora o cache (o scan sempre usa a lista
    // fresca). Quem chama enquanto ja esta carregando recebe a mesma
    // promessa.
    const VALIDADE_CACHE_DIALOGS_MS = 2 * 60 * 1000;
    let cacheDialogs = null; // { quando, lista, porId }
    let carregandoDialogs = null;
    async function listarDialogs(forcar) {
        if (!forcar && cacheDialogs && Date.now() - cacheDialogs.quando < VALIDADE_CACHE_DIALOGS_MS) {
            return cacheDialogs.lista;
        }
        if (!carregandoDialogs) {
            carregandoDialogs = (async () => {
                const lista = [];
                for await (const dialog of iterTodosOsDialogs()) lista.push(dialog);
                cacheDialogs = { quando: Date.now(), lista, porId: new Map(lista.map((d) => [String(d.id), d])) };
                return lista;
            })();
            carregandoDialogs.then(
                () => (carregandoDialogs = null),
                () => (carregandoDialogs = null)
            );
        }
        return carregandoDialogs;
    }

    function limparCacheDaConta() {
        cacheDialogs = null;
        dadosDaContaEmCache = null;
    }

    // Lista os grupos/canais da conta (pra popular o seletor de "qual grupo
    // escanear"). Separado de escanearTudo porque aqui so queremos
    // id+titulo, sem mexer no banco.
    async function carregarGruposParaSelecao() {
        const grupos = [];
        for (const dialog of await listarDialogs(false)) {
            if (!(dialog.isGroup || dialog.isChannel)) continue;
            grupos.push({ chatId: String(dialog.id), titulo: dialog.title || dialog.name || String(dialog.id) });
        }
        grupos.sort((a, b) => a.titulo.localeCompare(b.titulo));
        return grupos;
    }

    // ---- Tela de configuracao: quais grupos/canais entram no "Todos" do scan ----

    // Grupo desmarcado aqui some de TODO lugar (tabela de status, seletores
    // de busca e tambem do dropdown "Grupo/canal a escanear" da tela de
    // scan) ate ser marcado de novo - um unico comportamento consistente em
    // vez de excecao por tela. Pra escanear um grupo excluido manualmente,
    // marca ele aqui de novo primeiro. A lista inclui grupos arquivados (ver
    // iterTodosOsDialogs) e tambem grupos que o usuario ja saiu / mudaram de
    // id (ver reconciliacao com listarChats(db) dentro da funcao) - sem isso
    // esses dois casos nunca apareciam aqui pra poder ser excluidos, mesmo
    // com dados ja escaneados deles poluindo as outras telas pra sempre.
    async function telaConfigurarGrupos() {
        definirTituloTela("Grupos do scan");
        const corpo = corpoDoPainel();
        botaoVoltar(corpo, () => telaScanner());

        const aviso = document.createElement("div");
        aviso.style.cssText = "display:flex;align-items:center;gap:4px;color:#a3aab8;margin-bottom:10px;";
        aviso.innerHTML =
            '<span>Desmarca os grupos/canais que você NÃO quer no scan.</span>' +
            criarIconeInfoHtml(
                'Desmarca os grupos/canais que você NÃO quer acompanhar. Grupo novo que você entrar aparece aqui automaticamente, já marcado pra escanear. Um grupo desmarcado aqui some de tudo até ser marcado de novo: do scan com "Todos" selecionado, do dropdown "Grupo/canal a escanear" (pra escanear ele mesmo assim, marca de novo aqui primeiro), do seletor de grupo nas telas de busca, e da tabela "O que já está salvo" na tela de scan.'
            );
        corpo.appendChild(aviso);

        // Campo de filtro + contador ficam escondidos ate a lista carregar
        // (nao tem o que filtrar/contar antes disso) - pedido do usuario,
        // que com a conta cheia de grupos nao conseguia confirmar de
        // relance se um grupo especifico (que ele tinha acabado de entrar)
        // estava mesmo nessa lista ou nao.
        const blocoFiltro = document.createElement("div");
        blocoFiltro.style.cssText = "display:none;margin-bottom:8px;";
        blocoFiltro.innerHTML =
            '<input id="trp-filtro-grupos" type="text" placeholder="Filtrar por nome..." ' +
            'style="width:100%;background:#0c0e12;color:#e6e8ec;border:1px solid #2a2f3a;border-radius:6px;' +
            'padding:8px;box-sizing:border-box;margin-bottom:4px;">' +
            '<div id="trp-contador-grupos" style="color:#a3aab8;font-size:13px;"></div>';
        corpo.appendChild(blocoFiltro);
        const campoFiltro = blocoFiltro.querySelector("#trp-filtro-grupos");
        const contador = blocoFiltro.querySelector("#trp-contador-grupos");

        const lista = document.createElement("div");
        lista.style.cssText = "color:#a3aab8;";
        lista.textContent = "Carregando lista de grupos...";
        corpo.appendChild(lista);

        try {
            const grupos = await carregarGruposParaSelecao();
            const excluidos = carregarGruposExcluidos();

            // Reconciliacao com o que ja foi escaneado: um grupo que o
            // usuario SAIU, ou que mudou de chatId (grupo comum virou
            // supergrupo - Telegram troca o id nessa migracao), nao aparece
            // em carregarGruposParaSelecao() (que so ve a conta HOJE) mas os
            // dados escaneados dele continuam no disco pra sempre, e sem
            // aparecer aqui o usuario nunca consegue marcar ele como
            // excluido. Mostra esses tambem, separados, com o titulo salvo
            // na epoca do scan.
            const idsAtuais = new Set(grupos.map((g) => g.chatId));
            const db = await abrirBanco();
            const chatsSalvos = await listarChats(db);
            const orfaos = chatsSalvos.filter((c) => !idsAtuais.has(c.chatId));

            if (!grupos.length && !orfaos.length) {
                lista.textContent = "Nenhum grupo/canal encontrado nessa conta.";
                return;
            }

            const todosOsItens = [
                ...grupos.map((g) => ({ chatId: g.chatId, titulo: g.titulo, origemDesconhecida: false })),
                ...orfaos.map((c) => ({
                    chatId: c.chatId,
                    titulo: c.chatTitle || c.chatId,
                    origemDesconhecida: true,
                })),
            ];

            const criarLinha = (chatId, titulo, origemDesconhecida) => {
                const linha = document.createElement("div");
                linha.style.cssText =
                    "display:flex;align-items:flex-start;gap:8px;padding:6px 0;border-bottom:1px solid #2a2f3a;";
                const quadrado = criarQuadradoMarcavel(!excluidos.has(chatId), (incluido) => {
                    if (incluido) excluidos.delete(chatId);
                    else excluidos.add(chatId);
                    salvarGruposExcluidos(excluidos);
                });
                const rotulo = document.createElement("span");
                rotulo.textContent = titulo;
                linha.appendChild(quadrado.elemento);
                linha.appendChild(rotulo);
                if (origemDesconhecida) {
                    const nota = document.createElement("span");
                    nota.style.cssText = "color:#a3aab8;font-size:13px;margin-left:4px;";
                    nota.textContent = "(não está mais na sua lista de conversas - saiu do grupo ou ele mudou de id)";
                    linha.appendChild(nota);
                }
                lista.appendChild(linha);
            };

            // Reaplicado a cada letra digitada no filtro - "excluidos" (e os
            // proprios checkboxes, atraves dele) nao se perde entre
            // redesenhos porque o estado mora no Set/no storage, nunca no
            // DOM: cada redesenho so LE excluidos.has(chatId) de novo pra
            // decidir o estado inicial do quadrado.
            function renderizarLista(filtro) {
                lista.innerHTML = "";
                const termo = filtro.trim().toLowerCase();
                const itensFiltrados = termo
                    ? todosOsItens.filter((item) => item.titulo.toLowerCase().includes(termo))
                    : todosOsItens;
                contador.textContent = termo
                    ? `${itensFiltrados.length} de ${todosOsItens.length} grupos/canais`
                    : `${todosOsItens.length} grupos/canais encontrados`;
                if (!itensFiltrados.length) {
                    lista.innerHTML = '<div style="color:#a3aab8;font-size:13px;">Nenhum grupo/canal bate com esse filtro.</div>';
                    return;
                }
                for (const item of itensFiltrados) criarLinha(item.chatId, item.titulo, item.origemDesconhecida);
            }

            blocoFiltro.style.display = "block";
            renderizarLista("");
            campoFiltro.addEventListener("input", () => renderizarLista(campoFiltro.value));
        } catch (erro) {
            lista.textContent = "Erro ao carregar grupos: " + (erro && erro.message ? erro.message : erro);
        }
    }

    // ---- Tela de configuracao: historico de termos pesquisados ----

    // So dava pra limpar o historico todo de uma vez (apagando o
    // GM_setValue direto no storage do Tampermonkey) - pedido do usuario:
    // poder tirar so um termo especifico da lista de sugestao, sem perder o
    // resto. Dois historicos separados (busca local "Buscar mensagens" e
    // busca global "Busca avancada"), cada um com seu botao de limpar tudo.
    function telaHistoricoBusca() {
        definirTituloTela("Histórico de buscas");
        const corpo = corpoDoPainel();
        botaoVoltar(corpo, () => telaBuscar());

        const renderizarBloco = (titulo, chave) => {
            const secao = document.createElement("div");
            secao.style.marginBottom = "16px";

            const cabecalho = document.createElement("div");
            cabecalho.style.cssText = "display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;";
            const rotulo = document.createElement("span");
            rotulo.style.cssText = "color:#a3aab8;font-weight:600;";
            rotulo.textContent = titulo;
            cabecalho.appendChild(rotulo);

            const botaoLimparTudo = document.createElement("button");
            botaoLimparTudo.textContent = "Limpar tudo";
            botaoLimparTudo.style.cssText =
                "background:none;border:1px solid #2a2f3a;border-radius:6px;color:#ff6b6b;cursor:pointer;" +
                "font-size:13px;padding:3px 8px;";
            cabecalho.appendChild(botaoLimparTudo);
            secao.appendChild(cabecalho);

            const lista = document.createElement("div");
            secao.appendChild(lista);
            corpo.appendChild(secao);

            const renderizarLista = () => {
                const termos = carregarHistoricoBusca(chave);
                lista.innerHTML = "";
                if (!termos.length) {
                    lista.innerHTML = '<div style="color:#a3aab8;font-size:13px;">Nenhum termo buscado ainda.</div>';
                    return;
                }
                for (const termo of termos) {
                    const linha = document.createElement("div");
                    linha.style.cssText =
                        "display:flex;align-items:center;justify-content:space-between;gap:8px;padding:5px 0;" +
                        "border-bottom:1px solid #2a2f3a;";
                    const texto = document.createElement("span");
                    texto.style.cssText = "overflow-wrap:anywhere;";
                    texto.textContent = termo;
                    const botaoRemover = document.createElement("button");
                    botaoRemover.textContent = "✕";
                    botaoRemover.title = "Tirar esse termo do histórico";
                    botaoRemover.style.cssText =
                        "background:none;border:none;color:#a3aab8;cursor:pointer;font-size:13px;flex-shrink:0;";
                    botaoRemover.addEventListener("click", () => {
                        removerTermoDoHistorico(chave, termo);
                        renderizarLista();
                    });
                    linha.appendChild(texto);
                    linha.appendChild(botaoRemover);
                    lista.appendChild(linha);
                }
            };
            renderizarLista();

            botaoLimparTudo.addEventListener("click", () => {
                GM_setValue(chave, "[]");
                renderizarLista();
            });
        };

        renderizarBloco('Histórico de "No que escaneei"', CHAVE_HISTORICO_BUSCA_LOCAL);
        renderizarBloco('Histórico de "No Telegram"', CHAVE_HISTORICO_BUSCA_GLOBAL);
    }

    // ---- Tela de configuracao: backup dos dados escaneados ----

    // Os dados moram na pasta escolhida no disco (desde v2026.10.11.1);
    // copiar a pasta e o backup mais seguro. Isto aqui exporta
    // chats+mensagens num arquivo .json so, e importa de volta quando
    // precisar. Importar grava registro por
    // registro - nunca apaga nada que ja esta no banco e nao esta no
    // arquivo, so sobrescreve registros com a mesma chave (mesmo chatId ou
    // mesma mensagem) - por isso e seguro restaurar por cima de um banco
    // que ja tem dado, sem precisar de nenhuma confirmacao tipo "isso vai
    // apagar tudo".
    function telaBackup() {
        definirTituloTela("Backup");
        const corpo = corpoDoPainel();
        botaoVoltar(corpo, () => telaConfiguracoes());

        const aviso = document.createElement("div");
        aviso.style.cssText = "display:flex;align-items:center;gap:4px;color:#a3aab8;margin-bottom:14px;";
        aviso.innerHTML =
            '<span>Os dados já ficam na pasta que você escolheu no disco - copiar essa pasta é o backup mais seguro.</span>' +
            criarIconeInfoHtml(
                'Desde a v2026.10.11.1 tudo que o scan encontra fica em arquivos na pasta de armazenamento escolhida (chats.json, indice.jsonl e a pasta mensagens). Limpar dados do navegador NÃO apaga essa pasta. O jeito mais seguro de fazer backup e copiar a pasta inteira (com o painel fechado ou sem scan rodando). O .json abaixo junta tudo num arquivo só: prático pra histórico pequeno, mas com histórico muito grande (centenas de MB) o navegador pode ficar sem memória ao gerar ou ao importar. Importar nunca apaga dado que já está salvo - só sobrescreve o que tiver a mesma chave.'
            );
        corpo.appendChild(aviso);

        const botaoExportar = botaoAcao(corpo, "Exportar backup (.json)");
        const statusExportar = document.createElement("div");
        statusExportar.style.cssText = "color:#a3aab8;font-size:13px;margin:-4px 0 14px;";
        corpo.appendChild(statusExportar);

        botaoExportar.addEventListener("click", async () => {
            botaoExportar.disabled = true;
            statusExportar.textContent = "Lendo banco local...";
            const nomeArquivo = "gestor-tlgr-backup-" + new Date().toISOString().slice(0, 10) + ".json";
            const mostrarProgresso = (texto) => (statusExportar.textContent = texto);
            try {
                const db = await abrirBanco();
                await descarregarEscritasPendentes(db);
                let resumo;
                if (window.showSaveFilePicker) {
                    let destino;
                    try {
                        destino = await window.showSaveFilePicker({
                            suggestedName: nomeArquivo,
                            types: [{ description: "Backup TLGMaster", accept: { "application/json": [".json"] } }],
                        });
                    } catch (erro) {
                        if (erro && erro.name === "AbortError") {
                            statusExportar.textContent = "";
                            return; // fechou a janela sem escolher - nao e erro
                        }
                        throw erro;
                    }
                    const escrita = await destino.createWritable();
                    try {
                        resumo = await gerarPedacosDoBackup(db, (pedaco) => escrita.write(pedaco), mostrarProgresso);
                        await escrita.close();
                    } catch (erro) {
                        await escrita.abort().catch(() => {});
                        throw erro;
                    }
                } else {
                    const pedacos = [];
                    resumo = await gerarPedacosDoBackup(db, (pedaco) => pedacos.push(pedaco), mostrarProgresso);
                    const url = URL.createObjectURL(new Blob(pedacos, { type: "application/json" }));
                    const link = document.createElement("a");
                    link.href = url;
                    link.download = nomeArquivo;
                    link.click();
                    setTimeout(() => URL.revokeObjectURL(url), 60000); // revogar na hora pode cancelar o download em alguns navegadores
                }
                statusExportar.textContent = `Exportado: ${resumo.totalChats} grupo(s)/canal(is), ${resumo.totalMensagens} mensagem(ns).`;
            } catch (erro) {
                statusExportar.textContent = "Erro ao exportar: " + (erro && erro.message ? erro.message : erro);
            } finally {
                botaoExportar.disabled = false;
            }
        });

        const tituloImportar = document.createElement("div");
        tituloImportar.style.cssText = "color:#a3aab8;margin:18px 0 6px;font-weight:600;";
        tituloImportar.textContent = "Restaurar de um backup";
        corpo.appendChild(tituloImportar);

        const campoArquivo = document.createElement("input");
        campoArquivo.type = "file";
        campoArquivo.accept = ".json,application/json";
        campoArquivo.style.display = "none";
        corpo.appendChild(campoArquivo);

        const botaoImportar = botaoAcao(corpo, "Escolher arquivo de backup...");
        const statusImportar = document.createElement("div");
        statusImportar.style.cssText = "color:#a3aab8;font-size:13px;margin-top:-4px;white-space:pre-line;";
        corpo.appendChild(statusImportar);

        botaoImportar.addEventListener("click", () => campoArquivo.click());

        campoArquivo.addEventListener("change", async () => {
            const arquivo = campoArquivo.files && campoArquivo.files[0];
            campoArquivo.value = ""; // permite escolher o mesmo arquivo de novo depois, se precisar
            if (!arquivo) return;

            botaoImportar.disabled = true;
            statusImportar.textContent = "Lendo arquivo...";
            try {
                const texto = await arquivo.text();
                const backup = JSON.parse(texto);
                if (
                    !backup ||
                    backup.formato !== "gestor-tlgr-backup" ||
                    !Array.isArray(backup.chats) ||
                    !Array.isArray(backup.mensagens)
                ) {
                    statusImportar.textContent = "Arquivo inválido - não parece ser um backup do TLGMaster.";
                    return;
                }

                const db = await abrirBanco();
                let restauradas = 0;
                for (const mensagem of backup.mensagens) {
                    // Em lote (ver "Gravacao em lote" perto de abrirBanco) -
                    // 1 gravacao por mensagem copiava o indice inteiro a cada vez.
                    await salvarMensagem(db, mensagem, { adiarGravacao: true });
                    restauradas++;
                    if (restauradas % 1000 === 0) {
                        statusImportar.textContent = `Restaurando mensagens... ${restauradas} de ${backup.mensagens.length}`;
                    }
                }
                await descarregarEscritasPendentes(db);
                // Checkpoints dos chats so DEPOIS das mensagens gravadas: se a
                // importacao parar no meio, nenhum chat fica marcado como
                // escaneado ate um ponto cujas mensagens nao estao no disco.
                statusImportar.textContent = `Restaurando ${backup.chats.length} grupo(s)/canal(is)...`;
                for (const chat of backup.chats) await salvarChat(db, chat);

                statusImportar.textContent =
                    `Restaurado: ${backup.chats.length} grupo(s)/canal(is), ${backup.mensagens.length} mensagem(ns)` +
                    (backup.geradoEm ? ` (backup gerado em ${new Date(backup.geradoEm).toLocaleString()})` : "") +
                    ".";
            } catch (erro) {
                statusImportar.textContent = "Erro ao importar: " + (erro && erro.message ? erro.message : erro);
            } finally {
                botaoImportar.disabled = false;
            }
        });
    }

    // Acha o dialog.entity de um chat ja escaneado, pelo chatId guardado -
    // precisa disso (em vez de so o chatId numerico) pra poder chamar
    // cliente.getMessages, do mesmo jeito que escanearTudo usa
    // dialog.entity pra chamar iterMessages. So itera os dialogs ate achar
    // (nao da pra montar o InputPeer so com o chatId sem o access_hash).
    async function encontrarEntidadePorChatId(chatId) {
        await listarDialogs(false);
        let dialog = cacheDialogs && cacheDialogs.porId.get(chatId);
        if (!dialog) {
            await listarDialogs(true); // grupo que a conta acabou de entrar ainda nao estava no cache
            dialog = cacheDialogs && cacheDialogs.porId.get(chatId);
        }
        return dialog ? dialog.entity : null;
    }

    // Pega, numa unica passada por iterDialogs (a mesma chamada ja usada em
    // carregarGruposParaSelecao/escanearTudo, sem custo extra de API por
    // chat), o id da ultima mensagem de verdade que existe HOJE em cada
    // grupo/canal - dialog.message.id, de graca junto com a lista de dialogs,
    // sem precisar abrir o historico de cada um. Comparado com
    // lastScannedMessageId (o que a gente salvou), da pra saber se um grupo
    // tem mensagem nova que o scan ainda nao viu, sem escanear nada - so
    // serve de aviso (badge "desatualizado"), nao substitui rodar o scan de
    // verdade.
    async function buscarUltimaMensagemPorChat(forcar) {
        const mapa = new Map();
        for (const dialog of await listarDialogs(forcar)) {
            if (!(dialog.isGroup || dialog.isChannel)) continue;
            mapa.set(String(dialog.id), dialog.message ? dialog.message.id : null);
        }
        return mapa;
    }

    // Mostra o que ja esta salvo por grupo: quantas mensagens com reacao,
    // quando foi o ultimo scan e se terminou de verdade (concluido) ou ficou
    // parcial (cancelado no meio). Sem isso o usuario fica as cegas sobre o
    // que ja rodou. "ultimasMensagens" (opcional, vindo de
    // buscarUltimaMensagemPorChat) acrescenta o aviso de "desatualizado" -
    // calculado so uma vez por abertura da tela de scan (ver telaScanner()),
    // nao a cada vez que essa funcao e chamada de novo (ela e chamada varias
    // vezes durante um scan em andamento, repetir o iterDialogs a cada
    // checkpoint seria caro e sem necessidade).
    async function renderizarTabelaChats(container, db, ultimasMensagens) {
        // Grupo desmarcado em "Configurar grupos" some daqui tambem (e do
        // seletor de grupo nas telas de busca) - so volta a aparecer se o
        // usuario marcar ele de novo la. Pedido do usuario: grupo que ele
        // nao quer mais acompanhar nao devia continuar poluindo a lista de
        // status so porque foi escaneado um dia.
        const excluidos = carregarGruposExcluidos();
        const todosOsChatsSalvos = await listarChats(db);
        const chats = todosOsChatsSalvos.filter((c) => !excluidos.has(c.chatId));
        chats.sort((a, b) => (a.chatTitle || "").localeCompare(b.chatTitle || ""));
        // Quantos sumiram daqui por estarem desmarcados em "Configurar
        // grupos" - antes a lista so encolhia silenciosamente, sem nenhuma
        // pista de que havia mais chats escaneados alem dos visiveis aqui.
        const quantidadeOculta = todosOsChatsSalvos.length - chats.length;
        const notaOcultosHtml = quantidadeOculta
            ? '<div style="color:#a3aab8;font-size:13px;margin-top:6px;">' +
              (quantidadeOculta === 1
                  ? "+1 grupo oculto (desmarcado em \"Grupos do scan\")"
                  : "+" + quantidadeOculta + ' grupos ocultos (desmarcados em "Grupos do scan")') +
              "</div>"
            : "";
        if (!chats.length) {
            container.innerHTML =
                '<div style="color:#a3aab8;">Nenhum grupo escaneado ainda (ou todos os escaneados estão desmarcados em "Grupos do scan").</div>' +
                notaOcultosHtml;
            return;
        }
        const linhas = [];
        for (const c of chats) {
            const total = await contarMensagensDoChat(db, c.chatId);
            const quando = c.lastScannedAt ? new Date(c.lastScannedAt).toLocaleString() : "-";
            const backfillPendente = typeof c.backfillAlvo === "number" && (c.textoCompletoAte || 0) < c.backfillAlvo;
            const badge = !c.concluido
                ? '<span style="color:#ff6b6b;">parcial</span>'
                : backfillPendente
                ? '<span style="color:#4da3ff;">completando histórico antigo</span>'
                : '<span style="color:#5ec26a;">completo</span>';
            const ultimoIdReal = ultimasMensagens ? ultimasMensagens.get(c.chatId) : undefined;
            const desatualizado = ultimoIdReal != null && ultimoIdReal > (c.lastScannedMessageId || 0);
            const percentual = percentualEscaneado(c, ultimoIdReal);
            const avisoDesatualizado = desatualizado
                ? ' <span style="color:#4da3ff;" title="Tem mensagem nova no grupo desde o último scan - roda o scan de novo (é rápido, só busca o que é novo) pra essa mensagem entrar no cálculo de reações.">⟳ tem mensagem nova</span>'
                : "";
            linhas.push(
                "<tr>" +
                    '<td style="padding:4px 6px;">' +
                    escapeHtml(c.chatTitle || c.chatId) +
                    "</td>" +
                    '<td style="padding:4px 6px;text-align:right;">' +
                    total +
                    "</td>" +
                    '<td style="padding:4px 6px;text-align:right;" title="Até onde o scan chegou, comparado com a mensagem mais nova do grupo agora. Cai sozinho quando o grupo recebe mensagem nova e volta a 100% depois do scan.">' +
                    (percentual == null ? "-" : "~" + percentual + "%") +
                    "</td>" +
                    '<td style="padding:4px 6px;">' +
                    badge +
                    avisoDesatualizado +
                    "</td>" +
                    '<td style="padding:4px 6px;color:#a3aab8;font-size:13px;">' +
                    escapeHtml(quando) +
                    "</td>" +
                    "</tr>"
            );
        }
        // white-space:nowrap nos cabecalhos - eram so 1-2 palavras curtas
        // ("Status", "Ultimo scan") mas a coluna ficava estreita demais
        // (espremida pela coluna "Grupo", que precisa do espaco pro nome
        // do chat) e quebrava em 2 linhas, ficando com cara de erro.
        container.innerHTML =
            '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
            '<thead><tr style="color:#a3aab8;text-align:left;">' +
            '<th style="padding:4px 6px;white-space:nowrap;">Grupo</th>' +
            '<th style="padding:4px 6px;text-align:right;white-space:nowrap;">Salvas</th>' +
            '<th style="padding:4px 6px;text-align:right;white-space:nowrap;">Escaneado</th>' +
            '<th style="padding:4px 6px;white-space:nowrap;">Status</th>' +
            '<th style="padding:4px 6px;white-space:nowrap;">Último scan</th>' +
            "</tr></thead><tbody>" +
            linhas.join("") +
            "</tbody></table>" +
            notaOcultosHtml;
    }

    // Quanto do grupo o scan ja cobriu: id da ultima mensagem escaneada
    // sobre o id da mensagem mais nova do grupo agora (vem de graca na lista
    // de dialogs). Dinamico: o grupo recebe mensagem nova, o numero cai;
    // roda o scan, volta a 100%. So vale pra canal/supergrupo (ids proprios
    // de 1 em diante); grupo basico usa a numeracao da conta inteira, a
    // conta nao diria nada - fica "-". Aproximado: mensagem apagada conta
    // como se existisse; backfill do texto antigo pendente desconta o que
    // falta dele.
    function percentualEscaneado(chat, ultimoIdReal) {
        if (!ultimoIdReal || !String(chat.chatId).startsWith("-100")) return null;
        let cobertas = Math.min(chat.lastScannedMessageId || 0, ultimoIdReal);
        if (typeof chat.backfillAlvo === "number" && (chat.textoCompletoAte || 0) < chat.backfillAlvo) {
            cobertas -= chat.backfillAlvo - (chat.textoCompletoAte || 0);
        }
        return Math.max(0, Math.min(100, Math.floor((cobertas / ultimoIdReal) * 100)));
    }

    // Zera o checkpoint (lastScannedMessageId) do(s) chat(s) escolhido(s) -
    // faz o proximo scan reler a mensagem 1 em diante de novo, mesmo que ja
    // tivesse chegado no fim antes. So mexe em chat que JA tem registro
    // salvo (chat nunca escaneado ja comeca do zero, nao tem checkpoint pra
    // zerar). De proposito NAO toca em backfillAlvo/textoCompletoAte (o
    // controle separado de "completar o historico bem antigo") - zerar so
    // lastScannedMessageId ja basta pra forcar reler tudo, porque a fase 2
    // (iterMessages com minId:0) passa a varrer da primeira mensagem do
    // chat ate a mais recente de novo. "ultima linha vence" (ver
    // repetirJsonlUltimaVence) faz isso ser seguro - rescanear nao duplica
    // nada, so sobrescreve com a versao mais atual de cada mensagem.
    //
    // Pedido do usuario ("forcar um novo escaneamento"). Bonus pratico: e
    // tambem o unico jeito de uma mensagem ja escaneada ANTES de
    // v2026.10.11.2 ganhar o campo minhasReacoes (ver "Minhas reacoes") sem
    // esperar uma mensagem nova chegar naquele chat.
    //
    // "excluidos" (Set, opcional, so usado com "Todos"): grupo desmarcado
    // em "Configurar grupos" nao entra no scan "Todos", entao tambem nao
    // pode ter o checkpoint zerado por ele - antes era zerado mesmo assim e,
    // quando o usuario marcasse o grupo de novo, o scan normal recomecava
    // ele do zero sem ninguem ter pedido.
    async function resetarCheckpointsParaRescanCompleto(db, apenasChatId, excluidos) {
        const chatsParaResetar = apenasChatId
            ? [apenasChatId]
            : [...db.chats.keys()].filter((id) => !excluidos || !excluidos.has(id));
        for (const chatId of chatsParaResetar) {
            const chatSalvo = buscarChat(db, chatId);
            if (!chatSalvo) continue;
            await salvarChat(db, { ...chatSalvo, lastScannedMessageId: 0 });
        }
    }

    async function telaScanner() {
        definirTituloTela("Escanear");
        const corpo = corpoDoPainel();
        botaoVoltar(corpo);

        const db = await abrirBanco();

        const blocoSelecao = document.createElement("div");
        blocoSelecao.style.marginBottom = "10px";
        blocoSelecao.innerHTML =
            '<label style="display:block;color:#a3aab8;margin-bottom:4px;">Grupo/canal a escanear</label>' +
            '<select id="trp-select-grupo" style="width:100%;background:#0c0e12;color:#e6e8ec;border:1px solid #2a2f3a;border-radius:6px;padding:8px;box-sizing:border-box;">' +
            '<option value="">Todos (ordem que o Telegram devolver)</option>' +
            '<option value="" disabled id="trp-carregando-grupos">Carregando lista de grupos...</option>' +
            "</select>";
        corpo.appendChild(blocoSelecao);
        const selectGrupo = blocoSelecao.querySelector("#trp-select-grupo");
        selectGrupo.addEventListener("change", () => gravarPreferencia("scan_grupo", selectGrupo.value));

        // Grupo desmarcado em "Configurar grupos" nao aparece aqui tambem -
        // antes dessa correcao ele ficava escondido da tabela de status e
        // dos seletores de busca mas continuava aparecendo neste dropdown
        // (unica excecao que sobrou), o que o usuario reportou como
        // inconsistente. Pra escanear um grupo excluido manualmente agora e
        // so marcar ele de novo em "Configurar grupos" primeiro - mais
        // simples que manter uma excecao silenciosa so neste seletor.
        const excluidosParaDropdown = carregarGruposExcluidos();
        carregarGruposParaSelecao()
            .then((grupos) => {
                const carregando = selectGrupo.querySelector("#trp-carregando-grupos");
                if (carregando) carregando.remove();
                for (const g of grupos) {
                    if (excluidosParaDropdown.has(g.chatId)) continue;
                    const opcao = document.createElement("option");
                    opcao.value = g.chatId;
                    opcao.textContent = g.titulo;
                    selectGrupo.appendChild(opcao);
                }
                if (!scanEmAndamento) aplicarPreferenciaNoSelect(selectGrupo, "scan_grupo");
            })
            .catch(() => {
                const carregando = selectGrupo.querySelector("#trp-carregando-grupos");
                if (carregando) carregando.textContent = "Erro ao carregar lista de grupos.";
            });

        // Texto longo de explicacao vira label curto + icone "i" (mesmo
        // padrao das outras telas) - separado do "status" logo abaixo, que e
        // so pra mensagem DINAMICA de progresso do scan (escanearTudo()
        // escreve direto em status.textContent durante o scan).
        const aviso = document.createElement("div");
        aviso.style.cssText = "display:flex;align-items:center;gap:4px;color:#a3aab8;margin-bottom:6px;";
        aviso.innerHTML =
            '<span>Escolhe um grupo específico ou deixa em "Todos".</span>' +
            criarIconeInfoHtml(
                'Com "Todos" selecionado, respeita o que estiver desmarcado em "Grupos do scan" (grupo desmarcado lá não entra). Escolher um grupo específico aqui sempre escaneia ele, mesmo que esteja desmarcado em "Grupos do scan" - só precisa estar presente nesta lista (ou seja, marcado la). Continua de onde parou da última vez - pode parar e retomar a hora que quiser. Histórico antigo que ainda não tem texto completo salvo (grupos escaneados antes da busca por palavra-chave existir) é completado automaticamente, sem precisar marcar nada. Quando o Telegram pede uma pausa (flood control), o texto abaixo mostra a contagem regressiva - não é travamento; o scan continua sozinho quando a espera passa.'
            );
        corpo.appendChild(aviso);

        const status = document.createElement("div");
        status.style.cssText = "color:#a3aab8;margin-bottom:10px;white-space:pre-line;";
        status.textContent = scanEmAndamento ? "Scan já está rodando..." : "";
        corpo.appendChild(status);

        const botaoIniciar = botaoAcao(corpo, scanEmAndamento ? "Scan em andamento..." : "Iniciar scan");
        botaoIniciar.disabled = scanEmAndamento;

        const botaoParar = botaoAcao(corpo, "Parar");
        botaoParar.style.background = "#3a2f2f";
        botaoParar.style.display = scanEmAndamento ? "block" : "none";
        botaoParar.addEventListener("click", () => {
            cancelarScanSolicitado = true;
            botaoParar.disabled = true;
            botaoParar.textContent = "Parando...";
        });

        // Checkbox NAO persiste entre aberturas desta tela de proposito -
        // e uma opcao "so desta vez", pra nao correr o risco de deixar
        // marcada e forcar um reescaneamento completo sem querer da
        // proxima vez. Ver resetarCheckpointsParaRescanCompleto().
        // Rodada 6: "Reescanear do zero" e "Grupos do scan" ficam no bloco
        // recolhivel "Opcoes e filtros" desta tela.
        const opcoesDoScan = blocoRecolhivel(corpo, "escanear", "Opções e filtros");
        const blocoForcarRescan = document.createElement("div");
        blocoForcarRescan.style.cssText = "display:flex;align-items:center;gap:8px;margin:10px 0;font-size:13px;";
        const checkboxForcarRescan = criarQuadradoMarcavel(false, () => {});
        const labelForcarRescan = document.createElement("span");
        labelForcarRescan.style.cssText = "color:#a3aab8;display:flex;align-items:center;gap:4px;";
        labelForcarRescan.innerHTML =
            "<span>Reescanear do zero (lento - só pra corrigir dados; deixe desmarcado no dia a dia)</span>" +
            criarIconeInfoHtml(
                'Normalmente o scan "continua de onde parou" - mais rápido, não repete nada. Marcando isso, o(s) chat(s) escolhido(s) são relidos da primeira mensagem em diante de novo, mesmo que o scan já tivesse chegado no fim. Útil pra consertar um chat com suspeita de dado incompleto, ou pra preencher retroativamente um recurso novo (ex.: "Minhas reações") em chat já escaneado antes dele existir. Com "Todos" selecionado, reescaneia TODOS os grupos/canais marcados em "Grupos do scan" do zero - pode levar horas em canal grande, e pede um segundo clique pra confirmar. Se parar no meio, o próximo scan normal continua o reescaneamento de onde parou (o ponto antigo já foi zerado). As marcações de "já visto" são mantidas. A caixa desmarca sozinha ao sair desta tela.'
            );
        blocoForcarRescan.appendChild(checkboxForcarRescan.elemento);
        blocoForcarRescan.appendChild(labelForcarRescan);
        opcoesDoScan.appendChild(blocoForcarRescan);
        const linhaGrupos = document.createElement("div");
        linhaGrupos.style.cssText = "display:flex;align-items:center;gap:8px;flex-wrap:wrap;";
        botaoPequeno(linhaGrupos, "Grupos do scan (incluir/excluir)", () => telaConfigurarGrupos());
        linhaGrupos.insertAdjacentHTML("beforeend", '<span style="color:#a3aab8;font-size:13px;">Quais grupos entram no scan "Todos" e nas listas.</span>');
        opcoesDoScan.appendChild(linhaGrupos);

        const tituloTabela = document.createElement("div");
        tituloTabela.style.cssText = "color:#a3aab8;margin:14px 0 6px;font-weight:600;";
        tituloTabela.textContent = "O que já está salvo:";
        corpo.appendChild(tituloTabela);

        const tabela = document.createElement("div");
        corpo.appendChild(tabela);

        // So uma passada por iterDialogs aqui, reaproveitada nos demais
        // renderizarTabelaChats() desta mesma abertura de tela (inclusive os
        // que disparam a cada checkpoint durante um scan em andamento) - ver
        // comentario em cima de renderizarTabelaChats().
        const ultimasMensagens = await buscarUltimaMensagemPorChat().catch(() => new Map());
        await renderizarTabelaChats(tabela, db, ultimasMensagens);

        // Registra ESTA abertura como quem recebe status/atualizacao de
        // tabela agora - mesmo se um scan iniciado numa abertura ANTERIOR
        // desta tela ainda estiver rodando (scanEmAndamento true). Sem
        // isso, voltar pra "Escanear" enquanto um scan comecado antes
        // ainda roda mostrava "Scan ja esta rodando..." congelado pra
        // sempre, sem nenhuma atualizacao de progresso nem a mensagem final
        // quando terminasse.
        registrarVisualizacaoScanAtiva({
            atualizarStatus: (texto) => {
                status.textContent = texto;
            },
            aoAtualizarChat: () => renderizarTabelaChats(tabela, db, ultimasMensagens),
            // Reseta OS BOTOES desta abertura (a mais recente, que e a
            // visivel na tela quando o scan termina) e reconfere a tabela do
            // zero (a lista anterior pode ter ficado velha - o proprio scan
            // que acabou de rodar muda o que conta como "desatualizado").
            // Ver comentario em notificarFimScan()/visualizacaoScanAtiva.
            aoTerminarScan: async () => {
                botaoIniciar.disabled = false;
                botaoIniciar.textContent = "Iniciar scan de novo";
                botaoParar.style.display = "none";
                selectGrupo.disabled = false;
                const ultimasMensagensPosScan = await buscarUltimaMensagemPorChat(true).catch(() => new Map());
                await renderizarTabelaChats(tabela, db, ultimasMensagensPosScan);
            },
        });

        // Reescanear TODOS do zero pode levar horas (ver HISTORICO_TECNICO.md
        // v2026.10.13.1, canal com 468 mil mensagens) - pede um segundo
        // clique em ate 5s, mesmo padrao do "Sair", sem confirm() nativo.
        let confirmacaoRescanTodosPendente = false;
        let timeoutConfirmacaoRescan = null;

        botaoIniciar.addEventListener("click", async () => {
            if (checkboxForcarRescan.checked && !selectGrupo.value && !confirmacaoRescanTodosPendente) {
                confirmacaoRescanTodosPendente = true;
                const textoAnterior = botaoIniciar.textContent;
                const fundoAnterior = botaoIniciar.style.background;
                botaoIniciar.textContent = "Confirmar: reescanear TODOS do zero?";
                botaoIniciar.style.background = CORES.alerta;
                timeoutConfirmacaoRescan = setTimeout(() => {
                    confirmacaoRescanTodosPendente = false;
                    botaoIniciar.textContent = textoAnterior;
                    botaoIniciar.style.background = fundoAnterior;
                }, 5000);
                return;
            }
            confirmacaoRescanTodosPendente = false;
            clearTimeout(timeoutConfirmacaoRescan);
            botaoIniciar.style.background = "#4da3ff";
            botaoIniciar.disabled = true;
            botaoIniciar.textContent = "Escaneando...";
            botaoParar.style.display = "block";
            selectGrupo.disabled = true;
            const apenasChatId = selectGrupo.value || null;
            try {
                if (checkboxForcarRescan.checked) {
                    status.textContent = "Preparando reescaneamento completo...";
                    await resetarCheckpointsParaRescanCompleto(
                        db,
                        apenasChatId,
                        apenasChatId ? null : carregarGruposExcluidos()
                    );
                }
                const { gruposComErro } = await escanearTudo(apenasChatId);
                notificarStatusScan(
                    (cancelarScanSolicitado
                        ? "Scan interrompido - o que já foi visto fica salvo, pode retomar depois."
                        : apenasChatId
                        ? "Scan completo nesse grupo."
                        : "Scan completo em todos os grupos/canais.") +
                        (gruposComErro.length
                            ? "\nPulados por erro do Telegram (" + gruposComErro.length + "): " + gruposComErro.join("; ")
                            : "")
                );
            } catch (erro) {
                notificarStatusScan("Erro durante o scan: " + (erro && erro.message ? erro.message : erro));
            } finally {
                // Dirigido pra abertura ATUALMENTE registrada (ver
                // notificarFimScan()), nao necessariamente esta mesma
                // abertura - cobre o caso de ter navegado pra outra tela e
                // voltado enquanto este scan ainda rodava.
                await notificarFimScan();
            }
        });
    }

    // So mensagens.GetHistory/iterMessages (o que o scan chama em loop,
    // muitas vezes seguidas, no mesmo chat) realisticamente batem num
    // FLOOD_WAIT longo o suficiente pra chegar aqui - os outros lugares que
    // usam ".seconds" nesse mesmo formato de erro (SLOWMODE_WAIT,
    // TAKEOUT_INIT_DELAY, etc.) sao de fluxos que o scan nunca aciona.
    //
    // A propria lib (teleproto) ja espera sozinha por um FLOOD_WAIT de ate
    // 60s (floodSleepThreshold padrao dela) antes de sequer devolver o erro
    // pra gente - isso aqui so entra em acao quando a espera pedida pelo
    // Telegram e MAIOR que isso e a lib desiste. Sem isso, um FLOOD_WAIT
    // longo simplesmente quebrava o scan inteiro meio do caminho: parava,
    // mostrava "Erro durante o scan: Please wait Xs..." e ficava por conta
    // do usuario perceber e clicar "Iniciar scan" de novo manualmente (o
    // checkpoint ja garantia que retomava do ponto certo, so que exigia
    // esse passo manual).
    //
    // Deteccao por duck-typing (erro.seconds, numero) em vez de instanceof
    // Api.errors.FloodWaitError: essa classe (teleproto/errors) nao e
    // exposta pelo bridge (window.TeleprotoBridge so tem TelegramClient/
    // StringSession/PromisedWebSockets/Api - ver entry.js) - passar a expor
    // isso exigiria mexer no bundle, risco desproporcional pra esse ganho.
    //
    // Devolve true sempre que ERA um flood wait (espera completa ou nao -
    // quem chama confere cancelarScanSolicitado separado pra saber qual dos
    // dois aconteceu); false quando nao era flood wait nenhum, pra quem
    // chamou relancar o erro exatamente como sempre relancou.
    async function aguardarFloodWaitLongoSeForOCaso(erro) {
        if (!erro || typeof erro.seconds !== "number" || erro.seconds <= 0) return false;
        const segundosTotais = erro.seconds;
        let restante = segundosTotais;
        while (restante > 0 && !cancelarScanSolicitado) {
            notificarStatusScan(
                `O Telegram pediu uma pausa (flood wait) de ${segundosTotais}s - aguardando ${restante}s antes de continuar...`
            );
            const passo = Math.min(restante, 5);
            await new Promise((resolve) => setTimeout(resolve, passo * 1000));
            restante -= passo;
        }
        return true;
    }

    // So' pra dar uma nocao de "quanto falta" pro usuario durante a fase 2
    // (ver escanearTudo) - a fase 1 (backfill) ja tem um alvo exato
    // (backfillAlvo), nao precisa disso. iterMessages() expoe ".total" (a
    // contagem geral de mensagens do chat, que o proprio GetHistory devolve
    // de graca, sem chamada de API extra) assim que a primeira mensagem sai
    // do iterator. E' so' uma estimativa: ids de mensagem tem buracos
    // (mensagem deletada, por exemplo), entao o percentual pode nao bater
    // 100% com a realidade, mas da' uma ideia proxima o bastante.
    function formatarProgressoAproximado(mensagemAtualId, total) {
        if (typeof total !== "number" || total <= 0) return "";
        const percentual = Math.min(100, Math.round((mensagemAtualId / total) * 100));
        return ` (~${percentual}% de ~${total} mensagens no total deste chat)`;
    }

    // apenasChatId: null/"" escaneia todos os grupos/canais (como antes); um
    // chatId especifico faz so aquele grupo, sem depender da ordem que
    // iterDialogs() devolve.
    // Status e atualizacao de tabela nao vem mais por parametro - vao
    // direto por notificarStatusScan()/notificarAtualizacaoChatScan() (ver
    // comentario em visualizacaoScanAtiva, perto do topo do arquivo), que
    // sempre alcancam QUALQUER telaScanner() aberta no momento, mesmo se
    // for diferente da que chamou escanearTudo().
    //
    // Cada chat passa por duas fases, sem nenhum toggle manual:
    //
    // Fase 1 (backfill automatico): completa o texto das mensagens antigas,
    // de quando o chat foi escaneado antes da busca por palavra-chave
    // existir (so a mensagem com reacao era salva, o resto era descartado).
    // "backfillAlvo" congela, na primeira vez que o chat ganha essa
    // funcionalidade, o checkpoint antigo (o limite abaixo do qual o
    // historico pode estar incompleto); "textoCompletoAte" e o ponteiro
    // retomavel de ate onde esse backfill ja avancou. So roda enquanto
    // textoCompletoAte < backfillAlvo - uma vez que alcanca o alvo, nunca
    // mais roda de novo nesse chat.
    //
    // Fase 2 (scan incremental, igual sempre foi): continua de
    // lastScannedMessageId pra frente, pegando so mensagem nova. So comeca
    // se a fase 1 nao foi interrompida (senao o chat fica pra terminar o
    // backfill na proxima vez antes de seguir pra mensagem nova).
    //
    // Cada fase roda dentro de um laco de retry (while (true) { try {...}
    // catch {...} }): se o for-await terminar sem erro, dá break e segue a
    // vida; se der erro de flood wait longo (ver
    // aguardarFloodWaitLongoSeForOCaso), espera e tenta nessa mesma fase de
    // novo, sem perder o que ja foi salvo (textoCompletoAte/
    // lastScannedMessageId ja avancaram em memoria a cada mensagem, entao a
    // nova chamada de iterMessages com esses valores atualizados retoma do
    // lugar certo, nunca reprocessa nada); qualquer outro erro continua
    // propagando exatamente como sempre propagou.
    // A cada quantas mensagens o scan grava checkpoint (e o lote de
    // mensagens). Era 500; cada gravacao copia o indice inteiro, entao
    // espacar reduz esse custo 4x. Se o navegador fechar no meio, perde no
    // maximo isso de progresso (o proximo scan relê essas mensagens).
    const INTERVALO_CHECKPOINT_SCAN = 2000;

    async function escanearTudo(apenasChatId) {
        if (scanEmAndamento) return { gruposComErro: [] };
        scanEmAndamento = true;
        cancelarScanSolicitado = false;
        // So vale a exclusao quando "Todos" esta rodando - escolher um
        // grupo especifico (apenasChatId) sempre escaneia ele, mesmo que
        // esteja desmarcado em "Grupos do scan".
        const excluidos = apenasChatId ? null : carregarGruposExcluidos();
        const gruposComErro = [];
        let db = null;
        let limiteDeFloodOriginal = null;
        try {
            // Dentro do try: se abrir a pasta falhar, o finally ainda solta
            // scanEmAndamento (antes ficava preso em "Scan em andamento" ate
            // recarregar a pagina).
            db = await abrirBanco();
            // Materializa a lista inteira ANTES de comecar a escanear
            // qualquer chat (em vez de so consumir iterTodosOsDialogs() aos
            // poucos, no meio do laco) - e o que permite mostrar "grupo X de
            // Y" durante o scan (pedido do usuario). Mesmo custo de API de
            // sempre (so pagina o GetDialogs inteiro de uma vez em vez de
            // intercalado com o escaneamento de cada chat), nao faz nenhuma
            // chamada extra por grupo.
            const dialogsParaEscanear = [];
            for (const dialog of await listarDialogs(true)) {
                if (!(dialog.isGroup || dialog.isChannel)) continue;
                const chatId = String(dialog.id);
                if (apenasChatId && chatId !== apenasChatId) continue;
                if (excluidos && excluidos.has(chatId)) continue;
                dialogsParaEscanear.push(dialog);
            }
            const totalDeGrupos = dialogsParaEscanear.length;

            // Durante o scan, TODA pausa pedida pelo Telegram (flood wait)
            // volta pra gente em vez de a biblioteca dormir em silencio por
            // ate 60s (floodSleepThreshold padrao) - o laco de retry abaixo
            // ja espera o mesmo tempo, mas mostrando contagem regressiva no
            // status. Era a principal causa do "parece travado" sem nada na
            // tela. Volta ao valor original no finally. Efeito colateral
            // aceito: outra tela usada DURANTE o scan recebe erro de flood
            // wait em vez de esperar sozinha.
            if (cliente && "floodSleepThreshold" in cliente) {
                limiteDeFloodOriginal = cliente.floodSleepThreshold;
                cliente.floodSleepThreshold = 0;
            }

            for (let indiceGrupo = 0; indiceGrupo < totalDeGrupos; indiceGrupo++) {
                if (cancelarScanSolicitado) break;
                const dialog = dialogsParaEscanear[indiceGrupo];
                // So faz sentido com "Todos" (mais de um grupo na lista) -
                // escaneando um grupo especifico (apenasChatId, lista
                // sempre com 1 item so) "grupo 1 de 1" so seria ruido.
                const prefixoGrupo = totalDeGrupos > 1 ? `(grupo ${indiceGrupo + 1} de ${totalDeGrupos}) ` : "";
                const tituloParaErro = dialog.title || dialog.name || String(dialog.id);

                // Erro do Telegram que so afeta ESTE chat (ex.: CHANNEL_PRIVATE
                // depois de sair/ser removido do grupo) nao derruba mais o scan
                // inteiro: antes, um unico grupo assim parava o "Todos" sempre no
                // mesmo ponto, e os grupos depois dele nunca eram escaneados. O
                // checkpoint desse chat fica como estava (nao avanca), entao nada
                // se perde. Erro de rede/disco continua parando o scan (ver
                // erroSoDesteChat).
                try {

                    const chatId = String(dialog.id);
                    const chatTitle = dialog.title || dialog.name || chatId;
                    const chatUsername = (dialog.entity && dialog.entity.username) || null;

                    const chatSalvo = await buscarChat(db, chatId);

                    let backfillAlvo = 0;
                    let textoCompletoAte = 0;
                    if (chatSalvo) {
                        if (typeof chatSalvo.backfillAlvo === "number") {
                            backfillAlvo = chatSalvo.backfillAlvo;
                            textoCompletoAte = chatSalvo.textoCompletoAte || 0;
                        } else {
                            // chat ja existia de antes dessa funcionalidade -
                            // assume o pior caso (nenhum texto completo do
                            // historico antigo foi salvo ainda)
                            backfillAlvo = chatSalvo.lastScannedMessageId || 0;
                            textoCompletoAte = 0;
                        }
                    }
                    let lastScannedMessageId = (chatSalvo && chatSalvo.lastScannedMessageId) || 0;
                    let cancelado = false;
                    const inicio = Date.now();

                    console.log("[TLGMaster] scan:", {
                        chatTitle,
                        chatId,
                        backfillAlvo,
                        textoCompletoAte,
                        lastScannedMessageId,
                    });

                    // Grava as mensagens pendentes ANTES do checkpoint - nunca o
                    // contrario (ver "Gravacao em lote" perto de abrirBanco).
                    //
                    // No meio do chat o checkpoint roda SEM o scan esperar
                    // (salvarCheckpointEmParalelo): a gravacao em disco (que
                    // copia o indice inteiro, ver medicao no historico) corre
                    // enquanto o scan ja busca as proximas mensagens na rede.
                    // A ordem continua garantida: o lote de mensagens e
                    // separado na hora da chamada (descarregarEscritasPendentes
                    // troca o Map antes do primeiro await), cada checkpoint so
                    // grava chats.json depois do proprio lote E do checkpoint
                    // anterior, e os valores do checkpoint sao copiados na hora.
                    // Erro numa gravacao em paralelo e relancado no proximo
                    // checkpoint ou no fim do chat.
                    let checkpointsEmCurso = Promise.resolve();
                    let erroDeCheckpoint = null;
                    const salvarCheckpointEmParalelo = (concluido) => {
                        if (erroDeCheckpoint) throw erroDeCheckpoint;
                        const registro = {
                            chatId,
                            chatTitle,
                            chatUsername,
                            lastScannedMessageId,
                            lastScannedAt: new Date().toISOString(),
                            concluido,
                            backfillAlvo,
                            textoCompletoAte,
                        };
                        const gravacaoDoLote = descarregarEscritasPendentes(db);
                        checkpointsEmCurso = Promise.all([checkpointsEmCurso, gravacaoDoLote])
                            .then(() => salvarChat(db, registro))
                            .then(() => notificarAtualizacaoChatScan())
                            .catch((erro) => {
                                erroDeCheckpoint = erroDeCheckpoint || erro;
                            });
                    };
                    const salvarCheckpoint = async (concluido) => {
                        salvarCheckpointEmParalelo(concluido);
                        await checkpointsEmCurso;
                        if (erroDeCheckpoint) throw erroDeCheckpoint;
                    };

                    // ---- Fase 1: backfill automatico do historico antigo ----
                    if (textoCompletoAte < backfillAlvo) {
                        let totalVistas = 0;
                        // Alvo fixo e conhecido (backfillAlvo) - diferente da
                        // fase 2, da pra calcular o percentual exato aqui, sem
                        // depender de estimativa nenhuma.
                        const inicioBackfillAte = textoCompletoAte;
                        const extensaoBackfill = Math.max(1, backfillAlvo - inicioBackfillAte);
                        notificarStatusScan(
                            `${prefixoGrupo}${chatTitle}: completando histórico antigo (mensagem ${textoCompletoAte} até ${backfillAlvo})...`
                        );
                        while (true) {
                            try {
                                for await (const mensagem of cliente.iterMessages(dialog.entity, {
                                    minId: textoCompletoAte,
                                    maxId: backfillAlvo + 1,
                                    reverse: true,
                                })) {
                                    if (cancelarScanSolicitado) {
                                        cancelado = true;
                                        break;
                                    }
                                    totalVistas++;
                                    textoCompletoAte = mensagem.id;

                                    await salvarMensagem(db, montarRegistroDoScan(db, chatId, chatTitle, mensagem), {
                                        adiarGravacao: true,
                                    });

                                    // Texto da tela (so' custa um textContent)
                                    // atualiza bem mais seguido que o checkpoint
                                    // salvo no disco (esse sim grava arquivo) -
                                    // antes os dois estavam juntos
                                    // a cada 500 mensagens, o que podia deixar a
                                    // tela parecendo travada por muito tempo
                                    // entre uma atualizacao e outra.
                                    if (totalVistas % 100 === 0) {
                                        const segundos = Math.round((Date.now() - inicio) / 1000);
                                        const percentual = Math.min(
                                            100,
                                            Math.round(((textoCompletoAte - inicioBackfillAte) / extensaoBackfill) * 100)
                                        );
                                        notificarStatusScan(
                                            `${prefixoGrupo}${chatTitle}: completando histórico antigo, mensagem ${textoCompletoAte} de ${backfillAlvo} (~${percentual}%) (${segundos}s)...`
                                        );
                                    }
                                    if (totalVistas % INTERVALO_CHECKPOINT_SCAN === 0) {
                                        salvarCheckpointEmParalelo(false);
                                    }
                                }
                                break; // for-await terminou sem erro (cancelado ja foi tratado acima)
                            } catch (erro) {
                                if (!(await aguardarFloodWaitLongoSeForOCaso(erro))) throw erro;
                                if (cancelarScanSolicitado) {
                                    cancelado = true;
                                    break; // usuario cancelou enquanto esperava o flood wait passar
                                }
                                // espera terminou sem cancelar - volta pro topo
                                // do while e refaz iterMessages a partir de
                                // textoCompletoAte atualizado, sem reprocessar
                                // nada que ja foi salvo
                            }
                        }
                        await salvarCheckpoint(false);
                    }

                    if (cancelado) continue; // backfill ficou parcial - termina na proxima vez antes de seguir pra mensagem nova

                    // ---- Fase 2: scan incremental normal (so mensagem nova) ----
                    notificarStatusScan(`${prefixoGrupo}Escaneando: ${chatTitle} (a partir da mensagem ${lastScannedMessageId})...`);
                    let totalVistas = 0;
                    let comReacao = 0;
                    let terminouSemCancelar = true;

                    while (true) {
                        try {
                            const iteradorScan = cliente.iterMessages(dialog.entity, {
                                minId: lastScannedMessageId,
                                reverse: true,
                            });
                            for await (const mensagem of iteradorScan) {
                                if (cancelarScanSolicitado) {
                                    terminouSemCancelar = false;
                                    break;
                                }
                                totalVistas++;
                                lastScannedMessageId = Math.max(lastScannedMessageId, mensagem.id);

                                // Salva toda mensagem, nao so as com reacao - o
                                // texto completo de tudo e o que permite a busca
                                // por palavra-chave (tela "Buscar mensagens").
                                // reactionTotal fica 0 quando nao tem reacao, e
                                // o ranking de "top reacoes" continua filtrando
                                // por ele normalmente.
                                const registro = montarRegistroDoScan(db, chatId, chatTitle, mensagem);
                                await salvarMensagem(db, registro, { adiarGravacao: true });
                                if (registro.reactionTotal > 0) comReacao++;

                                // Ver comentario equivalente na fase 1: texto da
                                // tela atualiza mais seguido (so' custa
                                // textContent) que o checkpoint no disco (esse
                                // sim grava arquivo).
                                if (totalVistas % 100 === 0) {
                                    const segundos = Math.round((Date.now() - inicio) / 1000);
                                    notificarStatusScan(
                                        `${prefixoGrupo}${chatTitle}: mensagem ${lastScannedMessageId}${formatarProgressoAproximado(
                                            lastScannedMessageId,
                                            iteradorScan.total
                                        )}, ${totalVistas} verificadas (${segundos}s), ${comReacao} com reação...`
                                    );
                                }
                                if (totalVistas % INTERVALO_CHECKPOINT_SCAN === 0) {
                                    salvarCheckpointEmParalelo(false);
                                }
                            }
                            break; // for-await terminou sem erro (cancelado ja foi tratado acima)
                        } catch (erro) {
                            if (!(await aguardarFloodWaitLongoSeForOCaso(erro))) throw erro;
                            if (cancelarScanSolicitado) {
                                terminouSemCancelar = false;
                                break; // usuario cancelou enquanto esperava o flood wait passar
                            }
                            // espera terminou sem cancelar - volta pro topo do
                            // while e refaz iterMessages a partir de
                            // lastScannedMessageId atualizado, sem reprocessar
                            // nada que ja foi salvo
                        }
                    }

                    await salvarCheckpoint(terminouSemCancelar);
                } catch (erro) {
                    if (!erroSoDesteChat(erro)) throw erro;
                    console.warn("[TLGMaster] scan: pulando chat por erro do Telegram", tituloParaErro, erro);
                    gruposComErro.push(tituloParaErro + " (" + erro.errorMessage + ")");
                    notificarStatusScan(`${prefixoGrupo}${tituloParaErro}: pulado (${erro.errorMessage}), seguindo pro próximo...`);
                }
            }
            return { gruposComErro };
        } finally {
            // Garante que nada fica so em memoria se o scan parar por erro.
            // Gravar mensagem sem avancar o checkpoint e inofensivo (o
            // proximo scan regrava as mesmas, "ultima linha vence").
            if (db) await descarregarEscritasPendentes(db).catch((erro) => console.warn("[TLGMaster] erro ao gravar pendentes", erro));
            if (limiteDeFloodOriginal !== null && cliente) cliente.floodSleepThreshold = limiteDeFloodOriginal;
            scanEmAndamento = false;
        }
    }

    // Erro RPC do Telegram com codigo 400/403/406 (pedido invalido pra esse
    // chat, sem permissao, etc.) - afeta so o chat atual. 401 (sessao),
    // 420 (flood, tratado a parte), 5xx (servidor) e erros sem
    // errorMessage (rede caiu, disco) nao entram aqui.
    function erroSoDesteChat(erro) {
        return !!erro && typeof erro.errorMessage === "string" && [400, 403, 406].includes(erro.code);
    }

    // ---- Pecas compartilhadas das listas de mensagem (rodada 4) ----
    //
    // Top reacoes, Minhas reacoes, Buscar mensagens, Monitorados e
    // Favoritos usam as mesmas pecas: filtros ligados as preferencias
    // (ficam como o usuario deixou, ver preferencias.js), item de mensagem
    // (visto, favorito, autor, reacoes por emoji, "Monitorar autor") e a
    // lista com "Mostrar mais". Antes eram tres copias quase iguais.

    const ESTILO_CAMPO =
        "background:#0c0e12;color:#e6e8ec;border:1px solid #2a2f3a;border-radius:6px;padding:6px;box-sizing:border-box;";
    const ESTILO_BOTAO_PEQUENO =
        "background:#2a2f3a;border:none;border-radius:6px;color:#e6e8ec;cursor:pointer;font-size:13px;padding:4px 8px;";

    function botaoPequeno(container, texto, aoClicar, estiloExtra) {
        const botao = document.createElement("button");
        botao.textContent = texto;
        botao.style.cssText = ESTILO_BOTAO_PEQUENO + (estiloExtra || "");
        if (aoClicar) botao.addEventListener("click", aoClicar);
        container.appendChild(botao);
        return botao;
    }

    function rotuloDoEmoji(emoji) {
        if (emoji === "custom") return "(emoji personalizado)";
        if (emoji === "estrela") return "(estrela paga)";
        return emoji;
    }

    function textoDasReacoes(m) {
        return (m.emojis || [])
            .slice(0, 8)
            .map(([emoji, quantos]) => rotuloDoEmoji(emoji) + " " + quantos)
            .join("  ");
    }

    // Nome de quem mandou, pelo remetentes.json (sem chamada ao Telegram).
    function nomeDoAutor(db, de) {
        if (!de) return "";
        const dados = db && db.remetentes && db.remetentes.get(de);
        if (dados) return dados.n + (dados.u ? " (@" + dados.u + ")" : "");
        return String(de).startsWith("-") ? "canal/grupo " + de : "pessoa " + de;
    }

    // Emojis que aparecem no indice, do mais usado pro menos (filtro "so
    // com esta reacao"). Uma passada no indice em memoria por abertura de tela.
    function emojisMaisUsados(db, limite) {
        const contagem = new Map();
        for (const valor of db.indice.values()) {
            for (const par of valor.emojis || []) contagem.set(par[0], (contagem.get(par[0]) || 0) + par[1]);
        }
        return [...contagem.entries()].sort((a, b) => b[1] - a[1]).slice(0, limite || 40).map((par) => par[0]);
    }

    const TIPOS_DE_MIDIA_FILTRO = [
        { valor: "", rotulo: "Qualquer tipo" },
        { valor: "foto", rotulo: "Com foto" },
        { valor: "video", rotulo: "Com vídeo" },
        { valor: "audio", rotulo: "Com áudio" },
        { valor: "arquivo", rotulo: "Com arquivo" },
        { valor: "sem", rotulo: "Só texto" },
    ];

    // Grupo, (ordenar), (minimo), periodo, reacao, tipo de midia - todos
    // ligados as preferencias "<prefixo>_...". Devolve os campos e
    // filtros() com o valor atual de todos.
    function montarFiltrosDeLista(corpo, db, chats, prefixo, { ordenar, minimo, rotuloMinimo }, aoMudar) {
        const linha1 = document.createElement("div");
        linha1.style.cssText = "display:flex;gap:8px;margin-bottom:8px;";
        const selectGrupo = document.createElement("select");
        selectGrupo.style.cssText = ESTILO_CAMPO + "flex:2;min-width:0;";
        selectGrupo.innerHTML = '<option value="">Todos os grupos</option>';
        for (const c of chats) {
            const opcao = document.createElement("option");
            opcao.value = c.chatId;
            opcao.textContent = c.chatTitle || c.chatId;
            selectGrupo.appendChild(opcao);
        }
        linha1.appendChild(selectGrupo);
        ligarCampoAPreferencia(selectGrupo, prefixo + "_grupo");
        let selectOrdenar = null;
        if (ordenar) {
            selectOrdenar = document.createElement("select");
            selectOrdenar.style.cssText = ESTILO_CAMPO + "flex:1;min-width:0;";
            selectOrdenar.innerHTML = '<option value="reações">Mais reações</option><option value="data">Mais recentes</option>';
            linha1.appendChild(selectOrdenar);
            ligarCampoAPreferencia(selectOrdenar, prefixo + "_ordenar");
        }
        let inputMinimo = null;
        if (minimo) {
            inputMinimo = document.createElement("input");
            inputMinimo.type = "number";
            inputMinimo.min = "0";
            inputMinimo.title = rotuloMinimo || "Mínimo de reações";
            inputMinimo.style.cssText = ESTILO_CAMPO + "width:64px;flex-shrink:0;";
            linha1.appendChild(inputMinimo);
            ligarCampoAPreferencia(inputMinimo, prefixo + "_minimo");
        }
        corpo.appendChild(linha1);

        const linha2 = document.createElement("div");
        linha2.style.cssText = "display:flex;gap:8px;margin-bottom:8px;";
        const campoData = (rotulo, nome) => {
            const bloco = document.createElement("div");
            bloco.style.cssText = "flex:1;";
            const label = document.createElement("label");
            label.style.cssText = "display:block;color:#a3aab8;font-size:13px;margin-bottom:2px;";
            label.textContent = rotulo;
            const input = document.createElement("input");
            input.type = "date";
            input.style.cssText = ESTILO_CAMPO + "width:100%;";
            bloco.appendChild(label);
            bloco.appendChild(input);
            linha2.appendChild(bloco);
            return ligarCampoAPreferencia(input, nome);
        };
        const inputDataDe = campoData("De (data)", prefixo + "_data_de");
        const inputDataAte = campoData("Até (data)", prefixo + "_data_ate");
        corpo.appendChild(linha2);

        const linha3 = document.createElement("div");
        linha3.style.cssText = "display:flex;gap:8px;margin-bottom:8px;";
        const selectEmoji = document.createElement("select");
        selectEmoji.style.cssText = ESTILO_CAMPO + "flex:1;min-width:0;";
        selectEmoji.title = "Só mensagens com esta reação (mensagens escaneadas a partir desta versão)";
        selectEmoji.innerHTML = '<option value="">Qualquer reação</option>';
        for (const emoji of emojisMaisUsados(db)) {
            const opcao = document.createElement("option");
            opcao.value = emoji;
            opcao.textContent = "Só com " + rotuloDoEmoji(emoji);
            selectEmoji.appendChild(opcao);
        }
        const emojiSalvo = lerPreferencia(prefixo + "_emoji");
        if (emojiSalvo && ![...selectEmoji.options].some((o) => o.value === emojiSalvo)) {
            const opcao = document.createElement("option");
            opcao.value = emojiSalvo;
            opcao.textContent = "Só com " + rotuloDoEmoji(emojiSalvo);
            selectEmoji.appendChild(opcao);
        }
        ligarCampoAPreferencia(selectEmoji, prefixo + "_emoji");
        const selectMidia = document.createElement("select");
        selectMidia.style.cssText = ESTILO_CAMPO + "flex:1;min-width:0;";
        for (const tipo of TIPOS_DE_MIDIA_FILTRO) {
            const opcao = document.createElement("option");
            opcao.value = tipo.valor;
            opcao.textContent = tipo.rotulo;
            selectMidia.appendChild(opcao);
        }
        ligarCampoAPreferencia(selectMidia, prefixo + "_midia");
        linha3.appendChild(selectEmoji);
        linha3.appendChild(selectMidia);
        linha3.insertAdjacentHTML(
            "beforeend",
            criarIconeInfoHtml(
                "Reação e tipo de mídia só existem nas mensagens escaneadas a partir da versão 2026.10.14.3 (ou atualizadas pelo botão Atualizar reações). Mensagem salva antes disso não passa nesses dois filtros até o grupo ser escaneado de novo."
            )
        );
        corpo.appendChild(linha3);

        for (const campo of [selectGrupo, selectOrdenar, inputMinimo, inputDataDe, inputDataAte, selectEmoji, selectMidia]) {
            if (campo) campo.addEventListener("change", aoMudar);
        }
        return {
            selectGrupo,
            filtros() {
                return {
                    chatId: selectGrupo.value || null,
                    ordenarPor: selectOrdenar ? selectOrdenar.value : null,
                    minimo: inputMinimo ? parseInt(inputMinimo.value, 10) || 0 : 0,
                    dataDe: inputDataDe.value || null,
                    dataAte: inputDataAte.value || null,
                    emoji: selectEmoji.value || null,
                    midia: selectMidia.value || null,
                };
            },
            nomes: [prefixo + "_grupo", prefixo + "_ordenar", prefixo + "_minimo", prefixo + "_data_de", prefixo + "_data_ate", prefixo + "_emoji", prefixo + "_midia"].filter((n) => PREFERENCIAS.has(n)),
        };
    }

    // Rodada 7 (descoberta): tela vazia que ensina. Sem scan ainda, diz de
    // onde vem o conteudo e oferece o botao - antes era so o texto "Roda o
    // scan primeiro", sem caminho.
    function avisoSemScan(corpo, quem) {
        const caixa = document.createElement("div");
        caixa.className = "trp-vazio-sem-scan";
        caixa.style.cssText = "border:1px dashed " + CORES.borda + ";border-radius:8px;padding:12px;margin:4px 0 12px;font-size:14px;";
        const texto = document.createElement("div");
        texto.style.cssText = "margin-bottom:8px;";
        texto.textContent = "Nenhum grupo escaneado ainda. " + quem + " usa o que o Escanear salva dos seus grupos e canais - rode o scan uma vez e volte aqui.";
        caixa.appendChild(texto);
        botaoPequeno(caixa, "Escanear agora", () => telaScanner(), "background:" + CORES.destaque + ";color:" + CORES.fundo + ";font-weight:600;");
        corpo.appendChild(caixa);
        return caixa;
    }

    function filtrosDaListaDe(nomesDosFiltros, nomeOcultarVistos, reabrir) {
        const nomes = () => nomesDosFiltros.concat([nomeOcultarVistos]);
        return {
            nomes,
            limpar() {
                for (const nome of nomes()) if (PREFERENCIAS.has(nome)) gravarPreferencia(nome, PREFERENCIAS.get(nome).padrao);
                reabrir();
            },
            mostrarVistas() {
                gravarPreferencia(nomeOcultarVistos, false);
                reabrir();
            },
        };
    }

    function filtrosAtivos(nomes) {
        return nomes.filter((nome) => PREFERENCIAS.has(nome) && lerPreferencia(nome) !== PREFERENCIAS.get(nome).padrao);
    }

    // "Limpar filtros": volta os filtros desta tela ao padrao e redesenha.
    function botaoLimparFiltros(container, nomes, reabrir) {
        return botaoPequeno(container, "Limpar filtros", () => {
            for (const nome of nomes) gravarPreferencia(nome, PREFERENCIAS.get(nome).padrao);
            reabrir();
        });
    }

    // Um item de mensagem. opcoes: titulo, texto, tamanhoTexto, novo (destaque
    // "novo" dos Monitorados), faltando (lista onde o item se registra se o
    // texto precisar ser lido do arquivo do chat), semMonitorar.
    function criarItemDeMensagem(db, m, opcoes) {
        const item = document.createElement("div");
        item.style.cssText =
            "padding:8px 0;border-bottom:1px solid #2a2f3a;display:flex;gap:8px;align-items:flex-start;" +
            (m.visto ? "opacity:0.55;" : "") +
            (opcoes.novo ? "border-left:3px solid #4da3ff;padding-left:8px;" : "");
        item.dataset.key = m.key;
        const quadrado = criarQuadradoMarcavel(m.visto, (novoValor) => {
            marcarVisto(db, m.key, novoValor).catch((erro) => console.warn("[TLGMaster] marcar visto:", erro));
            item.style.opacity = novoValor ? "0.55" : "1";
        });
        quadrado.elemento.title = "Marcar como visto";
        // "Visto" fica no indice: mensagem que nao esta salva (conversa fora
        // do scan, favorito de mensagem que sumiu) nao tem onde guardar - a
        // caixinha nem aparece (antes marcava e sumia na proxima tela).
        if (!db.indice.has(m.key)) quadrado.elemento.style.visibility = "hidden";
        item.appendChild(quadrado.elemento);

        const conteudo = document.createElement("div");
        conteudo.style.cssText = "flex:1;min-width:0;";
        const link = criarLinkExterno((opcoes.novo ? "[novo] " : "") + opcoes.titulo, urlDaMensagem(m), "color:#4da3ff;font-weight:600;display:block;");
        conteudo.appendChild(link);
        const meta = document.createElement("div");
        meta.style.cssText = "color:#a3aab8;font-size:13px;";
        const partes = [m.chatTitle || m.chatId];
        if (m.de && m.de !== m.chatId) partes.push("por " + nomeDoAutor(db, m.de));
        else if (m.de && m.de === m.chatId) partes.push(m.assinatura ? "por " + m.assinatura + " (assinatura)" : "pelo próprio grupo/canal (admin anônimo ou post do canal)");
        const reacoes = textoDasReacoes(m);
        if (reacoes) partes.push(reacoes);
        if (m.achadoNoServidor) partes.push("achado ao vivo no servidor, salvo agora");
        meta.textContent = partes.join(" - ");
        conteudo.appendChild(meta);
        const texto = document.createElement("div");
        const tamanho = opcoes.tamanhoTexto || 200;
        const textoConhecido = opcoes.texto != null ? opcoes.texto : m.texto || m.trecho || m.textPreview || "";
        if (textoConhecido) texto.textContent = truncar(textoConhecido, tamanho);
        else if (opcoes.faltando) {
            texto.textContent = "(carregando texto...)";
            texto.style.color = "#a3aab8";
            opcoes.faltando.push({ elemento: texto, key: m.key, chatId: m.chatId, tamanho });
        }
        conteudo.appendChild(texto);

        const acoes = document.createElement("div");
        acoes.style.cssText = "display:flex;gap:6px;margin-top:4px;flex-wrap:wrap;";
        const favorito = ehFavorito(db, m.key);
        if (opcoes.naTelaDeFavoritos) {
            // Tela Favoritos: lixeira (com confirmacao) tira dos favoritos.
            botaoLixeira(acoes, "Tirar dos favoritos", async () => {
                await alternarFavorito(db, m, textoConhecido);
                if (opcoes.aoTirarDosFavoritos) opcoes.aoTirarDosFavoritos();
                else item.remove();
            });
        } else {
            const desenharFavorito = (sim) => {
                botaoFavorito.innerHTML =
                    '<span style="display:inline-flex;align-items:center;gap:4px;">' + iconeSvg("favoritos", 14) + "<span>" + (sim ? "Favorito (tirar)" : "Favoritar") + "</span></span>";
                botaoFavorito.style.color = sim ? CORES.destaque : CORES.texto;
            };
            const botaoFavorito = botaoPequeno(acoes, "", async () => desenharFavorito(await alternarFavorito(db, m, textoConhecido)));
            desenharFavorito(favorito);
        }
        if (!opcoes.semMonitorar && m.de !== m.chatId) {
            const jaMonitorado = m.de && estaMonitorado(m.de);
            const botaoMonitorar = botaoPequeno(acoes, jaMonitorado ? "Autor já monitorado" : "Monitorar autor", async () => {
                botaoMonitorar.disabled = true;
                botaoMonitorar.textContent = "Conferindo autor...";
                try {
                    botaoMonitorar.textContent = await monitorarAutorDaMensagem(db, m);
                } catch (erro) {
                    botaoMonitorar.textContent = "Não deu: " + mensagemDoErro(erro);
                    botaoMonitorar.disabled = false;
                }
            });
            if (jaMonitorado) botaoMonitorar.disabled = true;
        }
        conteudo.appendChild(acoes);
        item.appendChild(conteudo);
        return item;
    }

    // Texto das mensagens que so tem o indice (sem trecho): le o arquivo do
    // chat (com o cache de sempre) so pros itens que estao na tela.
    async function preencherTrechosQueFaltam(db, faltando) {
        const porChat = new Map();
        for (const pedido of faltando) {
            if (!porChat.has(pedido.chatId)) porChat.set(pedido.chatId, []);
            porChat.get(pedido.chatId).push(pedido);
        }
        for (const [chatId, pedidos] of porChat) {
            let mapa = null;
            try {
                mapa = await obterMensagensCompletasDoChat(db, chatId);
            } catch (erro) {
                mapa = new Map();
            }
            for (const pedido of pedidos) {
                const registro = mapa.get(pedido.key);
                pedido.elemento.style.color = "";
                pedido.elemento.textContent = registro ? truncar(registro.texto || "", pedido.tamanho) : "(texto não está salvo)";
            }
        }
    }

    // Lista com "Carregando...", "Mostrar mais", so a busca mais recente
    // desenhando e sem esvaziar a lista no meio (ver HISTORICO, salto de
    // rolagem). buscar(limite) -> { mensagens, temMais, avisos: [{texto, cor}] }.
    // filtrosDaLista (rodada 7, opcional): { nomes(), limpar(), mostrarVistas() } -
    // lista vazia por causa de filtro diz isso e oferece o botao, em vez de
    // parecer que nao tem nada (os filtros ficam no bloco recolhido).
    function criarListaDeMensagens(corpo, db, { buscar, ocultarVistos, montarItem, passo, vazio, agruparPorGrupo, filtrosDaLista }) {
        const status = document.createElement("div");
        status.style.cssText = "color:#a3aab8;font-size:13px;min-height:14px;margin-bottom:4px;white-space:pre-line;";
        corpo.appendChild(status);
        const lista = document.createElement("div");
        corpo.appendChild(lista);
        let limite = passo();
        let numeroAtual = 0;
        let ultimaAssinatura = null;
        async function atualizar(reiniciar) {
            if (reiniciar) limite = passo();
            const meu = ++numeroAtual;
            if (!lista.childNodes.length) lista.innerHTML = '<div style="color:#a3aab8;">Carregando...</div>';
            status.textContent = "Carregando...";
            let resultado;
            try {
                resultado = await buscar(limite, (texto) => {
                    if (meu === numeroAtual) status.textContent = texto;
                });
            } catch (erro) {
                if (meu !== numeroAtual) return;
                status.textContent = "";
                lista.innerHTML = "";
                const aviso = document.createElement("div");
                aviso.style.color = "#ff6b6b";
                aviso.textContent = "Erro: " + mensagemDoErro(erro);
                lista.appendChild(aviso);
                return;
            }
            if (meu !== numeroAtual) return;
            status.textContent = "";
            const mensagens = resultado.mensagens;
            const visiveis = ocultarVistos() ? mensagens.filter((m) => !m.visto) : mensagens;
            // Rodada 7: resultado igual ao que ja esta na tela = nao redesenha.
            // Redesenhar no "change" de um campo (que dispara quando a pessoa
            // clica fora dele) trocava o botao embaixo do mouse e o clique
            // se perdia (achado no teste do "Limpar filtros" da lista vazia).
            const assinatura = JSON.stringify([
                mensagens.length,
                visiveis, // registros leves inteiros: reacao/visto atualizados tambem redesenham
                filtrosDaLista ? filtrosAtivos(filtrosDaLista.nomes()).length : 0,
                !!resultado.temMais,
                (resultado.avisos || []).map((a) => a.texto),
                agruparPorGrupo ? !!agruparPorGrupo() : false,
            ]);
            if (assinatura === ultimaAssinatura && lista.childNodes.length) return;
            ultimaAssinatura = assinatura;
            const fragmento = document.createDocumentFragment();
            for (const aviso of resultado.avisos || []) {
                const div = document.createElement("div");
                div.style.cssText = "font-size:13px;margin-bottom:6px;color:" + (aviso.cor || "#a3aab8") + ";";
                div.textContent = aviso.texto;
                fragmento.appendChild(div);
            }
            const faltando = [];
            if (!mensagens.length) {
                const div = document.createElement("div");
                div.className = "trp-lista-vazia";
                div.style.color = "#a3aab8";
                div.textContent = vazio;
                const ativos = filtrosDaLista ? filtrosAtivos(filtrosDaLista.nomes()) : [];
                if (ativos.length) {
                    div.textContent +=
                        " " + (ativos.length > 1 ? ativos.length + ' filtros ativos em "Opções e filtros" podem' : '1 filtro ativo em "Opções e filtros" pode') + " estar escondendo resultados.";
                    const linha = document.createElement("div");
                    linha.style.cssText = "margin-top:6px;";
                    botaoPequeno(linha, "Limpar filtros", filtrosDaLista.limpar);
                    div.appendChild(linha);
                }
                fragmento.appendChild(div);
            } else if (!visiveis.length) {
                const div = document.createElement("div");
                div.className = "trp-lista-vazia";
                div.style.color = "#a3aab8";
                div.textContent = "Todas as mensagens desse filtro já foram marcadas como vistas.";
                if (filtrosDaLista && filtrosDaLista.mostrarVistas) {
                    const linha = document.createElement("div");
                    linha.style.cssText = "margin-top:6px;";
                    botaoPequeno(linha, "Mostrar as já vistas", filtrosDaLista.mostrarVistas);
                    div.appendChild(linha);
                }
                fragmento.appendChild(div);
            } else if (agruparPorGrupo && agruparPorGrupo() && visiveis.some((m) => m.chatId !== visiveis[0].chatId)) {
                for (const grupo of agruparPorChat(visiveis)) {
                    const cabecalho = document.createElement("div");
                    cabecalho.style.cssText =
                        "display:flex;align-items:center;gap:6px;padding:6px 0;cursor:pointer;user-select:none;color:#a3aab8;font-weight:600;font-size:13px;border-top:1px solid #2a2f3a;margin-top:4px;";
                    cabecalho.textContent = "▾ " + grupo.chatTitle + " (" + grupo.itens.length + ")";
                    const itens = document.createElement("div");
                    cabecalho.addEventListener("click", () => {
                        const aberto = itens.style.display !== "none";
                        itens.style.display = aberto ? "none" : "block";
                        cabecalho.textContent = (aberto ? "▸ " : "▾ ") + grupo.chatTitle + " (" + grupo.itens.length + ")";
                    });
                    fragmento.appendChild(cabecalho);
                    fragmento.appendChild(itens);
                    for (const m of grupo.itens) itens.appendChild(montarItem(m, faltando));
                }
            } else {
                for (const m of visiveis) fragmento.appendChild(montarItem(m, faltando));
            }
            lista.innerHTML = "";
            lista.appendChild(fragmento);
            if (resultado.temMais) {
                const botaoMais = botaoAcao(lista, "Mostrar mais");
                botaoMais.addEventListener("click", () => {
                    limite += passo();
                    atualizar(false);
                });
            }
            if (faltando.length) preencherTrechosQueFaltam(db, faltando);
        }
        return { atualizar, status, lista };
    }

    // "Atualizar reacoes pelo servidor": pede ao Telegram as reacoes ATUAIS
    // das mensagens ja salvas (messages.getMessagesReactions, 100 por
    // chamada) dos ultimos N dias (preferencia) e grava no indice - total,
    // por emoji e as SUAS reacoes. Era o que faltava pra "Minhas reacoes"
    // pegar mensagem antiga em que voce reagiu depois do scan (o truque da
    // "letra a" na busca ao vivo fazia isso sem querer, so pra 50 mensagens).
    // Pausa pedida pelo Telegram aparece em contagem no status.
    let atualizacaoDeReacoesRodando = false;
    async function atualizarReacoesPeloServidor(db, chatIdEscolhido, dias, aoProgresso, ctxExterno) {
        if (atualizacaoDeReacoesRodando) throw new Error("já tem uma atualização de reações rodando");
        atualizacaoDeReacoesRodando = true;
        try {
            const cli = await obterClienteParaFerramentas();
            const desde = new Date(Date.now() - dias * 86400000).toISOString();
            const excluidos = carregarGruposExcluidos();
            const porChat = new Map();
            for (const valor of db.indice.values()) {
                if (chatIdEscolhido ? valor.chatId !== chatIdEscolhido : excluidos.has(valor.chatId)) continue;
                if ((valor.dateUtc || "") < desde) continue;
                if (!porChat.has(valor.chatId)) porChat.set(valor.chatId, []);
                porChat.get(valor.chatId).push(valor.messageId);
            }
            let atualizadas = 0;
            let mudaram = 0;
            const pulados = [];
            let indiceChat = 0;
            for (const [chatId, ids] of porChat) {
                indiceChat++;
                const titulo = (buscarChat(db, chatId) || {}).chatTitle || chatId;
                const ctx = ctxExterno || { sinal: null, aoPausa: (s) => s && aoProgresso(titulo + ": Telegram pediu pausa de " + s + "s...") };
                let entidade;
                try {
                    entidade = await chamarComPausaLocal(() => encontrarEntidadePorChatId(chatId), ctx);
                } catch (erro) {
                    entidade = null;
                }
                if (!entidade) {
                    pulados.push(titulo + " (a conta não está mais no grupo)");
                    continue;
                }
                ids.sort((a, b) => b - a);
                for (let i = 0; i < ids.length; i += 100) {
                    aoProgresso("Grupo " + indiceChat + " de " + porChat.size + " (" + titulo + "): " + Math.min(i + 100, ids.length) + " de " + ids.length + " mensagens");
                    const lote = ids.slice(i, i + 100);
                    let resposta;
                    try {
                        resposta = await chamarComPausaLocal(
                            () => cli.invoke(new Api.messages.GetMessagesReactions({ peer: entidade, id: lote }), undefined, { floodSleepThreshold: 0 }),
                            ctx
                        );
                    } catch (erro) {
                        if (erroSoDesteChat(erro)) {
                            pulados.push(titulo + " (" + erro.errorMessage + ")");
                            break;
                        }
                        throw erro;
                    }
                    const atualizacoes = (resposta && resposta.updates) || [];
                    const respondidas = new Set();
                    for (const u of atualizacoes) {
                        if (u.className !== "UpdateMessageReactions") continue;
                        respondidas.add(Number(u.msgId));
                        if (aplicarReacoesNoIndice(db, chatId + ":" + u.msgId, u.reactions)) mudaram++;
                        atualizadas++;
                    }
                    // Mensagem sem reacao nenhuma pode nao vir na resposta: zera.
                    for (const id of lote) {
                        if (respondidas.has(id)) continue;
                        if (aplicarReacoesNoIndice(db, chatId + ":" + id, null)) mudaram++;
                    }
                    await descarregarEscritasPendentes(db);
                }
            }
            return { atualizadas, mudaram, pulados, grupos: porChat.size };
        } finally {
            atualizacaoDeReacoesRodando = false;
        }
    }

    // Grava no indice as reacoes novas de uma mensagem ja salva (mantendo
    // visto e o resto). Devolve true se algo mudou.
    function aplicarReacoesNoIndice(db, key, reacoes) {
        const leve = db.indice.get(key);
        if (!leve) return false;
        const { reactions, total, minhasReacoes } = extrairReacoes({ reactions: reacoes });
        const emojis = reactions.length ? reactions.map((r) => [r.emoji, r.count]) : undefined;
        const igual =
            (leve.reactionTotal || 0) === total &&
            JSON.stringify(leve.minhasReacoes || []) === JSON.stringify(minhasReacoes) &&
            JSON.stringify(leve.emojis || null) === JSON.stringify(emojis || null);
        if (igual) return false;
        // Sem reacao: "emojis: null" (e nao apagar o campo) - assim o null do
        // indice vence o emoji antigo do arquivo do chat (comVistoDoIndice).
        const novo = { ...leve, reactionTotal: total, minhasReacoes, emojis: emojis || null };
        db.indice.set(key, novo);
        const cacheDoChat = db.textoCompletoPorChat.get(leve.chatId);
        const completo = cacheDoChat && cacheDoChat.get(key);
        if (completo) cacheDoChat.set(key, { ...completo, reactionTotal: total, minhasReacoes, emojis: novo.emojis });
        adiarAnexo(db, "indice.jsonl", JSON.stringify(novo) + "\n");
        return true;
    }

    function botaoAtualizarReacoes(container, db, obterChatId, aoTerminar, aoStatus) {
        const dias = lerPreferencia("atualizar_reacoes_dias");
        const botao = botaoPequeno(container, "Atualizar reações pelo servidor (últimos " + dias + " dias)", async () => {
            botao.disabled = true;
            try {
                const r = await atualizarReacoesPeloServidor(db, obterChatId(), dias, aoStatus);
                aoStatus(
                    r.mudaram + " mensagem(ns) com reação diferente atualizada(s), de " + r.atualizadas + " conferida(s) em " + r.grupos + " grupo(s)." +
                        (r.pulados.length ? "\nPulados: " + r.pulados.join("; ") : "")
                );
                aoTerminar();
            } catch (erro) {
                aoStatus("Não deu pra atualizar as reações: " + mensagemDoErro(erro));
            } finally {
                botao.disabled = false;
            }
        });
        botao.title =
            "Pergunta ao Telegram as reações de agora das mensagens já salvas (total, por emoji e as suas) - pega reação que você fez DEPOIS do scan. 1 chamada a cada 100 mensagens. Quantos dias: em Opções e filtros desta tela.";
        return botao;
    }

    // ---- Tela de resultados ----

    // "Mais reagidas" (rodada 6): Top reacoes e Minhas reacoes viraram abas
    // da mesma tela; filtros e opcoes no bloco recolhivel.
    const ABAS_MAIS_REAGIDAS = [
        { id: "top", rotulo: "Top reações", abrir: () => telaResultados() },
        { id: "minhas", rotulo: "Minhas reações", abrir: () => telaMinhasReacoes() },
    ];
    const OPCOES_EXTRAS_REAGIDAS = ["itens_por_pagina", "atualizar_reacoes_dias", "reacoes_na_hora"];

    // Bloco "Opcoes e filtros" comum as duas abas de Mais reagidas.
    function opcoesDeMaisReagidas(corpo, db, chats, prefixo, configFiltros, aoMudar, reabrir) {
        const conteudo = blocoRecolhivel(corpo, "reagidas", "Opções e filtros");
        const filtros = montarFiltrosDeLista(conteudo, db, chats, prefixo, configFiltros, () => {
            conteudo.mostrarFiltrosAtivos(filtros.nomes.concat([prefixo + "_ocultar_vistos"]));
            aoMudar();
        });
        linhaDeQuadrado(conteudo, prefixo + "_ocultar_vistos", "Ocultar as já marcadas como vistas", null, () => {
            conteudo.mostrarFiltrosAtivos(filtros.nomes.concat([prefixo + "_ocultar_vistos"]));
            aoMudar();
        });
        const barra = document.createElement("div");
        barra.style.cssText = "display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;";
        conteudo.appendChild(barra);
        botaoLimparFiltros(barra, filtros.nomes, reabrir);
        botaoSalvarBusca(barra, db, prefixo, "", filtros.nomes);
        controlesDasPreferencias(conteudo, OPCOES_EXTRAS_REAGIDAS);
        botaoPadraoDaTela(conteudo, filtros.nomes.concat([prefixo + "_ocultar_vistos"], OPCOES_EXTRAS_REAGIDAS), reabrir);
        conteudo.mostrarFiltrosAtivos(filtros.nomes.concat([prefixo + "_ocultar_vistos"]));
        return { filtros, barra };
    }

    async function telaResultados() {
        definirTituloTela("Mais reagidas");
        const corpo = corpoDoPainel();
        botaoVoltar(corpo);
        abasDaTela(corpo, "reagidas", ABAS_MAIS_REAGIDAS, "top");

        const db = await abrirBanco();
        // Grupo desmarcado em "Configurar grupos" nao aparece no seletor -
        // ver comentario em renderizarTabelaChats().
        const excluidos = carregarGruposExcluidos();
        const chats = listarChats(db).filter((c) => !excluidos.has(c.chatId));
        chats.sort((a, b) => (a.chatTitle || "").localeCompare(b.chatTitle || ""));
        if (!chats.length) {
            avisoSemScan(corpo, "Mais reagidas");
            return;
        }

        const { filtros, barra } = opcoesDeMaisReagidas(corpo, db, chats, "top", { ordenar: true, minimo: true }, () => lista.atualizar(true), () => telaResultados());

        const lista = criarListaDeMensagens(corpo, db, {
            passo: () => lerPreferencia("itens_por_pagina"),
            ocultarVistos: () => lerPreferencia("top_ocultar_vistos"),
            vazio: "Nenhuma mensagem encontrada com esse filtro.",
            filtrosDaLista: filtrosDaListaDe(filtros.nomes, "top_ocultar_vistos", () => telaResultados()),
            async buscar(limite) {
                const f = filtros.filtros();
                const mensagens = buscarTop(db, { ...f, limite, excluidos, ocultarVistos: lerPreferencia("top_ocultar_vistos") });
                return { mensagens, temMais: mensagens.length >= limite };
            },
            montarItem: (m, faltando) =>
                criarItemDeMensagem(db, m, { titulo: m.reactionTotal + " reações - " + m.dateUtc.slice(0, 10), tamanhoTexto: 160, faltando }),
        });
        botaoAtualizarReacoes(barra, db, () => filtros.selectGrupo.value || null, () => lista.atualizar(false), (t) => (lista.status.textContent = t));
        await lista.atualizar(true);
    }

    // ---- Tela "Minhas reacoes" - mensagem que a PROPRIA conta reagiu,
    // usado como marcador/lembrete (ver buscarMinhasReacoes). Sem "ordenar
    // por"/"minimo" (aqui so existe "reagi ou nao reagi"), mais recente
    // primeiro.
    async function telaMinhasReacoes() {
        definirTituloTela("Mais reagidas");
        const corpo = corpoDoPainel();
        botaoVoltar(corpo);
        abasDaTela(corpo, "reagidas", ABAS_MAIS_REAGIDAS, "minhas");

        const db = await abrirBanco();
        const excluidos = carregarGruposExcluidos();
        const chats = listarChats(db).filter((c) => !excluidos.has(c.chatId));
        chats.sort((a, b) => (a.chatTitle || "").localeCompare(b.chatTitle || ""));
        if (!chats.length) {
            avisoSemScan(corpo, "Mais reagidas");
            return;
        }

        // Etapa P2: o que entra sozinho e o "Atualizar reacoes pelo
        // servidor" no topo (antes: aviso + botao dentro de Opcoes e filtros).
        const faixa = faixaDasReacoesNaHora(corpo);

        const { filtros } = opcoesDeMaisReagidas(corpo, db, chats, "minhas", {}, () => lista.atualizar(true), () => telaMinhasReacoes());

        const lista = criarListaDeMensagens(corpo, db, {
            passo: () => lerPreferencia("itens_por_pagina"),
            ocultarVistos: () => lerPreferencia("minhas_ocultar_vistos"),
            vazio: "Nenhuma mensagem encontrada com esse filtro.",
            filtrosDaLista: filtrosDaListaDe(filtros.nomes, "minhas_ocultar_vistos", () => telaMinhasReacoes()),
            async buscar(limite) {
                const f = filtros.filtros();
                const mensagens = buscarMinhasReacoes(db, { ...f, limite, excluidos, ocultarVistos: lerPreferencia("minhas_ocultar_vistos") });
                return { mensagens, temMais: mensagens.length >= limite };
            },
            montarItem: (m, faltando) =>
                criarItemDeMensagem(db, m, {
                    titulo:
                        (m.minhasReacoes || []).map(rotuloDoEmoji).join(" ") +
                        " - " +
                        m.dateUtc.slice(0, 10) +
                        (m.reactionTotal > 1 ? " (" + m.reactionTotal + " reações no total)" : ""),
                    tamanhoTexto: 160,
                    faltando,
                }),
        });
        botaoAtualizarReacoes(faixa, db, () => filtros.selectGrupo.value || null, () => lista.atualizar(false), (t) => (lista.status.textContent = t)).classList.add("trp-atualizar-reacoes-topo");
        // Reacao gravada na hora com esta tela aberta: redesenha a tela.
        aoGravarReacaoNaHora = () => {
            if (faixa.isConnected) telaMinhasReacoes();
        };
        await lista.atualizar(true);
    }

    // ---- Tela de busca por palavra-chave ----

    // Busca ao vivo no servidor (messages.Search, o mesmo da busca nativa)
    // num grupo. Grava TODA mensagem achada: a nova entra no banco (conserta
    // buraco de scan) e a ja salva tem reacoes/autor atualizados (antes a ja
    // salva era ignorada e a reacao feita depois do scan nunca chegava em
    // "Minhas reacoes"). Ate "busca_servidor_limite" mensagens por busca
    // (antes 50 fixo). Devolve o Set das keys que eram novas.
    async function buscarAoVivoNoServidor(db, chatId, termo, aoProgresso) {
        const entidade = await encontrarEntidadePorChatId(chatId);
        if (!entidade) throw new Error("grupo não encontrado entre os dialogs dessa conta agora");
        const chatInfo = buscarChat(db, chatId);
        const chatTitle = (chatInfo && chatInfo.chatTitle) || chatId;
        const limite = lerPreferencia("busca_servidor_limite");
        const novas = new Set();
        let vistas = 0;
        for await (const mensagem of cliente.iterMessages(entidade, { search: termo, limit: limite })) {
            vistas++;
            const registro = montarRegistroDoScan(db, chatId, chatTitle, mensagem);
            if (!db.indice.has(registro.key)) novas.add(registro.key);
            await salvarMensagem(db, registro, { adiarGravacao: true });
            if (vistas % 50 === 0 && aoProgresso) aoProgresso("Servidor: " + vistas + " mensagens conferidas...");
        }
        await descarregarEscritasPendentes(db);
        return { novas, vistas };
    }

    // Busca ao vivo no servidor e POR GRUPO (messages.search pede o chat).
    // Antes, com a caixinha marcada e "Todos os grupos" escolhido, a parte
    // do servidor era pulada em silencio (rodada 5, teste real do usuario).
    // Agora: caixinha marcada bloqueia "Todos" no seletor e explica; se ja
    // estava em "Todos", a busca nao roda ate escolher um grupo.
    const EXPLICACAO_SERVIDOR_POR_GRUPO = "busca no servidor é por grupo; para buscar em todos, use Buscar > No Telegram > Nas suas conversas";
    function situacaoDaBuscaNoServidor(servidorMarcado, chatId) {
        if (!servidorMarcado) return { noServidor: false, bloquearTodos: false, impedeBusca: false, aviso: "" };
        if (!chatId) {
            return { noServidor: false, bloquearTodos: true, impedeBusca: true, aviso: "Escolha um grupo pra buscar no servidor (ou desmarque a caixinha). " + EXPLICACAO_SERVIDOR_POR_GRUPO[0].toUpperCase() + EXPLICACAO_SERVIDOR_POR_GRUPO.slice(1) + "." };
        }
        return { noServidor: true, bloquearTodos: true, impedeBusca: false, aviso: EXPLICACAO_SERVIDOR_POR_GRUPO[0].toUpperCase() + EXPLICACAO_SERVIDOR_POR_GRUPO.slice(1) + "." };
    }

    // "Buscar" (rodada 6): "No que escaneei" (antiga Buscar mensagens) e
    // "No Telegram" (antiga Busca avancada) sao abas da mesma tela.
    const ABAS_BUSCAR = [
        { id: "escaneei", rotulo: "No que escaneei", abrir: () => telaBusca() },
        { id: "telegram", rotulo: "No Telegram", abrir: () => telaBuscaAvancada() },
    ];

    function botaoHistoricoDeBuscas(container) {
        return botaoPequeno(container, "Histórico de buscas (gerenciar/limpar)", () => telaHistoricoBusca());
    }

    async function telaBusca(pedido) {
        definirTituloTela("Buscar");
        const corpo = corpoDoPainel();
        botaoVoltar(corpo);
        abasDaTela(corpo, "buscar", ABAS_BUSCAR, "escaneei");

        const db = await abrirBanco();
        const excluidos = carregarGruposExcluidos();
        const chats = listarChats(db).filter((c) => !excluidos.has(c.chatId));
        chats.sort((a, b) => (a.chatTitle || "").localeCompare(b.chatTitle || ""));

        if (!chats.length) avisoSemScan(corpo, 'A aba "No que escaneei"');
        const aviso = document.createElement("div");
        aviso.style.cssText = "display:flex;align-items:center;gap:4px;color:#a3aab8;margin-bottom:10px;";
        aviso.innerHTML =
            "<span>Busca dentro do que já foi escaneado (e, se marcado, ao vivo no servidor).</span>" +
            criarIconeInfoHtml(
                'Várias palavras = qualquer uma delas (OU). Campo em branco = todas as mensagens, com os filtros. Grupo escaneado antes da busca por palavra existir completa o texto antigo sozinho na próxima passada do scan.'
            );
        corpo.appendChild(aviso);

        const campoBusca = campoTexto(corpo, "Palavra ou trecho a buscar (em branco = todas as mensagens)", "text", (pedido && pedido.termo) || "");
        const historicoBusca = ligarHistoricoBusca(campoBusca, CHAVE_HISTORICO_BUSCA_LOCAL);

        // Filtros e opcoes no bloco recolhivel (rodada 6). O aviso da busca
        // no servidor fica FORA do bloco (visivel com ele fechado).
        const opcoesDaBusca = blocoRecolhivel(corpo, "buscar_escaneei", "Opções e filtros");
        const nomesDosFiltrosDaBusca = () => filtros.nomes.concat(["busca_servidor", "busca_so_link", "busca_ocultar_vistos"]);
        const filtros = montarFiltrosDeLista(opcoesDaBusca, db, chats, "busca", { ordenar: true, minimo: true }, () => {
            atualizarDisponibilidadeServidor();
            opcoesDaBusca.mostrarFiltrosAtivos(nomesDosFiltrosDaBusca());
            if (jaBuscou && !situacaoDaBuscaNoServidor(lerPreferencia("busca_servidor"), filtros.selectGrupo.value).impedeBusca) lista.atualizar(true);
        });

        linhaDeQuadrado(
            opcoesDaBusca,
            "busca_servidor",
            "Também buscar ao vivo no servidor do Telegram",
            'Pega mensagem que o scan ainda não tem e atualiza as reações das que já estão salvas. Só num grupo escolhido: com a caixinha marcada, "Todos os grupos" fica bloqueado. Quantas mensagens trazer: logo abaixo.',
            () => {
                atualizarDisponibilidadeServidor();
                opcoesDaBusca.mostrarFiltrosAtivos(nomesDosFiltrosDaBusca());
            }
        );
        linhaDeQuadrado(opcoesDaBusca, "busca_so_link", "Só mensagens com link", null, () => {
            opcoesDaBusca.mostrarFiltrosAtivos(nomesDosFiltrosDaBusca());
            if (jaBuscou) lista.atualizar(true);
        });
        linhaDeQuadrado(opcoesDaBusca, "busca_ocultar_vistos", "Ocultar as já marcadas como vistas", null, () => {
            opcoesDaBusca.mostrarFiltrosAtivos(nomesDosFiltrosDaBusca());
            if (jaBuscou) lista.atualizar(true);
        });
        const avisoServidor = document.createElement("div");
        avisoServidor.className = "trp-aviso-servidor";
        avisoServidor.style.cssText = "font-size:13px;margin:0 0 10px;";
        corpo.appendChild(avisoServidor);

        // Caixinha marcada: "Todos os grupos" bloqueado + linha explicando;
        // em "Todos", pede pra escolher um grupo (em vermelho).
        function atualizarDisponibilidadeServidor() {
            const situacao = situacaoDaBuscaNoServidor(lerPreferencia("busca_servidor"), filtros.selectGrupo.value);
            const opcaoTodos = filtros.selectGrupo.options[0];
            if (opcaoTodos) {
                opcaoTodos.disabled = situacao.bloquearTodos;
                opcaoTodos.textContent = situacao.bloquearTodos ? "Todos os grupos (bloqueado: busca no servidor)" : "Todos os grupos";
            }
            avisoServidor.textContent = situacao.aviso;
            avisoServidor.style.color = situacao.impedeBusca ? "#ff6b6b" : "#a3aab8";
            avisoServidor.style.display = situacao.aviso ? "" : "none";
            return situacao;
        }
        atualizarDisponibilidadeServidor();

        const barra = document.createElement("div");
        barra.style.cssText = "display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;";
        opcoesDaBusca.appendChild(barra);
        botaoLimparFiltros(barra, filtros.nomes.concat(["busca_so_link"]), () => telaBusca({ termo: campoBusca.value }));
        botaoSalvarBusca(barra, db, "busca", () => campoBusca.value.trim(), filtros.nomes.concat(["busca_so_link", "busca_servidor"]));
        botaoHistoricoDeBuscas(barra);
        controlesDasPreferencias(opcoesDaBusca, ["busca_servidor_limite", "itens_por_pagina"]);
        botaoPadraoDaTela(opcoesDaBusca, nomesDosFiltrosDaBusca().concat(["busca_servidor_limite", "itens_por_pagina"]), () => telaBusca({ termo: campoBusca.value }));
        opcoesDaBusca.mostrarFiltrosAtivos(nomesDosFiltrosDaBusca());

        const botaoBuscar = botaoAcao(corpo, "Buscar");
        let jaBuscou = false;

        const lista = criarListaDeMensagens(corpo, db, {
            passo: () => lerPreferencia("itens_por_pagina") * 2,
            ocultarVistos: () => lerPreferencia("busca_ocultar_vistos"),
            vazio: "Nada encontrado com esse termo.",
            filtrosDaLista: filtrosDaListaDe(filtros.nomes.concat(["busca_so_link"]), "busca_ocultar_vistos", () => telaBusca({ termo: campoBusca.value })),
            agruparPorGrupo: () => !filtros.selectGrupo.value,
            async buscar(limite, aoProgresso) {
                const termo = campoBusca.value.trim();
                const f = filtros.filtros();
                const avisos = [];
                let novas = new Set();
                if (situacaoDaBuscaNoServidor(lerPreferencia("busca_servidor"), f.chatId).noServidor && !permite("busca_servidor")) {
                    avisos.push({ texto: "Busca no servidor é do plano pago - resultado abaixo é só o local.", cor: "#ff6b6b" });
                } else if (situacaoDaBuscaNoServidor(lerPreferencia("busca_servidor"), f.chatId).noServidor) {
                    try {
                        aoProgresso("Buscando ao vivo no servidor...");
                        const r = await buscarAoVivoNoServidor(db, f.chatId, termo, aoProgresso);
                        novas = r.novas;
                        avisos.push({
                            texto: "Servidor: " + r.vistas + " mensagem(ns) conferida(s), " + novas.size + " nova(s) salva(s) agora; as já salvas tiveram as reações atualizadas.",
                            cor: "#5ec26a",
                        });
                    } catch (erro) {
                        avisos.push({ texto: "Busca ao vivo no servidor falhou (" + mensagemDoErro(erro) + ") - resultado abaixo é só o local.", cor: "#ff6b6b" });
                    }
                    aoProgresso("Buscando no que está salvo...");
                }
                const mensagens = await buscarTexto(db, {
                    termo,
                    ...f,
                    limite,
                    excluidos,
                    ocultarVistos: lerPreferencia("busca_ocultar_vistos"),
                    soLink: lerPreferencia("busca_so_link"),
                });
                for (const m of mensagens) if (novas.has(m.key)) m.achadoNoServidor = true;
                return { mensagens, temMais: mensagens.length >= limite, avisos };
            },
            montarItem: (m) =>
                criarItemDeMensagem(db, m, {
                    titulo: m.dateUtc.slice(0, 10) + (m.reactionTotal ? " - " + m.reactionTotal + " reações" : ""),
                    texto: m.texto || m.textPreview || "",
                    tamanhoTexto: 200,
                }),
        });
        lista.lista.innerHTML =
            '<div style="color:#a3aab8;">Digita algo pra buscar, ou deixa em branco e aperta "Buscar" pra trazer todas as mensagens (sujeito aos filtros).</div>';

        const executar = () => {
            // Nunca pula o servidor em silencio: sem grupo, nao busca e diz.
            if (atualizarDisponibilidadeServidor().impedeBusca) {
                opcoesDaBusca.parentElement.open = true; // o seletor de grupo esta no bloco
                lista.lista.innerHTML = "";
                textoAviso(lista.lista, "Escolha um grupo no seletor antes de buscar (a busca no servidor é por grupo), ou desmarque \"Também buscar ao vivo no servidor\".", "#ff6b6b");
                return;
            }
            jaBuscou = true;
            const termo = campoBusca.value.trim();
            if (termo) historicoBusca.registrar(termo);
            lista.atualizar(true);
        };
        botaoBuscar.addEventListener("click", executar);
        campoBusca.addEventListener("keydown", (ev) => {
            if (ev.key === "Enter") executar();
        });
        if (pedido && pedido.executar) executar();
    }

    // ---- Tela de busca avancada (refeita na rodada 4) ----
    //
    // Antes eram 3 campos soltos (nome, post por hashtag/texto, colar link)
    // e o texto livre dava erro de Premium sem explicar. Agora:
    //   1. Link do Telegram: "https://t.me/" fixo na tela, digita so o final
    //      (ou cola qualquer forma de link, @usuario, varios de uma vez). Diz
    //      o que e, se o convite vale e - em link de mensagem - compara com o
    //      que esta salvo (era a tela "Verificar mensagem").
    //   2. Palavra-chave: UMA busca que junta tudo - grupos/canais/pessoas
    //      pelo nome (contacts.search), posts publicos (channels.searchPosts:
    //      hashtag sempre; texto livre so quando o Telegram deixa de graca
    //      nesta conta, com o motivo na tela), links t.me achados nos posts
    //      (conferidos) e as suas proprias conversas (messages.searchGlobal -
    //      inclusive grupo fora do scan).
    // As opcoes (o que buscar, filtros, ordem) ficam guardadas (preferencias
    // "ba_...", Configuracoes > Busca avancada).

    // Roda "tarefa" pra cada item, no maximo "simultaneas" de cada vez.
    async function emParaleloLimitado(itens, simultaneas, tarefa) {
        let proximo = 0;
        const trabalhadores = [];
        for (let i = 0; i < Math.min(simultaneas, itens.length); i++) {
            trabalhadores.push(
                (async () => {
                    while (proximo < itens.length) await tarefa(itens[proximo++]);
                })()
            );
        }
        await Promise.all(trabalhadores);
    }

    // Numero de membros que o Telegram nao mandou (objeto "min"): pede o
    // canal completo, uma vez por canal nesta tela.
    function criarBuscadorDeMembros() {
        const cache = new Map();
        return async (chat) => {
            if (!chat || chat.participantsCount != null || chat.className !== "Channel") return;
            const chave = String(chat.id);
            if (!cache.has(chave)) {
                cache.set(
                    chave,
                    cliente
                        .invoke(new Api.channels.GetFullChannel({ channel: chat }))
                        .then((completo) => (completo.fullChat && typeof completo.fullChat.participantsCount === "number" ? completo.fullChat.participantsCount : null))
                        .catch(() => null)
                );
            }
            const total = await cache.get(chave);
            if (total != null) chat.participantsCount = total;
        };
    }

    function tipoDoChat(chat) {
        return chat && chat.broadcast ? "canal" : "grupo";
    }

    function secaoDeResultado(corpo, titulo) {
        const bloco = document.createElement("div");
        bloco.style.cssText = "margin-top:14px;";
        const cabecalho = document.createElement("div");
        cabecalho.style.cssText = "color:#a3aab8;font-weight:600;margin-bottom:4px;";
        cabecalho.textContent = titulo;
        const status = document.createElement("div");
        status.style.cssText = "color:#a3aab8;font-size:13px;margin-bottom:4px;white-space:pre-line;";
        const lista = document.createElement("div");
        bloco.appendChild(cabecalho);
        bloco.appendChild(status);
        bloco.appendChild(lista);
        corpo.appendChild(bloco);
        return { bloco, cabecalho, status, lista, titulo };
    }

    function linhaSimples(lista, html, extra) {
        const linha = document.createElement("div");
        linha.style.cssText = "padding:6px 0;border-bottom:1px solid #2a2f3a;font-size:13px;";
        linha.innerHTML = html;
        if (extra) linha.appendChild(extra);
        lista.appendChild(linha);
        return linha;
    }

    // messages.searchGlobal (rodada 5, conferido com core.telegram.org/
    // method/messages.searchGlobal e /api/offsets): 1a pagina com
    // offset_rate 0, offset_peer vazio e offset_id 0; as seguintes com
    // offset_rate = next_rate da resposta (messages.messagesSlice) e
    // offset_peer/offset_id = chat e id da ULTIMA mensagem recebida.
    // Filtro so grupos / so canais / so conversas privadas: groups_only,
    // broadcasts_only, users_only (um de cada vez).
    function parametrosDaBuscaGlobal(termo, tipo, cursor) {
        const parametros = { q: termo, filter: new Api.InputMessagesFilterEmpty({}), minDate: 0, maxDate: 0, limit: 50, ...cursor };
        if (tipo === "grupos") parametros.groupsOnly = true;
        else if (tipo === "canais") parametros.broadcastsOnly = true;
        else if (tipo === "privados") parametros.usersOnly = true;
        return parametros;
    }

    // Proximo cursor, ou null se acabou. messages.messages = veio tudo;
    // messagesSlice traz "count" (total no servidor): acabou quando ja
    // recebeu isso ou a pagina veio vazia. Sem next_rate (nao deveria
    // acontecer num slice), usa a data da ultima mensagem.
    function proximaPaginaDaBuscaGlobal(resposta, recebidasAteAgora, peerDaUltima) {
        const todas = resposta.messages || [];
        const ultima = todas[todas.length - 1];
        if (!ultima || resposta.className === "messages.Messages") return null;
        if (typeof resposta.count === "number") {
            if (recebidasAteAgora >= resposta.count) return null;
        } else if (todas.length < 50) return null;
        return {
            offsetRate: resposta.nextRate || ultima.date,
            offsetPeer: peerDaUltima(ultima) || new Api.InputPeerEmpty({}),
            offsetId: ultima.id,
        };
    }

    async function telaBuscaAvancada(pedido) {
        if (!permite("busca_servidor")) return telaRecursoPago("Buscar no Telegram", "busca_servidor");
        definirTituloTela("Buscar");
        const corpo = corpoDoPainel();
        botaoVoltar(corpo);
        abasDaTela(corpo, "buscar", ABAS_BUSCAR, "telegram");
        const db = await abrirBanco();

        // ---------- 1. link ----------
        const tituloLink = document.createElement("div");
        tituloLink.style.cssText = "color:#a3aab8;font-weight:600;margin-bottom:6px;display:flex;align-items:center;gap:4px;";
        tituloLink.innerHTML =
            "<span>Conferir link do Telegram</span>" +
            criarIconeInfoHtml(
                'Digite só o final do link (ex.: "nomedocanal", "nomedocanal/123", "+convite", "c/123456/789") ou cole o link inteiro, @usuário, tg://..., ou vários de uma vez. Diz se é canal, grupo ou pessoa, título, membros, se o convite ainda vale e, em link de mensagem, se ela existe e se está salva no painel (com as reações de lá e daqui). NÃO entra em nada.'
            );
        corpo.appendChild(tituloLink);
        const linhaLink = document.createElement("div");
        linhaLink.style.cssText = "display:flex;align-items:stretch;margin-bottom:6px;";
        const prefixo = document.createElement("span");
        prefixo.textContent = "https://t.me/";
        prefixo.style.cssText = "background:#2a2f3a;color:#a3aab8;border:1px solid #2a2f3a;border-radius:6px 0 0 6px;padding:8px;font-size:13px;white-space:nowrap;";
        const campoLink = document.createElement("input");
        campoLink.type = "text";
        campoLink.placeholder = "nomedocanal/123";
        campoLink.style.cssText = ESTILO_CAMPO + "flex:1;min-width:0;border-radius:0 6px 6px 0;padding:8px;";
        linhaLink.appendChild(prefixo);
        linhaLink.appendChild(campoLink);
        corpo.appendChild(linhaLink);
        const botaoLink = botaoAcao(corpo, "Conferir link");
        const resultadoLink = document.createElement("div");
        resultadoLink.style.cssText = "margin-top:6px;";
        corpo.appendChild(resultadoLink);

        // Colou o link inteiro: o campo fica so com o final (o prefixo ja
        // esta na tela). Varios links: deixa como colou.
        const normalizarCampo = () => {
            const links = normalizarLinksDigitados(campoLink.value);
            if (links.length === 1) campoLink.value = links[0];
            return links;
        };
        campoLink.addEventListener("paste", () => setTimeout(normalizarCampo, 0));
        campoLink.addEventListener("change", normalizarCampo);

        async function conferirUmLink(sufixo) {
            const caixa = document.createElement("div");
            caixa.style.cssText = "border:1px solid #2a2f3a;border-radius:6px;padding:8px;margin-bottom:8px;font-size:13px;white-space:pre-line;";
            const endereco = "https://t.me/" + sufixo;
            caixa.textContent = endereco + " - conferindo...";
            resultadoLink.appendChild(caixa);
            const link = analisarLinkTelegram(endereco);
            if (!link) {
                caixa.textContent = endereco + "\nNão reconheci esse link (o que vem depois de t.me/ precisa ser um @usuário, +convite, joinchat/..., c/<id>/<msg> ou usuário/<msg>).";
                caixa.style.color = CORES.alerta;
                return;
            }
            const ctx = { sinal: null, maximoSegundosDePausa: 120, aoPausa: (s) => s && (caixa.textContent = endereco + "\nTelegram pediu pausa de " + s + "s...") };
            try {
                const r = await examinarLinkTelegram(link, ctx);
                caixa.textContent = endereco + "\n" + r.texto;
                caixa.appendChild(document.createElement("br"));
                const acoes = document.createElement("div");
                acoes.style.cssText = "display:flex;gap:6px;flex-wrap:wrap;margin-top:4px;";
                caixa.appendChild(acoes);
                if (link.tipo !== "privado") acoes.appendChild(criarLinkExterno("abrir no Telegram", endereco, ESTILO_BOTAO_PEQUENO));
                if (r.entidade && r.entidade.className === "User" && !r.entidade.bot) {
                    const id = String(r.entidade.id);
                    const botao = botaoPequeno(acoes, estaMonitorado(id) ? "Já monitorado" : "Monitorar esta pessoa", async () => {
                        atualizarRemetente(db, id, r.entidade);
                        await descarregarEscritasPendentes(db);
                        botao.textContent = (await adicionarMonitorado(db, { id, tipo: "pessoa" })) ? "Monitorando (veja em Monitorados)" : "Já monitorado";
                        botao.disabled = true;
                    });
                    if (estaMonitorado(id)) botao.disabled = true;
                }
                if (r.messageId && r.chatId) await compararComOSalvo(caixa, acoes, r);
            } catch (erro) {
                caixa.textContent = endereco + "\nNão deu pra conferir: " + mensagemDoErro(erro);
                caixa.style.color = "#ff6b6b";
            }
        }

        // O antigo "Verificar mensagem": a mensagem do link esta salva? O
        // texto ou as reacoes mudaram? Oferece salvar/atualizar na hora.
        async function compararComOSalvo(caixa, acoes, r) {
            const key = r.chatId + ":" + r.messageId;
            const local = await buscarMensagem(db, key).catch(() => null);
            const localComIndice = local ? comVistoDoIndice(db, local) : null;
            const linhas = [];
            if (!localComIndice) linhas.push("No painel: NÃO está salva" + (buscarChat(db, r.chatId) ? " (o grupo está no scan - buraco do scan ou mensagem nova)" : " (grupo fora do scan)") + ".");
            else linhas.push("No painel: salva, " + (localComIndice.reactionTotal || 0) + " reações" + (textoDasReacoes(localComIndice) ? " (" + textoDasReacoes(localComIndice) + ")" : "") + ".");
            if (r.mensagem) {
                const aoVivo = extrairReacoes(r.mensagem);
                linhas.push("No Telegram agora: " + aoVivo.total + " reações" + (aoVivo.minhasReacoes.length ? ", você reagiu com " + aoVivo.minhasReacoes.join(" ") : "") + ".");
                if (localComIndice && normalizarTexto(localComIndice.texto || "") !== normalizarTexto(textoCompleto(r.mensagem))) linhas.push("O texto salvo é diferente do atual (editada depois do scan).");
            }
            const nota = document.createElement("div");
            nota.style.cssText = "color:#a3aab8;margin-top:4px;";
            nota.textContent = linhas.join("\n");
            caixa.appendChild(nota);
            if (r.mensagem && buscarChat(db, r.chatId)) {
                const botao = botaoPequeno(acoes, localComIndice ? "Atualizar o salvo com o de agora" : "Salvar no painel agora", async () => {
                    const titulo = (buscarChat(db, r.chatId) || {}).chatTitle || r.chatId;
                    await salvarMensagem(db, montarRegistroDoScan(db, r.chatId, titulo, r.mensagem));
                    botao.textContent = "Salvo";
                    botao.disabled = true;
                });
            }
        }

        const conferirLinks = async () => {
            const links = normalizarCampo();
            resultadoLink.innerHTML = "";
            if (!links.length) {
                textoAviso(resultadoLink, "Digite o final do link (ou cole o link).", "#ff6b6b");
                return;
            }
            botaoLink.disabled = true;
            try {
                for (const sufixo of links.slice(0, 20)) await conferirUmLink(sufixo);
                if (links.length > 20) textoAviso(resultadoLink, "Conferi os 20 primeiros (de " + links.length + ").");
                // Rodada 7 (descoberta): na hora em que a pessoa confere um
                // link na mao, conta que da pra fazer direto na conversa -
                // so enquanto a ferramenta estiver desligada.
                if (typeof ferramentaLinksLigada === "function" && !ferramentaLinksLigada()) {
                    const dica = document.createElement("div");
                    dica.className = "trp-dica-alt-link";
                    dica.style.cssText = "display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:13px;color:" + CORES.textoSecundario + ";margin-top:4px;";
                    dica.appendChild(Object.assign(document.createElement("span"), { textContent: "Atalho: com \"Alt+clique num link t.me\" ligado, dá pra conferir direto na conversa, sem copiar o link." }));
                    botaoPequeno(dica, "Ligar", () => {
                        ligarFerramentaLinks(true);
                        dica.textContent = "Ligado. Segure Alt e clique num link t.me na conversa (desliga em Ajustes > Ferramentas).";
                    });
                    resultadoLink.appendChild(dica);
                }
            } finally {
                botaoLink.disabled = false;
            }
        };
        botaoLink.addEventListener("click", conferirLinks);
        campoLink.addEventListener("keydown", (ev) => {
            if (ev.key === "Enter") conferirLinks();
        });

        // ---------- 2. palavra-chave ----------
        const tituloBusca = document.createElement("div");
        tituloBusca.style.cssText = "color:#a3aab8;font-weight:600;margin:18px 0 6px;display:flex;align-items:center;gap:4px;";
        tituloBusca.innerHTML =
            "<span>Buscar por palavra-chave (tudo de uma vez)</span>" +
            criarIconeInfoHtml(
                'Uma busca só junta: grupos, canais e pessoas pelo NOME; posts de canais públicos (por hashtag sempre; por texto livre só quando o Telegram libera de graça pra esta conta - senão a tela explica e oferece pagar em Stars, nunca sozinho); os links t.me citados nesses posts (conferidos); e as mensagens das SUAS conversas no servidor (inclusive grupo que não está no scan). Várias hashtags: separe por ";". O que entra e os filtros ficam guardados (em "Opções e filtros" desta aba).'
            );
        corpo.appendChild(tituloBusca);
        const campoBusca = campoTexto(corpo, 'Palavra, nome ou hashtag (várias hashtags: "a;b;c")', "text", (pedido && pedido.termo) || "");
        const historicoBuscaGlobal = ligarHistoricoBusca(campoBusca, CHAVE_HISTORICO_BUSCA_GLOBAL);

        // Opcoes no bloco recolhivel (aberto/fechado guardado - rodada 6).
        const opcoes = blocoRecolhivel(corpo, "buscar_telegram", "Opções e filtros");
        const nomesDasOpcoes = preferenciasDaSecao("busca_avancada").map((p) => p.nome);
        controlesDasPreferencias(opcoes, nomesDasOpcoes);
        opcoes.mostrarFiltrosAtivos(nomesDasOpcoes);
        for (const campo of opcoes.querySelectorAll ? opcoes.querySelectorAll("[data-preferencia]") : []) campo.addEventListener("change", () => opcoes.mostrarFiltrosAtivos(nomesDasOpcoes));

        const barra = document.createElement("div");
        barra.style.cssText = "display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;";
        opcoes.appendChild(barra);
        botaoHistoricoDeBuscas(barra);
        botaoPadraoDaTela(barra, nomesDasOpcoes, () => telaBuscaAvancada());
        botaoSalvarBusca(barra, db, "avancada", () => campoBusca.value.trim(), preferenciasDaSecao("busca_avancada").map((p) => p.nome));
        const botaoBuscar = botaoAcao(corpo, "Buscar");
        const resultados = document.createElement("div");
        corpo.appendChild(resultados);

        async function executar() {
            const termo = campoBusca.value.trim();
            resultados.innerHTML = "";
            if (!termo) {
                textoAviso(resultados, "Digite algo pra buscar.", "#ff6b6b");
                return;
            }
            historicoBuscaGlobal.registrar(termo);
            botaoBuscar.disabled = true;
            try {
                await buscarPorNome(termo);
                if (lerPreferencia("ba_posts_publicos")) await buscarPostsPublicos(termo);
                if (lerPreferencia("ba_suas_conversas")) await buscarNasSuasConversas(termo);
            } finally {
                botaoBuscar.disabled = false;
            }
        }
        botaoBuscar.addEventListener("click", executar);
        campoBusca.addEventListener("keydown", (ev) => {
            if (ev.key === "Enter") executar();
        });

        const garantirMembros = criarBuscadorDeMembros();
        const ordenarChats = async (chats) => {
            const minimo = lerPreferencia("ba_minimo_membros");
            if (minimo > 0 || lerPreferencia("ba_ordenar") === "membros") await emParaleloLimitado(chats, 4, garantirMembros);
            let lista = chats.filter((c) => !minimo || (c.participantsCount || 0) >= minimo);
            if (lerPreferencia("ba_ordenar") === "membros") lista = [...lista].sort((a, b) => (b.participantsCount ?? -1) - (a.participantsCount ?? -1));
            return lista;
        };

        // 2a. nome
        async function buscarPorNome(termo) {
            const secao = secaoDeResultado(resultados, "Grupos, canais e pessoas pelo nome");
            secao.status.textContent = "Buscando...";
            try {
                const r = await cliente.invoke(new Api.contacts.Search({ q: termo.replace(/^[@#]/, ""), limit: 30 }));
                const tipo = lerPreferencia("ba_tipo");
                const chats = (r.chats || []).filter((c) => tipo === "todos" || tipo === tipoDoChat(c));
                const pessoas = tipo === "todos" || tipo === "pessoa" ? (r.users || []).filter((u) => !u.self) : [];
                const ordenados = tipo === "pessoa" ? [] : await ordenarChats(chats);
                secao.status.textContent = ordenados.length + " grupo(s)/canal(is), " + pessoas.length + " pessoa(s)";
                for (const chat of ordenados) {
                    const usuario = chat.username ? "@" + chat.username : null;
                    const linha = linhaSimples(
                        secao.lista,
                        '<span style="color:#4da3ff;">[' + tipoDoChat(chat) + "]</span> " + escapeHtml(chat.title || String(chat.id)) + (usuario ? " (" + escapeHtml(usuario) + ")" : "") +
                            (chat.participantsCount != null ? ' <span style="color:#a3aab8;">- ' + chat.participantsCount + " membros</span>" : "") +
                            (buscarChat(db, "-100" + chat.id) ? ' <span style="color:#5ec26a;">- já está no scan</span>' : "")
                    );
                    if (usuario) linha.appendChild(criarLinkExterno(" abrir", "https://t.me/" + encodeURIComponent(chat.username), "color:#4da3ff;font-size:13px;"));
                }
                for (const u of pessoas) {
                    const id = String(u.id);
                    const linha = linhaSimples(
                        secao.lista,
                        '<span style="color:#a3aab8;">[' + (u.bot ? "bot" : "pessoa") + "]</span> " + escapeHtml(nomeDaEntidade(u)) + (u.username ? " (@" + escapeHtml(u.username) + ")" : "") + " - id " + id
                    );
                    if (!u.bot) {
                        const botao = botaoPequeno(linha, estaMonitorado(id) ? "Já monitorado" : "Monitorar", async () => {
                            atualizarRemetente(db, id, u);
                            await descarregarEscritasPendentes(db);
                            botao.textContent = (await adicionarMonitorado(db, { id, tipo: "pessoa" })) ? "Monitorando" : "Já monitorado";
                            botao.disabled = true;
                        }, "margin-left:6px;");
                        if (estaMonitorado(id)) botao.disabled = true;
                    }
                }
                if (!ordenados.length && !pessoas.length) secao.status.textContent = "Nada com esse nome.";
            } catch (erro) {
                secao.status.textContent = "Erro: " + mensagemDoErro(erro);
                secao.status.style.color = "#ff6b6b";
            }
        }

        // 2b. posts publicos (+ links achados neles)
        async function buscarPostsPublicos(termoBruto) {
            const secao = secaoDeResultado(resultados, "Posts de canais públicos");
            const secaoLinks = lerPreferencia("ba_verificar_links") ? secaoDeResultado(resultados, "Links t.me citados nesses posts (conferidos)") : null;
            const linksVistos = new Map();
            const termos = [];
            for (const parte of termoBruto.split(";")) {
                const limpo = parte.trim().replace(/^#/, "");
                if (limpo && !termos.some((t) => t.toLowerCase() === limpo.toLowerCase())) termos.push(limpo);
                if (termos.length >= 10) break;
            }
            const umTermoSo = termos.length === 1;
            // Texto livre: so com cota gratis (ou Premium). Senao explica.
            let usarTextoLivre = false;
            let cota = null;
            if (umTermoSo) {
                try {
                    cota = await cliente.invoke(new Api.channels.CheckSearchPostsFlood({ query: termos[0] }));
                    usarTextoLivre = !!(cota.queryIsFree || cota.remains > 0);
                } catch (erro) {
                    cota = null;
                }
            }
            const acumulados = [];
            const vistos = new Set();
            const avisos = [];
            const pedir = async (parametros, rotulo) => {
                const resposta = await cliente.invoke(new Api.channels.SearchPosts({ offsetRate: 0, offsetPeer: new Api.InputPeerEmpty({}), offsetId: 0, limit: 30, ...parametros }));
                const chatsPorId = new Map((resposta.chats || []).map((c) => [String(c.id), c]));
                for (const m of resposta.messages || []) {
                    const idCanal = m.peerId && m.peerId.channelId != null ? String(m.peerId.channelId) : "?";
                    const chave = idCanal + ":" + m.id;
                    if (vistos.has(chave)) continue;
                    vistos.add(chave);
                    const links = extrairLinksTelegram(m.message);
                    if (lerPreferencia("ba_so_com_link") && !links.length) continue;
                    acumulados.push({ m, chat: chatsPorId.get(idCanal) || null, rotulo, links });
                }
            };
            secao.status.textContent = "Buscando...";
            for (const termo of termos) {
                const hashtag = termo.replace(/\s+/g, "");
                try {
                    await pedir({ hashtag }, "#" + hashtag);
                } catch (erro) {
                    avisos.push("#" + hashtag + ": " + mensagemDoErro(erro));
                }
            }
            if (umTermoSo) {
                if (usarTextoLivre) {
                    try {
                        await pedir({ query: termos[0] }, "texto");
                    } catch (erro) {
                        avisos.push(/PREMIUM_ACCOUNT_REQUIRED/i.test(mensagemDoErro(erro)) ? "Texto livre: o Telegram exigiu conta Premium." : "Texto livre: " + mensagemDoErro(erro));
                    }
                } else {
                    avisos.push(
                        "Texto livre em posts públicos NÃO foi buscado: o Telegram só libera essa busca pra conta Premium ou com cota grátis do dia" +
                            (cota && cota.totalDaily != null ? " (cota de hoje: " + (cota.remains ?? 0) + " de " + cota.totalDaily + ")" : "") +
                            ". Busquei pela hashtag #" + termos[0].replace(/\s+/g, "") + " (sempre grátis)."
                    );
                    if (cota && cota.starsAmount) {
                        const botaoPagar = botaoPequeno(secao.bloco, "Pagar " + cota.starsAmount + " Stars e buscar o texto livre mesmo assim", async () => {
                            botaoPagar.disabled = true;
                            try {
                                await pedir({ query: termos[0], allowPaidStars: cota.starsAmount }, "texto (pago)");
                                await desenhar();
                                botaoPagar.textContent = "Feito";
                            } catch (erro) {
                                botaoPagar.textContent = "Erro: " + mensagemDoErro(erro);
                            }
                        }, "border:1px solid #ff6b6b;color:#ff6b6b;margin-top:4px;");
                    }
                }
            }
            async function desenhar() {
                if (lerPreferencia("ba_ordenar") === "membros" || lerPreferencia("ba_minimo_membros") > 0) await emParaleloLimitado(acumulados, 4, (item) => garantirMembros(item.chat));
                const minimo = lerPreferencia("ba_minimo_membros");
                let itens = acumulados.filter((i) => !minimo || (i.chat && (i.chat.participantsCount || 0) >= minimo));
                if (lerPreferencia("ba_ordenar") === "membros") itens = [...itens].sort((a, b) => ((b.chat && b.chat.participantsCount) ?? -1) - ((a.chat && a.chat.participantsCount) ?? -1));
                else if (lerPreferencia("ba_ordenar") === "data") itens = [...itens].sort((a, b) => b.m.date - a.m.date);
                secao.lista.innerHTML = "";
                secao.status.textContent = itens.length + " post(s)" + (avisos.length ? "\n" + avisos.join("\n") : "");
                for (const { m, chat, rotulo, links } of itens) {
                    const titulo = (chat && chat.title) || "canal/grupo";
                    const usuario = chat && chat.username;
                    const reacoes = extrairReacoes(m).total;
                    const linha = linhaSimples(
                        secao.lista,
                        '<div style="color:#4da3ff;font-weight:600;">' + escapeHtml(titulo) + " (" + tipoDoChat(chat) + ")</div>" +
                            '<div style="color:#a3aab8;font-size:13px;">' +
                            escapeHtml([usuario ? "@" + usuario : null, chat && chat.participantsCount != null ? chat.participantsCount + " membros" : null, reacoes ? reacoes + " reações" : null, dataIso(m).slice(0, 10), termos.length > 1 || rotulo !== "#" + termos[0] ? rotulo : null].filter(Boolean).join(" - ")) +
                            "</div><div>" + escapeHtml(truncar((m.message || "").trim(), 200)) + "</div>"
                    );
                    if (usuario) linha.appendChild(criarLinkExterno("abrir o post", "https://t.me/" + encodeURIComponent(usuario) + "/" + m.id, "display:block;color:#4da3ff;font-size:13px;margin-top:4px;"));
                    if (secaoLinks) for (const link of links) if (linksVistos.size < 20 || linksVistos.has((link.ehConvite ? "convite:" : "usuario:") + link.valor.toLowerCase())) criarItemDeLink(link, secaoLinks.lista, linksVistos);
                }
                if (secaoLinks) secaoLinks.status.textContent = linksVistos.size ? linksVistos.size + " link(s)" + (linksVistos.size >= 20 ? " (até 20 por busca)" : "") : "Nenhum link t.me nos posts.";
            }
            await desenhar();
        }

        // 2c. suas conversas (servidor)
        async function buscarNasSuasConversas(termo) {
            const secao = secaoDeResultado(resultados, "Nas suas conversas (servidor, todos os chats da conta)");
            let cursor = { offsetRate: 0, offsetPeer: new Api.InputPeerEmpty({}), offsetId: 0 };
            let recebidas = 0;
            let total = 0;
            let novasSalvas = 0;
            const carregar = async () => {
                secao.status.textContent = "Buscando...";
                try {
                    const r = await cliente.invoke(new Api.messages.SearchGlobal(parametrosDaBuscaGlobal(termo, lerPreferencia("ba_conversas_tipo"), cursor)));
                    const chatsPorId = new Map();
                    for (const c of r.chats || []) chatsPorId.set(c.className === "Channel" ? "-100" + c.id : "-" + c.id, c);
                    for (const u of r.users || []) chatsPorId.set(String(u.id), u);
                    const chatIdDoPeer = (p) => (p.channelId != null ? "-100" + p.channelId : p.chatId != null ? "-" + p.chatId : p.userId != null ? String(p.userId) : null);
                    const todas = r.messages || [];
                    const mensagens = todas.filter((m) => m.className === "Message");
                    for (const m of mensagens) {
                        const p = m.peerId || {};
                        const chatId = p.channelId != null ? "-100" + p.channelId : p.chatId != null ? "-" + p.chatId : p.userId != null ? String(p.userId) : null;
                        if (!chatId) continue;
                        const chat = chatsPorId.get(chatId);
                        const titulo = (buscarChat(db, chatId) || {}).chatTitle || (chat && chat.title) || "conversa " + chatId;
                        const noScan = !!buscarChat(db, chatId);
                        let registro = { key: chatId + ":" + m.id, chatId, messageId: m.id, dateUtc: dataIso(m), texto: textoCompleto(m), chatTitle: titulo };
                        aplicarDadosDaMensagem(registro, m);
                        // Grupo do scan: grava (nova entra, ja salva tem as
                        // reacoes atualizadas - mesma ideia da busca ao vivo).
                        if (noScan) {
                            registro = montarRegistroDoScan(db, chatId, titulo, m);
                            if (!db.indice.has(registro.key)) {
                                novasSalvas++;
                                registro.achadoNoServidor = true;
                            }
                            await salvarMensagem(db, registro, { adiarGravacao: true });
                        }
                        total++;
                        const item = criarItemDeMensagem(db, { ...registro, visto: noScan ? (db.indice.get(registro.key) || {}).visto : false }, {
                            titulo: registro.dateUtc.slice(0, 10) + " - " + titulo + (noScan ? "" : " (fora do scan)"),
                            texto: registro.texto,
                            tamanhoTexto: 200,
                            semMonitorar: !noScan,
                        });
                        secao.lista.appendChild(item);
                    }
                    await descarregarEscritasPendentes(db);
                    // Pagina pela ULTIMA mensagem devolvida (inclusive de
                    // servico) e pelo peer dela - conversa privada inclusa.
                    recebidas += todas.length;
                    const proxima = proximaPaginaDaBuscaGlobal(r, recebidas, (ultima) => {
                        const chat = chatsPorId.get(chatIdDoPeer(ultima.peerId || {}));
                        return chat ? inputPeerDoChat(chat) : null;
                    });
                    const temMais = !!proxima;
                    if (temMais) cursor = proxima;
                    secao.status.textContent =
                        total + " mensagem(ns)" + (typeof r.count === "number" ? " de " + r.count + " no servidor" : "") +
                        (novasSalvas ? " - " + novasSalvas + " de grupos do scan que faltavam foram salvas agora" : "") + (temMais ? "" : " (fim)");
                    const antigo = secao.bloco.querySelector && secao.bloco.querySelector(".trp-mais-conversas");
                    if (antigo) antigo.remove();
                    if (temMais) {
                        const mais = botaoAcao(secao.bloco, "Carregar mais");
                        mais.className = "trp-mais-conversas";
                        mais.addEventListener("click", () => {
                            mais.remove();
                            carregar();
                        });
                    }
                } catch (erro) {
                    secao.status.textContent = "Erro: " + mensagemDoErro(erro);
                    secao.status.style.color = "#ff6b6b";
                }
            };
            await carregar();
        }

        if (pedido && pedido.executar && campoBusca.value.trim()) executar();
    }

    function escapeHtml(texto) {
        const div = document.createElement("div");
        div.textContent = texto == null ? "" : texto;
        return div.innerHTML;
    }

    // Na linha abaixo montar_userscript.mjs insere ferramentas_fundo.js
    // (dentro desta funcao, sem variavel global nova).
    // ==== Configuracao do build PESSOAL (produto P1) ====
    //
    // Mesmos valores que estavam fixos no codigo ate a 2026.10.14.7: o build
    // pessoal tem que se comportar igual ao de antes. O build do produto usa
    // config_produto.js (mesmos campos). Ver montagem.mjs.
    const CONFIG = {
        alvo: "pessoal",
        nomeProduto: "TLGMaster",
        // Nome do "aparelho" mandado no login (aparece em Dispositivos).
        nomeDoAparelho: "Painel Gestor TLGR",
        contatoSuporte: "",
        servidorLicenca: "",
        // Caminho no Windows da pasta de dados (o navegador nao revela;
        // sugestao pro instalador do ajudante). Padrao do build pessoal.
        caminhoPastaDadosWindows: "C:\\Projetos\\PROJETOS_MAESTRO\\TELEGRAM_TOP_REACOES\\Armazenamento_APP",
        pastaDownloads: "Downloads_TLGR",
        pastaSugerida: "",
        // Pessoal nao aplica limites de plano (tudo liberado).
        aplicarLimites: false,
        // Etapa P4: codigo principal ao lado do carregador no repositorio
        // publico TLGR-TR-painel (ver docs/CARREGADOR.md).
        enderecoDoCodigoPrincipal: "https://raw.githubusercontent.com/lohrangm/TLGR-TR-painel/main/principal/painel_principal-{versao}.js",
        // Primeiro uso (boas-vindas em passos) e assistente da chave de API
        // em my.telegram.org: so no produto.
        boasVindas: false,
        assistenteChaveApi: false,
        planos: null, // sem limites de plano
        linksTutorial: {},
    };
    // ==== Fim da configuracao ====

    // ==== Preferencias do usuario (rodada 4) ====
    //
    // Toda caixinha, seletor, limite e filtro das telas fica guardado aqui,
    // no armazenamento do Tampermonkey (GM_setValue), com a chave
    // "trp_pref_<nome>". Antes cada tela comecava do zero a cada abertura
    // ("Ocultar vistos" voltava desmarcado sempre). Padrao unico:
    //   1. a preferencia e declarada uma vez (definirPreferencia) com secao,
    //      valor padrao e tipo;
    //   2. a tela liga o controle a ela (ligarCampoAPreferencia,
    //      quadradoDaPreferencia) - o valor salvo entra na criacao e cada
    //      mudanca e gravada na hora;
    //   3. cada tela mostra as suas no bloco "Opcoes e filtros", com "Voltar ao padrao".
    // Valor salvo invalido (tipo errado, fora do limite, opcao que nao
    // existe mais) cai no padrao, nunca quebra a tela.

    const PREFIXO_PREFERENCIA = "trp_pref_";
    const PREFERENCIAS = new Map(); // nome -> { nome, secao, padrao, tipo, rotulo, opcoes, min, max, naTelaDeConfig }

    const SECOES_DE_PREFERENCIAS = [
        { id: "listas", titulo: "Mais reagidas e Buscar > No que escaneei" },
        { id: "busca_avancada", titulo: "Buscar > No Telegram" },
        { id: "scan", titulo: "Scan e download em lote" },
        { id: "downloads", titulo: "Downloads" },
        { id: "monitorados", titulo: "Monitorados" },
    ];

    function definirPreferencia(nome, definicao) {
        PREFERENCIAS.set(nome, { nome, tipo: typeof definicao.padrao === "boolean" ? "booleano" : typeof definicao.padrao === "number" ? "numero" : "texto", naTelaDeConfig: true, ...definicao });
    }

    function valorValido(definicao, valor) {
        if (valor === undefined || valor === null) return definicao.padrao;
        if (definicao.tipo === "booleano") return valor === true || valor === false ? valor : definicao.padrao;
        if (definicao.tipo === "numero") {
            const numero = Number(valor);
            if (!isFinite(numero) || valor === "") return definicao.padrao;
            const minimo = definicao.min != null ? definicao.min : -Infinity;
            const maximo = definicao.max != null ? definicao.max : Infinity;
            return Math.min(maximo, Math.max(minimo, Math.round(numero)));
        }
        const texto = typeof valor === "string" ? valor : String(valor);
        if (definicao.opcoes && !definicao.opcoes.some((o) => o.valor === texto)) return definicao.padrao;
        return texto;
    }

    function lerPreferencia(nome) {
        const definicao = PREFERENCIAS.get(nome);
        if (!definicao) throw new Error("preferência não declarada: " + nome);
        return valorValido(definicao, GM_getValue(PREFIXO_PREFERENCIA + nome, undefined));
    }

    function gravarPreferencia(nome, valor) {
        const definicao = PREFERENCIAS.get(nome);
        if (!definicao) throw new Error("preferência não declarada: " + nome);
        GM_setValue(PREFIXO_PREFERENCIA + nome, valorValido(definicao, valor));
    }

    function preferenciasDaSecao(secao) {
        return [...PREFERENCIAS.values()].filter((p) => p.secao === secao);
    }

    // "Voltar ao padrao" de uma secao: grava o padrao de cada preferencia
    // dela (o armazenamento do Tampermonkey nao tem "apagar" liberado
    // neste script - so GM_setValue/GM_getValue).
    function voltarSecaoAoPadrao(secao) {
        for (const definicao of preferenciasDaSecao(secao)) GM_setValue(PREFIXO_PREFERENCIA + definicao.nome, definicao.padrao);
        for (const extra of aoVoltarSecaoAoPadrao) {
            try {
                extra(secao);
            } catch (erro) {
                console.warn("[TLGMaster] voltar ao padrão:", erro);
            }
        }
    }
    const aoVoltarSecaoAoPadrao = []; // ferramentas/monitorados que guardam config fora deste registro

    // Liga um <select>/<input> a uma preferencia: valor salvo na criacao,
    // cada mudanca gravada na hora. Select de grupo (opcoes que mudam):
    // se o grupo salvo nao existe mais na lista, fica em "Todos".
    function ligarCampoAPreferencia(campo, nome) {
        if (campo.dataset) campo.dataset.preferencia = nome;
        const valor = lerPreferencia(nome);
        campo.value = valor === null || valor === undefined ? "" : String(valor);
        if (campo.tagName === "SELECT" && campo.value !== String(valor)) campo.value = "";
        const gravar = () => gravarPreferencia(nome, campo.type === "number" ? (campo.value === "" ? null : Number(campo.value)) : campo.value);
        campo.addEventListener("change", gravar);
        return campo;
    }

    // Select cujas opcoes chegam depois (ex.: grupos do scan, carregados
    // da rede): aplica o valor salvo quando as opcoes ja estiverem la.
    function aplicarPreferenciaNoSelect(select, nome) {
        const valor = String(lerPreferencia(nome));
        if ([...select.options].some((o) => o.value === valor)) select.value = valor;
    }

    function quadradoDaPreferencia(nome, aoAlternar) {
        return criarQuadradoMarcavel(lerPreferencia(nome), (marcado) => {
            gravarPreferencia(nome, marcado);
            if (aoAlternar) aoAlternar(marcado);
        });
    }

    // Linha "caixinha + texto + i" ligada a uma preferencia.
    function linhaDeQuadrado(corpo, nome, rotulo, info, aoAlternar) {
        const bloco = document.createElement("div");
        bloco.style.cssText = "display:flex;align-items:center;gap:8px;margin-bottom:10px;font-size:13px;";
        const quadrado = quadradoDaPreferencia(nome, aoAlternar);
        const texto = document.createElement("span");
        texto.style.cssText = "color:#a3aab8;display:flex;align-items:center;gap:4px;";
        texto.innerHTML = "<span>" + escapeHtml(rotulo) + "</span>" + (info ? criarIconeInfoHtml(info) : "");
        bloco.appendChild(quadrado.elemento);
        bloco.appendChild(texto);
        corpo.appendChild(bloco);
        return quadrado;
    }

    // ---- declaracoes ----
    const OPCOES_ORDENAR = [
        { valor: "reacoes", rotulo: "Mais reações" },
        { valor: "data", rotulo: "Mais recentes" },
    ];
    // Listas
    definirPreferencia("itens_por_pagina", { secao: "listas", padrao: 50, min: 10, max: 500, rotulo: "Itens por página (Top reações, Minhas reações, Monitorados; Buscar > No que escaneei usa o dobro)" });
    definirPreferencia("top_grupo", { secao: "listas", padrao: "", rotulo: "Top reações: grupo", naTelaDeConfig: false });
    definirPreferencia("top_ordenar", { secao: "listas", padrao: "reacoes", opcoes: OPCOES_ORDENAR, rotulo: "Top reações: ordenar por" });
