    definirPreferencia("top_data_ate", { secao: "listas", padrao: "", rotulo: "Top reações: até (data)", naTelaDeConfig: false });
    definirPreferencia("top_ocultar_vistos", { secao: "listas", padrao: false, rotulo: "Top reações: ocultar as já vistas" });
