    definirPreferencia("top_midia", { secao: "listas", padrao: "", rotulo: "Top reações: tipo de mídia", naTelaDeConfig: false });
    definirPreferencia("minhas_grupo", { secao: "listas", padrao: "", rotulo: "Minhas reações: grupo", naTelaDeConfig: false });
    definirPreferencia("minhas_data_de", { secao: "listas", padrao: "", rotulo: "Minhas reações: de", naTelaDeConfig: false });
    definirPreferencia("minhas_data_ate", { secao: "listas", padrao: "", rotulo: "Minhas reações: até", naTelaDeConfig: false });
    definirPreferencia("minhas_emoji", { secao: "listas", padrao: "", rotulo: "Minhas reações: só com esta reação", naTelaDeConfig: false });
    definirPreferencia("minhas_midia", { secao: "listas", padrao: "", rotulo: "Minhas reações: tipo de mídia", naTelaDeConfig: false });
    definirPreferencia("busca_emoji", { secao: "listas", padrao: "", rotulo: "No que escaneei: só com esta reação", naTelaDeConfig: false });
